# -*- coding: utf-8 -*-
"""
Задание №24 ОГЭ — геометрические задачи на доказательство.

Банк Школково (152 задачи) сводится к 25 принципиально разным сюжетам, они
перечислены в oge24_setup/TYPES.md («Сводка 2»). Здесь каждый сюжет — одна
функция: условие своими словами, доказательство по шагам и чертёж.

Почему это не генераторы в смысле №20-№22
-----------------------------------------
Доказать «биссектрисы углов A и B параллелограмма пересекаются в середине
CD» можно единственным способом — привести доказательство. Числа тут ни при
чём: у 22 сюжетов из 25 в условии их просто нет, варьировать можно только
буквы и зеркальную посадку чертежа, а это не вариативность. Настоящие числа
есть у двух сюжетов (трапеция с BD² = BC·AD и касательная к двум окружностям)
и частично у третьего (параллелограмм со стороной вдвое больше смежной) —
там они и генерируются.

Проверить доказательство машина не может, а режима «на проверку
преподавателю» в курсе ОГЭ нет — он живёт только в курсах с домашкой.
Поэтому режим у №24 свой: ученик думает, открывает доказательство и сам
отмечает, справился или нет. Платформа узнаёт этот режим по
answer_kind = 'proof' (см. views_exam.check_problem_answer).

Контракт функции сюжета
-----------------------
    @сюжет(N)
    def _сюжет_N(rng) -> dict

    {
      'title':          короткое название сюжета;
      'statement_html': условие. Своими словами, а не копия банка; формулы
                        в \\( \\); без слова «Докажите» в начале не обойтись;
      'proof_html':     доказательство по шагам, каждый шаг с обоснованием
                        (какая теорема или признак), HTML;
      'figure':         объект users.geom_svg.Чертёж или None; чертёж идёт
                        в разбор, а не в условие — на экзамене чертёж делает
                        ученик, и проверить свой рисунок он сможет по разбору;
      'facts':          список опорных фактов одной строкой каждый — они
                        выводятся под доказательством как «что нужно знать»;
      'params':         что угодно для отладки; у сюжетов с числами — сами
                        числа, чтобы проверка могла подставить их в
                        соотношение.
    }
"""

import math
import random
from fractions import Fraction
from math import acos, atan2, cos, degrees, gcd, hypot, radians, sin, sqrt

from .geom_svg import СТОРОНЫ, Чертёж

GENERATORS = {}


def сюжет(номер):
    def деко(func):
        GENERATORS[номер] = func
        func.номер = номер
        return func
    return деко


def generate(номер, seed=None):
    if номер not in GENERATORS:
        raise KeyError('нет сюжета %s' % номер)
    rng = random.Random(seed)
    task = GENERATORS[номер](rng)
    task['scenario'] = номер
    task['question_html'] = task['statement_html']
    return task


def solution_html(task):
    куски = ['<p><b>Доказательство.</b></p>', task['proof_html']]
    if task.get('figure') is not None:
        куски.append('<div class="graph">%s</div>' % task['figure'].готово())
    if task.get('facts'):
        куски.append('<p><b>На что опирается доказательство:</b></p><ul>'
                     + ''.join('<li>%s</li>' % f for f in task['facts'])
                     + '</ul>')
    return ''.join(куски)


def as_task(номер, seed=None):
    """Мост к платформе: users/generators/g<id>.py вызывает это."""
    task = generate(номер, seed)
    return {
        'condition_text': task['question_html'],
        # Ответа как числа нет. Строка ниже — метка самооценки: ученик после
        # разбора отмечает «справился», и это и есть «верный ответ».
        'correct_answer': 'solved',
        'answer_kind': 'proof',
        'multi_answer': False,
        'allow_fractions': False,
        'solution_html': solution_html(task),
        'oge24_scenario': номер,
        'title': task['title'],
    }


# ──────────────────────────────────────────────────────────────────────────
# Помощники для чертежей
# ──────────────────────────────────────────────────────────────────────────

def проекция(P, Q, R):
    """Основание перпендикуляра из R на прямую PQ."""
    px, py = P
    qx, qy = Q
    rx, ry = R
    ux, uy = qx - px, qy - py
    t = ((rx - px) * ux + (ry - py) * uy) / float(ux * ux + uy * uy)
    return (px + t * ux, py + t * uy)


def пересечение(A, B, C, D):
    """Точка пересечения прямых AB и CD."""
    x1, y1 = A
    x2, y2 = B
    x3, y3 = C
    x4, y4 = D
    зн = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if abs(зн) < 1e-12:
        raise ValueError('прямые параллельны')
    px = ((x1 * y2 - y1 * x2) * (x3 - x4) - (x1 - x2) * (x3 * y4 - y3 * x4)) / зн
    py = ((x1 * y2 - y1 * x2) * (y3 - y4) - (y1 - y2) * (x3 * y4 - y3 * x4)) / зн
    return (px, py)


def середина(A, B):
    return ((A[0] + B[0]) / 2.0, (A[1] + B[1]) / 2.0)


def подписать_вершины(ч, *пары):
    """ч.вершина для каждой тройки (точка, буква, сторона подписи)."""
    for p, буква, сторона in пары:
        ч.вершина(p, буква, сторона)


# ──────────────────────────────────────────────────────────────────────────
# Сюжет 1. Трапеция: диагональ — среднее геометрическое оснований
# ──────────────────────────────────────────────────────────────────────────
#
# Единственный сюжет банка с полностью генерируемыми числами. Основания BC и
# AD и диагональ BD связаны соотношением BD² = BC·AD; требуется доказать
# подобие треугольников CBD и BDA. Целые тройки получаются из
# BC = t·m², AD = t·n², BD = t·m·n при m < n: тогда BD² = t²m²n² = BC·AD
# автоматически, а трапеция не вырождается (BC ≠ AD).
#
# Доказательство — второй признак подобия: ∠CBD = ∠BDA как накрест лежащие
# при BC ∥ AD и секущей BD, а стороны при этих углах пропорциональны:
# BC/BD = BD/AD — это и есть переписанное условие BD² = BC·AD.

@сюжет(1)
def _сюжет_1(rng):
    while True:
        m = rng.randint(1, 4)
        n = rng.randint(m + 1, 6)
        t = rng.choice([1, 1, 2, 3])
        if gcd(m, n) == 1:
            break
    BC, AD, BD = t * m * m, t * n * n, t * m * n

    условие = (
        '<p>Основания \\(BC\\) и \\(AD\\) трапеции \\(ABCD\\) равны соответственно '
        '\\(%d\\) и \\(%d\\), \\(BD = %d\\). Докажите, что треугольники \\(CBD\\) и '
        '\\(BDA\\) подобны.</p>' % (BC, AD, BD))

    доказательство = (
        '<p>1. \\(BC \\parallel AD\\) как основания трапеции, \\(BD\\) — секущая. '
        'Значит \\(\\angle CBD = \\angle BDA\\) как накрест лежащие углы.</p>'
        '<p>2. Сравним стороны, прилежащие к этим углам. В треугольнике \\(CBD\\) '
        'угол \\(CBD\\) лежит между сторонами \\(BC\\) и \\(BD\\), в треугольнике '
        '\\(BDA\\) угол \\(BDA\\) — между \\(BD\\) и \\(DA\\). Составим отношения:</p>'
        '\\[\\frac{BC}{BD} = \\frac{%d}{%d} = \\frac{%s}{%s}, \\qquad '
        '\\frac{BD}{DA} = \\frac{%d}{%d} = \\frac{%s}{%s}.\\]'
        '<p>Отношения равны: \\(\\dfrac{BC}{BD} = \\dfrac{BD}{DA}\\) '
        '(это то же самое, что \\(BD^2 = BC \\cdot AD\\): \\(%d^2 = %d \\cdot %d = %d\\)).</p>'
        '<p>3. Две стороны треугольника \\(CBD\\) пропорциональны двум сторонам '
        'треугольника \\(BDA\\), а углы между ними равны. По второму признаку '
        'подобия \\(\\triangle CBD \\sim \\triangle BDA\\), что и требовалось.</p>'
        % (BC, BD, m, n, BD, AD, m, n, BD, BC, AD, BD * BD))

    # Чертёж: трапеция с AD внизу, BC сверху, диагональ BD. Пропорции берём
    # из чисел задачи, чтобы картинка не спорила с условием.
    ш_низ = float(AD)
    ш_верх = float(BC)
    выс = max(2.0, ш_низ * 0.45)
    сдвиг = (ш_низ - ш_верх) * 0.35
    A, D = (0.0, 0.0), (ш_низ, 0.0)
    B, C = (сдвиг, выс), (сдвиг + ш_верх, выс)
    ч = Чертёж()
    ч.многоугольник([A, B, C, D])
    ч.отрезок(B, D, пунктир=True)
    ч.дуга_угла(B, C, D)
    ч.дуга_угла(D, B, A)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'), (D, 'D', 'юв'))

    return {
        'title': 'Трапеция: диагональ — среднее геометрическое оснований',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Накрест лежащие углы при параллельных прямых и секущей равны.',
            'Второй признак подобия: две стороны одного треугольника пропорциональны '
            'двум сторонам другого, и углы между этими сторонами равны.',
        ],
        'params': {'BC': BC, 'AD': AD, 'BD': BD, 'm': m, 'n': n, 't': t},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 2. Точка на средней линии трапеции: сумма площадей треугольников на основаниях.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация. Трапеция ABCD с основаниями AD и BC, M и N — середины боковых
# сторон AB и CD, F — любая точка средней линии MN. Точку соединяют с концами
# обоих оснований: получаются треугольники BFC (на верхнем основании) и AFD
# (на нижнем). Доказать, что S(BFC) + S(AFD) = ½·S(ABCD). Чисел в условии нет:
# утверждение верно для любой трапеции и любой точки на MN, поэтому от сида к
# сиду меняются только буква точки, буквы вспомогательной высоты, форма
# условия и посадка чертежа.
#
# Ключевой ход. Через F проводим высоту трапеции KL (K на BC, L на AD). Три
# параллельные прямые BC, MN, AD отсекают на секущей AB равные отрезки
# BM = MA, значит по теореме Фалеса и на секущей KL отрезки равны:
# KF = FL = h/2. Дальше чистый счёт: у треугольника BFC основание BC = a и
# высота FK = h/2, у треугольника AFD основание AD = b и высота FL = h/2;
# сумма площадей ah/4 + bh/4 = (a + b)h/4 — ровно половина площади трапеции
# (a + b)h/2.
#
# Почему это работает. Обе высоты — куски одного перпендикуляра, а средняя
# линия режет его пополам независимо от того, где на MN взята точка: при
# сдвиге F вдоль MN вершина каждого треугольника движется по прямой,
# параллельной его основанию, и высота не меняется. Поэтому «произвольность»
# точки в условии задачу не усложняет, а упрощает.
#
# Ловушки.
# * «Средняя линия делит высоту пополам» — не аксиома; эксперт ждёт ссылку на
#   теорему Фалеса (или на среднюю линию треугольника). Без неё шаг не зачтут.
# * Высоты обоих треугольников надо брать на одном перпендикуляре, иначе не
#   получить FK + FL = h. Перпендикуляр к AD автоматически перпендикулярен BC —
#   это тоже нужно проговорить, а не подразумевать.
# * В сильно скошенной трапеции основание перпендикуляра может попасть на
#   продолжение BC. Доказательству это не мешает (высота опускается на
#   прямую), но чертёж строим так, чтобы K и L лежали на самих основаниях.
# * На чертеже F не должна стоять посередине MN — иначе ученик решит, что
#   доказан частный случай.


def _подпись_в_просвете(ч, p, буква, соседи, k, радиус=18.0):
    """Подпись точки, из которой отрезки расходятся во все стороны.

    Из F выходят восемь отрезков (к четырём вершинам, к M, N и к концам
    высоты), так что любая из восьми сторон СТОРОНЫ рано или поздно ляжет
    на линию. Поэтому ищем самый широкий угловой просвет между лучами из p
    и ставим букву на его биссектрису в «радиус» пикселях от точки.
    Смещения СТОРОНЫ заданы в экранных пикселях (ось y вниз, y — базовая
    линия текста, середина буквы на ~4 px выше): берём ближайшую по
    направлению сторону, а якорь подписи сдвигаем так, чтобы центр буквы
    попал ровно на биссектрису. k — масштаб холста, пикселей на мировую
    единицу.
    """
    лучи = sorted(math.atan2(q[1] - p[1], q[0] - p[0]) for q in соседи)
    лучи.append(лучи[0] + 2 * math.pi)          # замыкаем круг
    i = max(range(len(лучи) - 1), key=lambda j: лучи[j + 1] - лучи[j])
    угол = (лучи[i] + лучи[i + 1]) / 2

    def отклонение(сторона):
        dx, dy = СТОРОНЫ[сторона]
        направление = math.atan2(-(dy - 4), dx)
        return abs((направление - угол + math.pi) % (2 * math.pi) - math.pi)

    сторона = min(СТОРОНЫ, key=отклонение)
    dx, dy = СТОРОНЫ[сторона]
    # Экранный вектор «точка → центр буквы» минус собственное смещение
    # стороны — это сдвиг якоря; в мировые единицы переводим с переворотом y.
    сдвиг_x = радиус * math.cos(угол) - dx
    сдвиг_y = -радиус * math.sin(угол) - (dy - 4)
    ч.точка(p)
    ч.подпись((p[0] + сдвиг_x / k, p[1] - сдвиг_y / k), буква, сторона)


@сюжет(2)
def _сюжет_2(rng):
    # Буквы. В банке точку зовут F, K или E; вспомогательную высоту — KL или
    # EF. Пара букв высоты не должна пересекаться с буквой точки.
    F = rng.choice(['E', 'F', 'K', 'P'])
    K, L = rng.choice([п for п in [('K', 'L'), ('P', 'Q'), ('E', 'F')]
                       if F not in п])
    б = {'F': F, 'K': K, 'L': L}

    # Две равносильные формы условия: «точка на средней линии» и «M, N —
    # середины боковых сторон, точка на отрезке MN». Доказательство ниже
    # начинает с того, что в условии не сказано.
    форма = rng.randint(0, 1)
    if форма == 0:
        условие = (
            '<p>Точка \\(%(F)s\\) взята на средней линии \\(MN\\) трапеции '
            '\\(ABCD\\) (\\(AD\\) и \\(BC\\) — её основания) и соединена '
            'отрезками со всеми четырьмя вершинами. Докажите, что площади '
            'треугольников \\(B%(F)sC\\) и \\(A%(F)sD\\) в сумме составляют '
            'половину площади трапеции \\(ABCD\\).</p>' % б)
        шаг1 = (
            '<p>1. По условию \\(MN\\) — средняя линия трапеции, то есть \\(M\\) '
            'и \\(N\\) — середины боковых сторон; будем считать, что \\(M\\) — '
            'середина \\(AB\\), а \\(N\\) — середина \\(CD\\) (как на рисунке). '
            'По свойству средней линии трапеции \\(MN \\parallel AD\\); основания '
            'трапеции тоже параллельны: \\(BC \\parallel AD\\). Итак, три прямые '
            '\\(BC\\), \\(MN\\) и \\(AD\\) параллельны. Прямая \\(MN\\) проходит '
            'через точку \\(M\\), лежащую на стороне \\(AB\\) между \\(A\\) и '
            '\\(B\\), поэтому она целиком, а с ней и точка \\(%(F)s\\), лежит '
            'между прямыми \\(BC\\) и \\(AD\\).</p>' % б)
    else:
        условие = (
            '<p>В трапеции \\(ABCD\\) с основаниями \\(BC\\) и \\(AD\\) точки '
            '\\(M\\) и \\(N\\) — середины боковых сторон \\(AB\\) и \\(CD\\) '
            'соответственно, а \\(%(F)s\\) — произвольная точка отрезка '
            '\\(MN\\). Докажите, что '
            '\\(S_{B%(F)sC} + S_{A%(F)sD} = \\tfrac12 S_{ABCD}\\).</p>' % б)
        шаг1 = (
            '<p>1. Отрезок \\(MN\\) соединяет середины боковых сторон \\(AB\\) и '
            '\\(CD\\), значит \\(MN\\) — средняя линия трапеции. По её свойству '
            '\\(MN \\parallel AD\\); основания трапеции тоже параллельны: '
            '\\(BC \\parallel AD\\). Итак, три прямые \\(BC\\), \\(MN\\) и \\(AD\\) '
            'параллельны. Прямая \\(MN\\) проходит через точку \\(M\\), лежащую '
            'на стороне \\(AB\\) между \\(A\\) и \\(B\\), поэтому она целиком, а с '
            'ней и точка \\(%(F)s\\), лежит между прямыми \\(BC\\) и '
            '\\(AD\\).</p>' % б)

    доказательство = шаг1 + (
        '<p>2. Дополнительное построение. Через точку \\(%(F)s\\) проведём '
        'прямую, перпендикулярную основанию \\(AD\\); пусть она пересекает '
        'прямую \\(BC\\) в точке \\(%(K)s\\), а прямую \\(AD\\) — в точке '
        '\\(%(L)s\\). Прямая, перпендикулярная одной из двух параллельных '
        'прямых, перпендикулярна и другой, поэтому \\(%(K)s%(L)s \\perp BC\\). '
        'Значит, \\(%(K)s%(L)s\\) — высота трапеции; обозначим '
        '\\(%(K)s%(L)s = h\\). Точка \\(%(F)s\\) лежит между прямыми \\(BC\\) и '
        '\\(AD\\), то есть внутри отрезка \\(%(K)s%(L)s\\), поэтому '
        '\\(%(K)s%(F)s + %(F)s%(L)s = h\\).</p>'

        '<p>3. Покажем, что \\(%(F)s\\) — середина высоты \\(%(K)s%(L)s\\). '
        'Параллельные прямые \\(BC\\), \\(MN\\), \\(AD\\) пересекают секущую '
        '\\(AB\\) в точках \\(B\\), \\(M\\), \\(A\\) и отсекают на ней равные '
        'отрезки: \\(BM = MA\\), так как \\(M\\) — середина \\(AB\\). По теореме '
        'Фалеса те же параллельные прямые отсекают равные отрезки и на любой '
        'секущей, в частности на \\(%(K)s%(L)s\\): '
        '\\(%(K)s%(F)s = %(F)s%(L)s\\). Вместе с равенством '
        '\\(%(K)s%(F)s + %(F)s%(L)s = h\\) это даёт</p>'
        '\\[%(K)s%(F)s = %(F)s%(L)s = \\frac{h}{2}.\\]'

        '<p>4. Обозначим \\(BC = a\\), \\(AD = b\\). Площадь трапеции равна '
        'произведению полусуммы оснований на высоту:</p>'
        '\\[S_{ABCD} = \\frac{a + b}{2} \\cdot h.\\]'

        '<p>5. В треугольнике \\(B%(F)sC\\) возьмём за основание сторону '
        '\\(BC\\). Высота, опущенная из вершины \\(%(F)s\\) на прямую \\(BC\\), — '
        'это отрезок \\(%(F)s%(K)s\\), поскольку \\(%(F)s%(K)s \\perp BC\\) '
        '(доказано в п. 2). Поэтому</p>'
        '\\[S_{B%(F)sC} = \\frac12 \\cdot BC \\cdot %(F)s%(K)s = '
        '\\frac12 \\cdot a \\cdot \\frac{h}{2} = \\frac{ah}{4}.\\]'
        '<p>Точно так же в треугольнике \\(A%(F)sD\\) основание — \\(AD\\), а '
        'высота из вершины \\(%(F)s\\) — отрезок \\(%(F)s%(L)s\\), '
        'перпендикулярный \\(AD\\) по построению:</p>'
        '\\[S_{A%(F)sD} = \\frac12 \\cdot AD \\cdot %(F)s%(L)s = '
        '\\frac12 \\cdot b \\cdot \\frac{h}{2} = \\frac{bh}{4}.\\]'

        '<p>6. Складываем площади:</p>'
        '\\[S_{B%(F)sC} + S_{A%(F)sD} = \\frac{ah}{4} + \\frac{bh}{4} = '
        '\\frac{(a + b)h}{4} = \\frac12 \\cdot \\frac{a + b}{2} \\cdot h = '
        '\\frac12 S_{ABCD},\\]'
        '<p>что и требовалось доказать.</p>'

        '<p><i>Замечание.</i> То, где именно на средней линии взята точка '
        '\\(%(F)s\\), в доказательстве не использовалось: при сдвиге '
        '\\(%(F)s\\) вдоль \\(MN\\) обе высоты \\(%(F)s%(K)s\\) и '
        '\\(%(F)s%(L)s\\) остаются равными \\(h/2\\), и сумма площадей не '
        'меняется.</p>' % б)

    # Чертёж. Нижнее основание AD фиксированной длины, верхнее BC заметно
    # короче и сдвинуто так, чтобы обе боковые стороны наклонялись (не
    # прямоугольная и не обязательно равнобедренная трапеция). Точку F
    # сажаем на среднюю линию в стороне от её середины, но над отрезком BC,
    # чтобы основания перпендикуляра K и L попали на сами основания.
    ad = 10.0
    bc = rng.uniform(4.6, 6.4)
    выс = rng.uniform(3.7, 4.5)
    слева = rng.uniform(1.2, ad - bc - 1.2)
    A, D = (0.0, 0.0), (ad, 0.0)
    B, C = (слева, выс), (слева + bc, выс)
    M, N = середина(A, B), середина(C, D)
    доля = 0.5 + rng.choice([-1, 1]) * rng.uniform(0.12, 0.25)
    x = слева + доля * bc
    Fт = пересечение(M, N, (x, 0.0), (x, 1.0))   # средняя линия ∩ вертикаль
    Kт = проекция(B, C, Fт)
    Lт = проекция(A, D, Fт)

    ч = Чертёж(height=240)
    ч.многоугольник([A, B, C, D])
    ч.отрезок(M, N)
    for вершина in (A, B, C, D):
        ч.отрезок(Fт, вершина)
    ч.отрезок(Kт, Lт, пунктир=True)              # дополнительное построение
    ч.прямой_угол(Kт, Fт, C, размер=0.35)
    ч.прямой_угол(Lт, Fт, D, размер=0.35)
    # Равные отрезки: AM = MB (один штрих), CN = ND (два), KF = FL (три).
    ч.равенство(A, M, 1)
    ч.равенство(M, B, 1)
    ч.равенство(C, N, 2)
    ч.равенство(N, D, 2)
    ч.равенство(Kт, Fт, 3)
    ч.равенство(Fт, Lт, 3)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'), (M, 'M', 'з'), (N, 'N', 'в'),
                      (Kт, K, 'с'), (Lт, L, 'ю'))
    # Масштаб холста повторяет формулу Чертёж._преобразование: все точки
    # чертежа лежат в прямоугольнике [0, ad] × [0, выс], так что он известен
    # заранее и нужен только для того, чтобы отмерить подпись F в пикселях.
    k = min((ч.width - 2 * ч.поле) / ad, (ч.height - 2 * ч.поле) / выс)
    _подпись_в_просвете(ч, Fт, F, [A, B, C, D, M, N, Kт, Lт], k)

    return {
        'title': 'Точка на средней линии трапеции: сумма площадей треугольников '
                 'на основаниях',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Средняя линия трапеции соединяет середины боковых сторон и '
            'параллельна основаниям.',
            'Теорема Фалеса: если параллельные прямые отсекают на одной секущей '
            'равные отрезки, то и на любой другой секущей они отсекают равные '
            'отрезки.',
            'Прямая, перпендикулярная одной из двух параллельных прямых, '
            'перпендикулярна и другой.',
            'Площадь трапеции — произведение полусуммы оснований на высоту; '
            'площадь треугольника — половина произведения основания на высоту.',
        ],
        'params': {
            'точка': F, 'высота': K + L, 'форма_условия': форма,
            'BC': round(bc, 2), 'AD': ad, 'h': round(выс, 2),
            'доля_вдоль_BC': round(доля, 2),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 3. Точка на средней линии трапеции: треугольники при боковых сторонах.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация. Трапеция ABCD с основаниями AD и BC; M и N — середины боковых
# сторон AB и CD, MN — средняя линия. На ней взята произвольная точка E и
# соединена со всеми четырьмя вершинами. Доказать, что S(AEB) + S(CED) =
# ½·S(ABCD): два треугольника, прислонённые к боковым сторонам, вместе занимают
# ровно половину трапеции, где бы E ни стояла.
#
# Это парный сюжет к сюжету 2 (те же условия, но треугольники на основаниях —
# BEC и AED). Справочник предлагает получать наш случай дополнением: доказать
# утверждение про основания и вычесть его из площади трапеции. Здесь
# доказательство прямое — оно короче и не требует по дороге доказывать чужое
# утверждение (а ссылаться на него без доказательства эксперт не разрешит).
#
# Ключевой ход. Треугольник AEB режем отрезком EM. Это его медиана, но нужна
# она не как медиана, а как общее основание двух половинок AEM и BEM: обе
# стоят на прямой MN, а их вершины A и B лежат на прямых AD и BC, параллельных
# MN. Значит высоты половинок — это расстояния от MN до оснований трапеции, и
# в сумме они дают всю высоту H:
#     S(AEB) = ½·EM·(h₁ + h₂) = ½·EM·H.
# Так же S(CED) = ½·EN·H. Складываем: ½·H·(EM + EN) = ½·H·MN, а MN равна
# полусумме оснований, откуда ½·H·(AD + BC)/2 = ½·S(ABCD).
#
# Почему работает. Факт «средняя линия делит высоту пополам» (h₁ = h₂ = H/2)
# здесь не нужен — хватает h₁ + h₂ = H. Зато существенно, что E лежит на
# отрезке MN (иначе EM + EN ≠ MN) и что MN — именно средняя линия: только у
# неё длина равна полусумме оснований. Положение E на MN на ответ не влияет
# потому, что при сдвиге E вдоль MN один из отрезков EM, EN растёт ровно на
# столько, на сколько убывает другой.
#
# Ловушки.
#   * Перепутать с сюжетом 2 и искать высоты треугольников AEB и CED к
#     боковым сторонам — они ни с чем не связаны, разложение не сложится.
#   * Сослаться на «известное» S(BEC) + S(AED) = ½·S без доказательства.
#   * Не обосновать, почему высота треугольника BEM равна расстоянию между
#     прямыми MN и BC: нужно явно провести перпендикуляр KL через E и
#     заметить, что он перпендикулярен и MN, раз MN ∥ BC.
#   * Перпендикуляр через E может попасть на продолжение основания (сильно
#     скошенная трапеция), поэтому K и L берём на прямых BC и AD, а не на
#     отрезках — доказательству всё равно.
#   * На чертеже E не должна совпадать с M или N и не должна выходить за
#     отрезок MN: на продолжении средней линии утверждение неверно.
#
# Числовых данных в условии нет. Варьируются буква точки, формулировка
# (с названными серединами M, N или без них) и форма трапеции на чертеже.


def _якорь_подписи_3(E, C, k, отступ_px=18.0):
    """Мировая точка, к которой подпись стороной 'св' ляжет в свободный
    просвет справа-сверху от E.

    Из E выходят восемь отрезков (к четырём вершинам, два куска высоты и два
    куска средней линии), и любая стандартная сторона подписи упирается в
    один из них. Правый верхний угол между EK (строго вверх) и EN (строго
    вправо) луч EC делит на два просвета; берём тот, что шире: пока EC
    положе 45°, это просвет над ним, когда E ближе к N и EC круче — под ним.
    Середину буквы ставим по биссектрисе просвета в отступ_px пикселях от
    точки. Два поправочных сдвига: сторона 'св' сама уводит текст на (11; 8)
    px вверх-вправо, а координата текста — это базовая линия, середина
    глифа на 4,5 px выше неё; оба вычитаем, иначе буква съезжает к лучу EC.
    """
    θC = math.atan2(C[1] - E[1], C[0] - E[0])
    θ = (math.pi / 2 + θC) / 2 if θC <= math.pi / 4 else θC / 2
    return (E[0] + (отступ_px * math.cos(θ) - 11) / k,
            E[1] + (отступ_px * math.sin(θ) - 8 - 4.5) / k)


@сюжет(3)
def _сюжет_3(rng):
    Т = rng.choice(['E', 'F', 'P'])          # буква точки на средней линии
    середины_названы = rng.random() < 0.5    # есть ли M и N уже в условии

    if середины_названы:
        условие = (
            '<p>В трапеции \\(ABCD\\) с основаниями \\(AD\\) и \\(BC\\) точки '
            '\\(M\\) и \\(N\\) — середины боковых сторон \\(AB\\) и \\(CD\\), '
            'а \\(§\\) — произвольная точка средней линии \\(MN\\). Докажите, что '
            '\\(S_{A§B} + S_{C§D} = \\dfrac{1}{2}\\,S_{ABCD}\\).</p>')
        шаг1 = (
            '<p>1. Отрезок \\(MN\\) соединяет середины боковых сторон, то есть '
            'является средней линией трапеции. По теореме о средней линии '
            'трапеции \\(MN \\parallel AD\\), \\(MN \\parallel BC\\) и '
            '\\(MN = \\dfrac{AD + BC}{2}\\).</p>')
    else:
        условие = (
            '<p>На средней линии трапеции \\(ABCD\\) с основаниями \\(AD\\) и '
            '\\(BC\\) отмечена произвольная точка \\(§\\). Докажите, что сумма '
            'площадей треугольников \\(A§B\\) и \\(C§D\\) равна половине площади '
            'трапеции.</p>')
        шаг1 = (
            '<p>1. Пусть \\(M\\) и \\(N\\) — середины боковых сторон \\(AB\\) и '
            '\\(CD\\). Тогда \\(MN\\) — средняя линия трапеции, и точка \\(§\\) '
            'лежит на отрезке \\(MN\\). По теореме о средней линии трапеции '
            '\\(MN \\parallel AD\\), \\(MN \\parallel BC\\) и '
            '\\(MN = \\dfrac{AD + BC}{2}\\).</p>')

    доказательство = шаг1 + (
        '<p>2. Дополнительное построение. Через точку \\(§\\) проведём прямую, '
        'перпендикулярную основанию \\(AD\\); так как \\(BC \\parallel AD\\), она '
        'перпендикулярна и \\(BC\\) (прямая, перпендикулярная одной из двух '
        'параллельных прямых, перпендикулярна и другой). Пусть \\(K\\) — её '
        'точка пересечения с прямой '
        '\\(BC\\), \\(L\\) — с прямой \\(AD\\). Тогда \\(KL \\perp BC\\), '
        '\\(KL \\perp AD\\), то есть \\(KL\\) — общий перпендикуляр параллельных '
        'прямых \\(BC\\) и \\(AD\\); его длина равна расстоянию между этими '
        'прямыми, то есть высоте трапеции (точки \\(K\\) и \\(L\\) при этом '
        'могут лежать и на продолжениях оснований — на длину \\(KL\\) это не '
        'влияет). Обозначим \\(KL = H\\). Средняя линия лежит между прямыми '
        '\\(BC\\) и \\(AD\\) '
        '(её концы \\(M\\) и \\(N\\) — внутренние точки боковых сторон), поэтому '
        '\\(§\\) — внутренняя точка отрезка \\(KL\\) и \\(§K + §L = KL = H\\).</p>'

        '<p>3. Так как \\(MN \\parallel BC\\) и \\(KL \\perp BC\\), то по той же '
        'причине \\(KL \\perp MN\\). Поэтому \\(§K\\) — общий перпендикуляр '
        'параллельных прямых \\(MN\\) и \\(BC\\), и длина \\(§K\\) равна расстоянию '
        'между ними. Точно так же длина \\(§L\\) равна расстоянию между прямыми '
        '\\(MN\\) и \\(AD\\).</p>'

        '<p>4. Точка \\(M\\) лежит на стороне \\(AB\\) треугольника \\(A§B\\), '
        'поэтому отрезок \\(§M\\) разбивает его на треугольники \\(A§M\\) и '
        '\\(B§M\\), и \\(S_{A§B} = S_{A§M} + S_{B§M}\\). В обоих треугольниках '
        'примем за основание общую сторону \\(§M\\); она лежит на прямой '
        '\\(MN\\). Вершина \\(B\\) лежит на прямой \\(BC\\), параллельной '
        '\\(MN\\), поэтому высота треугольника \\(B§M\\), опущенная из \\(B\\) '
        'на прямую \\(MN\\), равна расстоянию между прямыми \\(BC\\) и \\(MN\\), '
        'то есть \\(§K\\) '
        '(п. 3). Аналогично высота треугольника \\(A§M\\), опущенная из \\(A\\), '
        'равна расстоянию между прямыми \\(AD\\) и \\(MN\\), то есть \\(§L\\). '
        'По формуле площади треугольника</p>'
        '\\[S_{A§B} = \\frac{1}{2}\\,§M \\cdot §L + \\frac{1}{2}\\,§M \\cdot §K '
        '= \\frac{1}{2}\\,§M\\,(§L + §K) = \\frac{1}{2}\\,§M \\cdot H.\\]'
        '<p>(Если \\(§\\) совпадает с \\(M\\), треугольник \\(A§B\\) вырождается '
        'в отрезок, и обе части равенства равны нулю — формула остаётся '
        'верной; то же относится к треугольнику \\(C§D\\) в п. 5 при '
        '\\(§ = N\\).)</p>'

        '<p>5. Точно так же отрезок \\(§N\\) разбивает треугольник \\(C§D\\) на '
        'треугольники \\(C§N\\) и \\(D§N\\) с общим основанием \\(§N\\) на прямой '
        '\\(MN\\); их высоты, опущенные из \\(C\\) и \\(D\\), равны \\(§K\\) и '
        '\\(§L\\). Поэтому</p>'
        '\\[S_{C§D} = \\frac{1}{2}\\,§N \\cdot §K + \\frac{1}{2}\\,§N \\cdot §L '
        '= \\frac{1}{2}\\,§N \\cdot H.\\]'

        '<p>6. Сложим полученные площади. Точка \\(§\\) лежит на отрезке \\(MN\\), '
        'поэтому \\(§M + §N = MN\\), а по п. 1 \\(MN = \\dfrac{AD + BC}{2}\\):</p>'
        '\\[S_{A§B} + S_{C§D} = \\frac{1}{2}\\,H\\,(§M + §N) '
        '= \\frac{1}{2}\\,H \\cdot MN '
        '= \\frac{1}{2} \\cdot \\frac{AD + BC}{2} \\cdot H.\\]'

        '<p>7. По формуле площади трапеции \\(S_{ABCD} = \\dfrac{AD + BC}{2} '
        '\\cdot H\\). Сравнивая с п. 6, получаем '
        '\\(S_{A§B} + S_{C§D} = \\dfrac{1}{2}\\,S_{ABCD}\\), что и требовалось '
        'доказать.</p>')

    # Буква точки встречается в тексте десятки раз, а в LaTeX полно фигурных
    # скобок, поэтому вместо %-подстановки — свой значок § и один replace.
    условие = условие.replace('§', Т)
    доказательство = доказательство.replace('§', Т)

    # Чертёж: AD внизу, BC сверху. Основание AD фиксируем в 10 единиц,
    # отступы B и C от краёв — от 1,4 до 2,8, высота чуть больше половины
    # основания: трапеция читается как трапеция, а не как прямоугольник
    # или остриё.
    отступ_л = rng.uniform(1.4, 2.8)
    отступ_п = rng.uniform(1.4, 2.8)
    выс = rng.uniform(5.0, 5.8)
    A, D = (0.0, 0.0), (10.0, 0.0)
    B, C = (отступ_л, выс), (10.0 - отступ_п, выс)
    M, N = середина(A, B), середина(C, D)
    # Точку держим ближе к M: у N справа стоит подпись, и E не должна в неё
    # упереться. При таких границах перпендикуляр из E попадает на сами
    # основания, а не на их продолжения.
    t = rng.uniform(0.30, 0.62)
    E = (M[0] + t * (N[0] - M[0]), M[1] + t * (N[1] - M[1]))
    K = проекция(B, C, E)
    L = проекция(A, D, E)

    ч = Чертёж()
    # Трапеция — только контуром, а два треугольника из условия закрашены:
    # так видно, о какой именно половине площади идёт речь.
    ч.многоугольник([A, B, C, D], залить=False)
    ч.многоугольник([A, E, B])
    ч.многоугольник([C, E, D])
    ч.отрезок(M, N)
    ч.отрезок(K, L, пунктир=True, вспомогательный=True)
    ч.прямой_угол(K, C, E, размер=0.35)
    ч.прямой_угол(L, D, E, размер=0.35)
    ч.равенство(A, M)
    ч.равенство(M, B)
    ч.равенство(C, N, штрихов=2)
    ч.равенство(N, D, штрихов=2)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'), (M, 'M', 'з'), (N, 'N', 'в'),
                      (K, 'K', 'с'), (L, 'L', 'ю'))
    # Масштаб чертежа известен заранее: все точки лежат внутри трапеции,
    # значит, рамка — ровно 10 на выс единиц. Повторяем формулу Чертёж'а.
    k = min((ч.width - 2 * ч.поле) / 10.0, (ч.height - 2 * ч.поле) / выс)
    ч.точка(E)
    ч.подпись(_якорь_подписи_3(E, C, k), Т, 'св')

    return {
        'title': 'Точка на средней линии трапеции: треугольники при боковых '
                 'сторонах — половина площади',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Средняя линия трапеции параллельна основаниям и равна их полусумме.',
            'Прямая, перпендикулярная одной из двух параллельных прямых, '
            'перпендикулярна и другой; длина общего перпендикуляра — это '
            'расстояние между параллельными прямыми, и оно не зависит от того, '
            'в каком месте перпендикуляр проведён.',
            'Площадь треугольника — половина произведения стороны на высоту, '
            'проведённую к ней; площадь трапеции — произведение полусуммы '
            'оснований на высоту.',
            'Отрезок из вершины треугольника в точку противоположной стороны '
            'разбивает его на два треугольника, площади которых складываются.',
        ],
        'params': {
            'точка': Т,
            'середины_названы': середины_названы,
            'форма': (round(отступ_л, 2), round(отступ_п, 2), round(выс, 2)),
            't': round(t, 3),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 4. Середина боковой стороны трапеции: треугольник на противоположной боковой стороне — половина трапеции.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация. Трапеция ABCD с основаниями BC и AD. На одной из боковых
# сторон отмечают середину (K на CD либо M на AB — две задачи банка, зеркальные
# близнецы) и соединяют её с концами противоположной боковой стороны. Получается
# треугольник, «опёртый» на эту сторону; нужно доказать, что его площадь — ровно
# половина площади трапеции. Чисел в условии нет вовсе: не заданы ни основания,
# ни высота, ни углы. Единственная «числовая» константа спрятана в слове
# «середина», и она жёсткая.
#
# Ключевой ход. Из середины K опускаем перпендикуляры KP и KQ на прямые
# оснований. Основания параллельны, поэтому P, K, Q лежат на одном перпендикуляре:
# PQ — высота трапеции, разрезанная точкой K на два куска. Прямоугольные
# треугольники CKP и DKQ равны по гипотенузе (CK = KD) и острому углу
# (вертикальные углы при K), откуда KP = KQ = h и высота трапеции равна 2h.
# Иначе говоря, середина боковой стороны равноудалена от обоих оснований.
# Дальше счёт: S(BKC) + S(AKD) = ½ah + ½bh = ½(a + b)h, а S(ABCD) =
# (a + b)/2 · 2h = (a + b)h. Два «боковых» треугольника забирают ровно половину,
# и треугольнику AKB достаётся вторая половина.
#
# Почему это работает. Площадь треугольника с вершиной на прямой, параллельной
# основанию, зависит только от основания и расстояния между прямыми; равенство
# этих расстояний и есть содержание слова «середина». Проверка на жёсткость:
# при CK : KD = m : n расстояния до оснований равны mH/(m + n) и nH/(m + n),
# сумма боковых площадей — H(am + bn)/(2(m + n)), и она равна половине
# (a + b)H/2 лишь при (m − n)(a − b) = 0. То есть либо K — точно середина, либо
# a = b и перед нами параллелограмм. «Почти верных» числовых вариантов нет,
# генерировать нечего: варьируются боковая сторона, форма вопроса («половина
# трапеции» или «сумма двух других треугольников») и посадка чертежа.
#
# Ловушки.
# * Одно из оснований перпендикуляра всегда попадает на продолжение основания,
#   а не на само основание: K лежит строго между вертикалями через C и D, если
#   трапеция не прямоугольная. На площадь это не влияет — высота треугольника
#   BKC есть расстояние от K до прямой BC, — но на чертеже продолжение надо
#   нарисовать честно, иначе рисунок лжёт.
# * Нельзя молча считать «перпендикуляр через K» одной прямой для обоих
#   оснований: нужно сослаться на то, что перпендикуляр к одной из параллельных
#   перпендикулярен и другой, а перпендикуляр из точки к прямой единственный.
# * Условие не запрещает прямоугольную трапецию с прямыми углами на той самой
#   боковой стороне, где взята середина (CD ⊥ AD). Тогда P = C, Q = D, и
#   треугольники CKP, DKQ вырождаются в отрезки — признак равенства применять
#   не к чему. Равенство KP = KQ в этом случае очевидно (это KC = KD), но
#   случай надо назвать явно, иначе доказательство покрывает не все трапеции.
# * Вычитание площадей в конце законно потому, что K лежит на стороне CD и
#   отрезки KA, KB проходят внутри выпуклой трапеции: три треугольника не
#   перекрываются и заполняют её целиком.
#
# Есть и второе решение, через достраивание: продолжить BK до пересечения с
# прямой AD в точке T, получить △BKC = △TKD по стороне и двум прилежащим углам,
# и тогда AK — медиана треугольника ABT, равновеликого трапеции. Оно короче, но
# здесь взят счёт через высоту: он совпадает с разбором, который ждёт эксперт,
# и каждый его шаг — проверяемая формула.


@сюжет(4)
def _сюжет_4(rng):
    # Две задачи банка — зеркальные близнецы: пополам делят либо CD, либо AB.
    # Чтобы не писать доказательство дважды, буквы собраны в словарь: X —
    # середина, «верх» — конец этой боковой стороны на основании BC, «низ» —
    # её конец на AD, п1 и п2 — концы противоположной боковой стороны.
    # P и Q — основания перпендикуляров из X на прямые BC и AD; они одни и те
    # же в обоих вариантах, чтобы текст читался одинаково.
    сторона = rng.choice(['CD', 'AB'])
    if сторона == 'CD':
        б = dict(X='K', верх='C', низ='D', сторона='CD',
                 тр='AKB', тр_верх='BKC', тр_низ='AKD', п1='A', п2='B')
    else:
        б = dict(X='M', верх='B', низ='A', сторона='AB',
                 тр='CMD', тр_верх='BMC', тр_низ='AMD', п1='C', п2='D')
    # Форма вопроса — «половина трапеции» чаще, «сумма двух других
    # треугольников» реже: второе — та же теорема, но ученику нужно заметить,
    # что сумма двух других треугольников и есть вторая половина.
    вопрос = rng.choice(['половина', 'половина', 'сумма'])

    # ── условие ──────────────────────────────────────────────────────────
    # Формулировка своя, не банковская: в банке «В трапеции ABCD с основаниями
    # ... точка K — середина боковой стороны CD. Докажите, что площадь
    # треугольника ... равна половине площади трапеции».
    начало = rng.choice([
        'Основания трапеции \\(ABCD\\) — отрезки \\(BC\\) и \\(AD\\). На боковой стороне '
        '\\(%(сторона)s\\) отметили её середину — точку \\(%(X)s\\) — и соединили её '
        'отрезками с вершинами \\(%(п1)s\\) и \\(%(п2)s\\).',
        'Точку \\(%(X)s\\) — середину боковой стороны \\(%(сторона)s\\) трапеции '
        '\\(ABCD\\) с основаниями \\(BC\\) и \\(AD\\) — соединили отрезками с вершинами '
        '\\(%(п1)s\\) и \\(%(п2)s\\).',
    ]) % б
    if вопрос == 'половина':
        просьба = ('Докажите, что площадь получившегося треугольника \\(%(тр)s\\) '
                   'составляет половину площади трапеции \\(ABCD\\).') % б
    else:
        просьба = ('Трапеция при этом разбилась на три треугольника. Докажите, что '
                   'площадь треугольника \\(%(тр)s\\) равна сумме площадей двух других — '
                   '\\(%(тр_верх)s\\) и \\(%(тр_низ)s\\).') % б
    условие = '<p>%s %s</p>' % (начало, просьба)

    # ── доказательство ───────────────────────────────────────────────────
    шаги = [
        # 1. Построение и то, что оно даёт высоту трапеции.
        '<p>1. Опустим из точки \\(%(X)s\\) перпендикуляры на прямые, содержащие '
        'основания: \\(%(X)sP \\perp BC\\), где \\(P\\) лежит на прямой \\(BC\\), и '
        '\\(%(X)sQ \\perp AD\\), где \\(Q\\) лежит на прямой \\(AD\\). Так как '
        '\\(BC \\parallel AD\\), прямая \\(%(X)sP\\), перпендикулярная \\(BC\\), '
        'перпендикулярна и \\(AD\\). Через точку \\(%(X)s\\) проходит только один '
        'перпендикуляр к прямой \\(AD\\), поэтому прямые \\(%(X)sP\\) и \\(%(X)sQ\\) '
        'совпадают: точки \\(P\\), \\(%(X)s\\), \\(Q\\) лежат на одной прямой. '
        'Точка \\(%(X)s\\) лежит на боковой стороне \\(%(сторона)s\\) и отлична от её '
        'концов, то есть находится строго между прямыми \\(BC\\) и \\(AD\\); поэтому '
        '\\(%(X)s\\) лежит между \\(P\\) и \\(Q\\), \\(PQ = %(X)sP + %(X)sQ\\), а сам отрезок '
        '\\(PQ\\) — высота трапеции. Заметим: основания перпендикуляров могут попасть не на сами '
        'основания, а на их продолжения (на чертеже так расположена точка \\(P\\)) — '
        'рассуждение от этого не меняется.</p>',
        # 2. Равенство прямоугольных треугольников — середина равноудалена от оснований.
        '<p>2. Докажем, что \\(%(X)sP = %(X)sQ\\). Если боковая сторона \\(%(сторона)s\\) '
        'перпендикулярна основаниям, то \\(P = %(верх)s\\), \\(Q = %(низ)s\\) и '
        '\\(%(X)sP = %(X)s%(верх)s = %(X)s%(низ)s = %(X)sQ\\), поскольку \\(%(X)s\\) — '
        'середина \\(%(сторона)s\\). Пусть теперь \\(%(сторона)s\\) не перпендикулярна '
        'основаниям; тогда \\(P \\ne %(верх)s\\) и \\(Q \\ne %(низ)s\\). Рассмотрим '
        'треугольники \\(%(верх)s%(X)sP\\) и \\(%(низ)s%(X)sQ\\). '
        'Они прямоугольные: \\(\\angle %(верх)sP%(X)s = \\angle %(низ)sQ%(X)s = 90^\\circ\\). '
        'Их гипотенузы равны: \\(%(верх)s%(X)s = %(X)s%(низ)s\\), поскольку \\(%(X)s\\) — '
        'середина \\(%(сторона)s\\). Острые углы \\(\\angle %(верх)s%(X)sP\\) и '
        '\\(\\angle %(низ)s%(X)sQ\\) равны как вертикальные: точка \\(%(X)s\\) лежит '
        'между \\(%(верх)s\\) и \\(%(низ)s\\) на прямой \\(%(сторона)s\\) и между '
        '\\(P\\) и \\(Q\\) на прямой \\(PQ\\) (шаг 1), поэтому лучи \\(%(X)s%(верх)s\\) '
        'и \\(%(X)s%(низ)s\\) противоположны, как и лучи \\(%(X)sP\\) и \\(%(X)sQ\\). '
        'По признаку равенства прямоугольных треугольников по гипотенузе и острому '
        'углу \\(\\triangle %(верх)s%(X)sP = \\triangle %(низ)s%(X)sQ\\), а в равных '
        'треугольниках соответственные стороны равны: катеты \\(%(X)sP\\) и '
        '\\(%(X)sQ\\), прилежащие к равным острым углам при вершине \\(%(X)s\\), равны. '
        'Итак, в любом случае \\(%(X)sP = %(X)sQ\\). Обозначим \\(%(X)sP = %(X)sQ = h\\); '
        'тогда высота трапеции \\(PQ = 2h\\).</p>',
        # 3. Площади двух треугольников на основаниях.
        '<p>3. Обозначим \\(BC = a\\), \\(AD = b\\) и найдём площади треугольников '
        '\\(%(тр_верх)s\\) и \\(%(тр_низ)s\\). В треугольнике \\(%(тр_верх)s\\) сторона '
        '\\(BC\\) — основание, а \\(%(X)sP\\) — высота, проведённая к нему '
        '(\\(%(X)sP \\perp BC\\)). В треугольнике \\(%(тр_низ)s\\) основание — \\(AD\\), '
        'высота — \\(%(X)sQ\\). По формуле площади треугольника</p>'
        '\\[S_{%(тр_верх)s} = \\frac{1}{2}\\, BC \\cdot %(X)sP = \\frac{1}{2}\\, a h, \\qquad '
        'S_{%(тр_низ)s} = \\frac{1}{2}\\, AD \\cdot %(X)sQ = \\frac{1}{2}\\, b h, \\qquad '
        'S_{%(тр_верх)s} + S_{%(тр_низ)s} = \\frac{(a + b)\\, h}{2}.\\]',
        # 4. Площадь трапеции и сравнение.
        '<p>4. Площадь трапеции равна произведению полусуммы оснований на высоту:</p>'
        '\\[S_{ABCD} = \\frac{a + b}{2} \\cdot PQ = \\frac{a + b}{2} \\cdot 2h = (a + b)\\, h.\\]'
        '<p>Сравнивая с шагом 3, получаем \\(S_{%(тр_верх)s} + S_{%(тр_низ)s} = '
        '\\dfrac{1}{2}\\, S_{ABCD}\\).</p>',
        # 5. Вычитание площадей.
        '<p>5. Точка \\(%(X)s\\) лежит на стороне \\(%(сторона)s\\), поэтому отрезки '
        '\\(%(X)s%(п1)s\\) и \\(%(X)s%(п2)s\\) проходят внутри трапеции и разрезают её на '
        'три треугольника без наложений: \\(%(тр)s\\), \\(%(тр_верх)s\\) и \\(%(тр_низ)s\\). '
        'Площадь фигуры равна сумме площадей её частей, откуда</p>',
    ]
    if вопрос == 'половина':
        шаги.append(
            '\\[S_{%(тр)s} = S_{ABCD} - \\bigl(S_{%(тр_верх)s} + S_{%(тр_низ)s}\\bigr) '
            '= S_{ABCD} - \\frac{1}{2}\\, S_{ABCD} = \\frac{1}{2}\\, S_{ABCD}.\\]'
            '<p>Это и требовалось доказать.</p>')
    else:
        шаги.append(
            '\\[S_{%(тр)s} = S_{ABCD} - \\bigl(S_{%(тр_верх)s} + S_{%(тр_низ)s}\\bigr) '
            '= S_{ABCD} - \\frac{1}{2}\\, S_{ABCD} = \\frac{1}{2}\\, S_{ABCD} '
            '= S_{%(тр_верх)s} + S_{%(тр_низ)s}.\\]'
            '<p>Итак, площадь треугольника \\(%(тр)s\\) равна сумме площадей двух '
            'других треугольников, что и требовалось доказать.</p>')
    доказательство = ''.join(ш % б for ш in шаги)

    # ── чертёж ───────────────────────────────────────────────────────────
    # AD внизу, BC сверху. Боковые стороны наклонены по-разному, чтобы
    # трапеция не читалась ни как равнобокая, ни как прямоугольная. Со
    # стороны середины наклон делаем побольше: тогда продолжение основания до
    # точки P получается заметной длины, а не обрубком в пару пикселей.
    низ_ш = 9.0
    H = rng.uniform(4.6, 5.4)
    while True:
        у_середины = rng.uniform(2.0, 2.8)
        другой = rng.uniform(1.2, 2.0)
        if abs(у_середины - другой) >= 0.4:
            break
    if сторона == 'CD':
        слева, справа = другой, у_середины
    else:
        слева, справа = у_середины, другой
    A, D = (0.0, 0.0), (низ_ш, 0.0)
    B, C = (слева, H), (низ_ш - справа, H)

    if сторона == 'CD':
        X = середина(C, D)
        верх_т, низ_т = C, D
        прочие = (A, B)
        подписи = ((A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'с'), (D, 'D', 'юв'),
                   (X, 'K', 'св'))
        подпись_P = 'св'
    else:
        X = середина(A, B)
        верх_т, низ_т = B, A
        прочие = (C, D)
        подписи = ((A, 'A', 'юз'), (B, 'B', 'с'), (C, 'C', 'св'), (D, 'D', 'юв'),
                   (X, 'M', 'сз'))
        подпись_P = 'сз'
    # Основания перпендикуляров. P всегда попадает на продолжение BC за
    # конец основания (см. докстринг), Q — внутрь отрезка AD.
    P = проекция(B, C, X)
    Q = проекция(A, D, X)

    ч = Чертёж()
    ч.многоугольник([A, B, C, D], залить=False)
    ч.многоугольник([прочие[0], X, прочие[1]])          # искомый треугольник — заливкой
    ч.отрезок(верх_т, P, вспомогательный=True)            # продолжение основания BC
    ч.отрезок(P, Q, пунктир=True)                         # перпендикуляр через середину
    ч.прямой_угол(P, X, верх_т, размер=0.4)
    ч.прямой_угол(Q, X, низ_т, размер=0.4)
    ч.равенство(верх_т, X)
    ч.равенство(X, низ_т)
    ч.равенство(X, P, штрихов=2)
    ч.равенство(X, Q, штрихов=2)
    ч.дуга_угла(X, верх_т, P, радиус=0.9)                 # вертикальные углы при середине
    ч.дуга_угла(X, низ_т, Q, радиус=0.9)
    подписать_вершины(ч, *подписи)
    ч.вершина(P, 'P', подпись_P)
    ч.вершина(Q, 'Q', 'ю')
    ч.подпись(середина(B, C), 'a', 'с')
    ч.подпись(середина(A, D), 'b', 'ю')

    return {
        'title': 'Трапеция: треугольник с вершиной в середине боковой стороны — половина трапеции',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Прямая, перпендикулярная одной из двух параллельных прямых, перпендикулярна '
            'и второй; из точки к прямой можно провести только один перпендикуляр.',
            'Прямоугольные треугольники равны по гипотенузе и острому углу; '
            'вертикальные углы равны; соответственные элементы равных треугольников равны.',
            'Площадь треугольника — половина произведения основания на высоту; '
            'площадь трапеции — произведение полусуммы оснований на высоту.',
            'Площадь фигуры, разрезанной на части без наложений, равна сумме '
            'площадей частей.',
        ],
        'params': {
            'сторона': сторона, 'середина': б['X'], 'вопрос': вопрос,
            'BC': round(низ_ш - слева - справа, 2), 'AD': низ_ш, 'H': round(H, 2),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 5. Диагонали трапеции: треугольники при боковых сторонах равновелики.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация. Трапеция ABCD с основаниями BC и AD (BC ∥ AD), диагонали AC и
# BD пересекаются в точке P (в другой редакции банка — O). Диагонали режут
# трапецию на четыре треугольника; два из них прилегают к основаниям (BPC и
# APD), два — к боковым сторонам (APB и CPD). Доказать нужно, что S(APB) =
# S(CPD). Чисел в условии нет и быть не может: в трапеции площади всех четырёх
# кусков жёстко связаны (S(APB)² = S(BPC)·S(APD)), и любая внесённая цифра либо
# избыточна, либо противоречива.
#
# Ключевой ход — не смотреть на сами треугольники APB и CPD (они, вообще
# говоря, не равны и даже не подобны), а «нарастить» каждый до большого
# треугольника с общим основанием AD: ABD = APB + APD и ACD = CPD + APD.
# У треугольников ABD и ACD одна сторона AD и высоты к ней — это высоты
# трапеции BH и CK. Они равны, потому что BC ∥ AD: точки одной из параллельных
# прямых равноудалены от другой (на уровне 8 класса — HBCK параллелограмм,
# противоположные стороны равны). Значит, S(ABD) = S(ACD), а после вычитания
# общего куска APD остаётся то, что требовалось.
#
# Почему это работает только при BC ∥ AD: равенство высот держится на
# параллельности оснований. Если BC ∦ AD, то BH ≠ CK и утверждение ложно
# (более того, для выпуклого четырёхугольника S(APB) = S(CPD) равносильно
# BC ∥ AD: из AP·PB = CP·PD и вертикальных углов при P следует подобие APD и
# CPB, а с ним накрест лежащие углы при секущей AC). Слово «выпуклого»
# обязательно: для невыпуклого четырёхугольника с диагоналями-прямыми
# A(−2,0), B(0,1), C(1,0), D(0,2), P(0,0) площади равны (обе 1), а BC ∦ AD.
# Это стоит проговорить ученику, чтобы он не тянул результат на «любые
# диагонали». Для
# параллелограмма утверждение верно, но он в школьном курсе трапецией не
# считается, поэтому в замечании для ученика говорим не «не трапеция», а
# «стороны BC и AD не параллельны».
#
# Ловушки при написании.
# * Написать «треугольники APB и CPD равны» вместо «равновелики»/«равны по
#   площади» — грубая ошибка: у них нет ни равных сторон, ни равных углов,
#   кроме вертикальных при P.
# * Сказать «высоты равны» без обоснования — эксперт снимет балл; нужна
#   ссылка на расстояние между параллельными прямыми или на параллелограмм
#   HBCK.
# * Симметричный путь через основание BC (треугольники ABC и DBC) верен, но
#   основания высот из A и D падают на продолжение BC — чертёж грязнее, а
#   формула ½·a·h от этого не меняется. Здесь взят путь через AD: основания
#   высот лежат внутри отрезка AD, чертёж читается сразу.
#
# Вариативность: буква точки пересечения (P или O), три редакции формулировки
# и посадка трапеции (отношение оснований, высота, разные наклоны боковых
# сторон — чтобы картинка не была равнобокой и не походила на прямоугольник).


@сюжет(5)
def _сюжет_5(rng):
    # Буква точки пересечения: в банке две одинаковые задачи, различающиеся
    # только этим. P чаще — так в условии Школково; O — редакция Ященко.
    т = rng.choice(['P', 'P', 'O'])

    формулировки = [
        '<p>Диагонали \\(AC\\) и \\(BD\\) трапеции \\(ABCD\\) '
        '(\\(BC \\parallel AD\\)) пересекаются в точке \\(%s\\). Докажите, что '
        'треугольник \\(A%sB\\) равновелик треугольнику \\(C%sD\\).</p>'
        % (т, т, т),

        '<p>Отрезки \\(AC\\) и \\(BD\\) — диагонали трапеции \\(ABCD\\) '
        'с основаниями \\(AD\\) и \\(BC\\), \\(%s\\) — их общая точка. '
        'Докажите, что площадь треугольника \\(A%sB\\) равна площади '
        'треугольника \\(C%sD\\).</p>' % (т, т, т),

        '<p>Пусть \\(%s\\) — точка пересечения диагоналей трапеции \\(ABCD\\) '
        'с основаниями \\(BC\\) и \\(AD\\). Докажите, что два треугольника, '
        'прилежащие к боковым сторонам трапеции, — \\(A%sB\\) и \\(C%sD\\) — '
        'равновелики.</p>' % (т, т, т),
    ]
    номер_формулировки = rng.randrange(len(формулировки))
    условие = формулировки[номер_формулировки]

    доказательство = (
        '<p>1. Дополнительное построение. Проведём высоты трапеции \\(BH\\) и '
        '\\(CK\\): \\(BH \\perp AD\\), \\(CK \\perp AD\\), точки \\(H\\) и \\(K\\) '
        'лежат на прямой \\(AD\\). Две прямые, перпендикулярные одной и той же '
        'прямой, параллельны, поэтому \\(BH \\parallel CK\\). Кроме того, '
        '\\(BC \\parallel HK\\), так как \\(BC \\parallel AD\\) по определению '
        'трапеции. В четырёхугольнике \\(HBCK\\) противоположные стороны '
        'попарно параллельны, значит, \\(HBCK\\) — параллелограмм по '
        'определению, и \\(BH = CK\\) как противоположные стороны '
        'параллелограмма. Иначе говоря, обе '
        'высоты равны расстоянию между параллельными прямыми \\(BC\\) и '
        '\\(AD\\).</p>'

        '<p>2. Рассмотрим треугольники \\(ABD\\) и \\(ACD\\). У них общая '
        'сторона \\(AD\\), а высоты, опущенные на неё из вершин \\(B\\) и '
        '\\(C\\), — это \\(BH\\) и \\(CK\\). По формуле площади треугольника</p>'
        '\\[S_{ABD} = \\frac{1}{2}\\, AD \\cdot BH, \\qquad '
        'S_{ACD} = \\frac{1}{2}\\, AD \\cdot CK.\\]'
        '<p>Так как \\(BH = CK\\), правые части равны, откуда '
        '\\(S_{ABD} = S_{ACD}\\).</p>'

        '<p>3. Трапеция — выпуклый четырёхугольник, а диагонали выпуклого '
        'четырёхугольника пересекаются, и точка пересечения лежит внутри '
        'каждой из них. Поэтому точка \\(%(т)s\\) лежит внутри отрезка '
        '\\(BD\\) и внутри отрезка \\(AC\\). Отрезок \\(A%(т)s\\) делит '
        'треугольник \\(ABD\\) на треугольники \\(A%(т)sB\\) и \\(A%(т)sD\\), '
        'а отрезок \\(D%(т)s\\) делит треугольник \\(ACD\\) на треугольники '
        '\\(C%(т)sD\\) и \\(A%(т)sD\\). Если многоугольник составлен из '
        'нескольких многоугольников, то его площадь равна сумме их '
        'площадей:</p>'
        '\\[S_{ABD} = S_{A%(т)sB} + S_{A%(т)sD}, \\qquad '
        'S_{ACD} = S_{C%(т)sD} + S_{A%(т)sD}.\\]'

        '<p>4. Левые части этих равенств равны по пункту 2, а в правых '
        'частях есть общее слагаемое \\(S_{A%(т)sD}\\). Значит, равны и '
        'оставшиеся слагаемые:</p>'
        '\\[S_{A%(т)sB} = S_{ABD} - S_{A%(т)sD} = S_{ACD} - S_{A%(т)sD} '
        '= S_{C%(т)sD},\\]'
        '<p>что и требовалось доказать.</p>'

        '<p><i>Замечание.</i> Сами треугольники \\(A%(т)sB\\) и \\(C%(т)sD\\), '
        'вообще говоря, не равны (равны они только в равнобедренной трапеции): '
        'в общем случае у них нет ни равных сторон, ни равных углов, кроме '
        'вертикальных при \\(%(т)s\\). Доказано только равенство площадей, и '
        'держится оно на параллельности оснований \\(BC \\parallel AD\\) — для '
        'выпуклого четырёхугольника \\(ABCD\\), у которого стороны \\(BC\\) и '
        '\\(AD\\) не параллельны, утверждение неверно.</p>'
        % {'т': т})

    # Чертёж. AD = 10 внизу, BC сверху. Основания высот H и K должны лежать
    # внутри отрезка AD (для этого оба свеса — левый a и правый c — строго
    # положительны), боковые стороны — с разными наклонами (a ≠ c), чтобы
    # трапеция не выглядела равнобокой, и не круче ~75°, чтобы не походила
    # на прямоугольник. Высота 4–5 при AD = 10 даёт учебниковую пропорцию.
    # Ещё одно требование — к штрихам «BH = CK»: они стоят на серединах
    # высот, а диагональ AC пересекает BH на высоте h·a/(a+BC), диагональ BD
    # пересекает CK на высоте h·c/(c+BC). Если точка пересечения подходит к
    # середине ближе чем на 0,3 (≈10 px), штрих ложится на диагональ и
    # читается как её пометка. Отсюда условие на зазор.
    AD_дл = 10.0
    while True:
        BC_дл = rng.choice([3.5, 4.0, 4.5, 5.0, 5.5, 6.0])
        a = rng.choice([1.5, 2.0, 2.5, 3.0, 3.5])
        h = rng.choice([4.0, 4.5, 5.0])
        c = AD_дл - a - BC_дл
        зазор_BH = h * abs(BC_дл - a) / (2 * (a + BC_дл))
        зазор_CK = h * abs(BC_дл - c) / (2 * (c + BC_дл))
        if c >= 1.5 and abs(a - c) >= 0.5 and min(зазор_BH, зазор_CK) >= 0.3:
            break

    A, D = (0.0, 0.0), (AD_дл, 0.0)
    B, C = (a, h), (a + BC_дл, h)
    P = пересечение(A, C, B, D)
    H = проекция(A, D, B)
    K = проекция(A, D, C)

    ч = Чертёж()
    ч.многоугольник([A, B, C, D])
    # Диагонали даны условием — рисуем сплошными.
    ч.отрезок(A, C)
    ч.отрезок(B, D)
    # Высоты — дополнительное построение: пунктир и серый.
    ч.отрезок(B, H, пунктир=True, вспомогательный=True)
    ч.отрезок(C, K, пунктир=True, вспомогательный=True)
    ч.прямой_угол(H, B, D, размер=0.35)
    ч.прямой_угол(K, C, D, размер=0.35)
    # Штрихи «BH = CK» — то, на чём стоит всё доказательство.
    ч.равенство(B, H)
    ч.равенство(C, K)
    # Подпись точки пересечения ставим сверху: угол BPC — самый широкий из
    # четырёх (он равен углу APD, а тот тупой при коротком BC), там подпись
    # не налезает на диагонали.
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'), (H, 'H', 'ю'), (K, 'K', 'ю'),
                      (P, т, 'с'))

    return {
        'title': 'Трапеция: треугольники при боковых сторонах равновелики',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Определение трапеции: основания параллельны, \\(BC \\parallel AD\\).',
            'Две прямые, перпендикулярные одной и той же прямой, параллельны.',
            'Определение параллелограмма: четырёхугольник, у которого '
            'противоположные стороны попарно параллельны; свойство '
            'параллелограмма: противоположные стороны равны.',
            'Все точки одной из двух параллельных прямых равноудалены от другой: '
            'высоты трапеции, проведённые из разных вершин одного основания, равны.',
            'Площадь треугольника равна половине произведения стороны на '
            'проведённую к ней высоту; треугольники с общей стороной и равными '
            'высотами к ней равновелики.',
            'Трапеция — выпуклый четырёхугольник; диагонали выпуклого '
            'четырёхугольника пересекаются, точка пересечения лежит внутри каждой.',
            'Если многоугольник составлен из нескольких многоугольников, то его '
            'площадь равна сумме их площадей.',
        ],
        'params': {
            'точка': т,
            'формулировка': номер_формулировки,
            'AD': AD_дл, 'BC': BC_дл, 'h': h,
            'свес_слева': a, 'свес_справа': c,
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 6. Биссектрисы двух углов при одной стороне пересекаются на
# ────────────────────────────────────────────────────────────────────────
#
# противоположной стороне: точка пересечения равноудалена от трёх прямых.
#
# Конфигурация. Выпуклый четырёхугольник ABCD; в половине задач банка это
# трапеция с основаниями AD и BC, и тогда речь идёт об углах при боковой
# стороне. Проведены биссектрисы двух углов при концах одной стороны (скажем,
# углов A и B), и дано, что они пересекаются в точке K, лежащей на
# противоположной стороне CD. Доказать: K одинаково удалена от прямых AB, AD и
# BC. Четвёртая прямая CD в списке не участвует — точка лежит на ней.
#
# Ключевой ход. Расстояние до прямой — это перпендикуляр, поэтому из K
# опускаем три перпендикуляра: на AB (общую сторону двух углов), на AD и на
# BC. Пара прямоугольных треугольников при вершине A (общая гипотенуза AK,
# равные острые углы от биссектрисы) равна по гипотенузе и острому углу —
# отсюда равны перпендикуляры к AD и к AB. Такая же пара при вершине B даёт
# равенство перпендикуляров к AB и к BC. Перпендикуляр к общей стороне AB
# входит в обе пары и склеивает два равенства в одно: все три расстояния равны.
#
# Почему это работает. По сути это дважды применённое свойство биссектрисы
# (её точки равноудалены от сторон угла); общая сторона AB — «мост», по
# которому равенство передаётся от одного угла к другому. Условие «K лежит на
# CD» и параллельность оснований трапеции в доказательстве не используются
# вовсе: они нужны лишь для честной постановки задачи (иначе пришлось бы
# говорить о четырёх прямых) и для того, чтобы чертёж существовал.
#
# Ловушки.
# * Биссектрисы обязаны выходить из соседних вершин. У противоположных вершин
#   общей стороны нет, «мост» исчезает, и утверждение становится ложным.
# * Основание перпендикуляра может попасть не на сторону, а на её продолжение.
#   В трапеции это неизбежно: K равноудалена от параллельных оснований и лежит
#   на боковой стороне, значит K — середина этой стороны, и проекции K на оба
#   основания лежат на одном перпендикуляре к ним; одна из проекций выходит за
#   край своего основания (исключение — CD ⊥ основаниям: тогда проекции —
#   сами вершины C и D; такой угол генератор не выдаёт). Поэтому в условии
#   говорится о расстоянии до прямых,
#   а на чертеже продолжение стороны показано пунктиром.
# * Конфигурация трапеции жёсткая: расстояние от середины CD до AB равно
#   (BC + AD)·h / (2·AB), а должно равняться h/2, откуда AB = BC + AD — боковая
#   сторона равна сумме оснований. Такая трапеция обязательно высокая и с
#   сильно разными основаниями. Поэтому чертёж сажаем двумя способами: с
#   острым углом при D (привычный вид, но высокий) и с тупым углом при D
#   (верхнее основание выступает за нижнее, пропорции ближе к квадрату). В
#   обоих случаях угол D держим подальше от 90°, иначе трапеция читается как
#   прямоугольная.
# * Признак равенства надо назвать точно: «по гипотенузе и острому углу», а не
#   «по двум сторонам» — равенство катетов ещё только предстоит доказать.
# * У произвольного четырёхугольника углы C и D сделаны острыми (тогда все три
#   основания перпендикуляров попадают на сами стороны), а сумма углов A и B
#   заметно отличается от 180°, чтобы фигура не читалась как трапеция.


# ── маленькая векторная арифметика ────────────────────────────────────────

def _луч(P, угол_град):
    """Вторая точка луча из P под данным углом к оси x (против часовой)."""
    a = radians(угол_град)
    return (P[0] + cos(a), P[1] + sin(a))


def _повернуть(p, угол_град):
    a = radians(угол_град)
    return (p[0] * cos(a) - p[1] * sin(a), p[0] * sin(a) + p[1] * cos(a))


def _расстояние(P, Q):
    return hypot(Q[0] - P[0], Q[1] - P[1])


def _единичный_6(v):
    d = hypot(v[0], v[1]) or 1.0
    return (v[0] / d, v[1] / d)


def _сумма(*векторы):
    return (sum(v[0] for v in векторы), sum(v[1] for v in векторы))


def _умножить(v, k):
    return (v[0] * k, v[1] * k)


def _вектор(P, Q):
    return (Q[0] - P[0], Q[1] - P[1])


def _доля_6(P, Q, F):
    """Положение точки F прямой PQ: 0 — в P, 1 — в Q, больше 1 — за Q."""
    ux, uy = Q[0] - P[0], Q[1] - P[1]
    return ((F[0] - P[0]) * ux + (F[1] - P[1]) * uy) / float(ux * ux + uy * uy)


def _компас(v):
    """Сторона подписи по направлению «от фигуры наружу»."""
    a = degrees(atan2(v[1], v[0])) % 360
    стороны = ['в', 'св', 'с', 'сз', 'з', 'юз', 'ю', 'юв']
    return стороны[int((a + 22.5) // 45) % 8]


def _сторона_подписи(желаемое, нормаль, зазор_px=8.0):
    """Сторона подписи точки, лежащей на прямой с данной внешней нормалью.

    Из восьми сторон берём ближайшую к желаемому направлению, но только среди
    тех, при которых центр буквы отстоит от самой прямой не меньше чем на
    зазор_px: грубая восьмирумбовая сетка иначе кладёт букву на наклонную
    сторону (смещение «ю» почти параллельно крутой боковой стороне).
    """
    лучшая, лучший_балл = None, None
    for сторона, (dx, dy) in СТОРОНЫ.items():
        # Экранное смещение → мировое (ось y вверх); центр буквы стоит
        # примерно на 4,5 px выше базовой линии текста.
        v = (dx, -(dy - 4.5))
        зазор = v[0] * нормаль[0] + v[1] * нормаль[1]
        балл = (v[0] * желаемое[0] + v[1] * желаемое[1]) / hypot(*v)
        if зазор < зазор_px:
            балл -= 100.0
        if лучший_балл is None or балл > лучший_балл:
            лучшая, лучший_балл = сторона, балл
    return лучшая


def _наружу_из_вершины(V, соседняя1, соседняя2):
    """Направление подписи вершины — против биссектрисы её угла."""
    u1 = _единичный_6(_вектор(V, соседняя1))
    u2 = _единичный_6(_вектор(V, соседняя2))
    return _умножить(_сумма(u1, u2), -1.0)


def _нормаль_наружу(P, Q, центр):
    """Единичная нормаль к стороне PQ, смотрящая прочь от центра фигуры."""
    u = _единичный_6(_вектор(P, Q))
    n = (-u[1], u[0])
    M = середина(P, Q)
    if n[0] * (M[0] - центр[0]) + n[1] * (M[1] - центр[1]) < 0:
        n = (-n[0], -n[1])
    return n


# ── построение конфигурации ───────────────────────────────────────────────

def _четырёхугольник(угол1, угол2, угол4, сторона):
    """Точки V1, V2, V3, V4 и K в системе, где V1 = (0, 0), V2 = (сторона, 0).

    угол1, угол2 — углы при V1 и V2 (из них выходят биссектрисы), угол4 —
    угол при V4. K — пересечение биссектрис. V4 берём на луче из V1 на таком
    расстоянии, чтобы угол при V4 равнялся заданному: в треугольнике V1 K V4
    известны угол при V1 (половина угла1), угол при V4 и сторона V1K, и
    теорема синусов даёт V1V4. V3 — пересечение прямой V4K с лучом из V2.
    Так точка K гарантированно лежит на стороне V3V4, а не наоборот
    подбирается к готовой фигуре.
    """
    V1 = (0.0, 0.0)
    V2 = (сторона, 0.0)
    α, β = угол1 / 2.0, угол2 / 2.0
    K = пересечение(V1, _луч(V1, α), V2, _луч(V2, 180.0 - β))
    d = _расстояние(V1, K) * sin(radians(α + угол4)) / sin(radians(угол4))
    V4 = (d * cos(radians(угол1)), d * sin(radians(угол1)))
    V3 = пересечение(V4, K, V2, _луч(V2, 180.0 - угол2))
    return V1, V2, V3, V4, K


def _выпуклый(точки):
    """Все повороты в вершинах в одну сторону."""
    знаки = []
    n = len(точки)
    for i in range(n):
        P, Q, R = точки[i], точки[(i + 1) % n], точки[(i + 2) % n]
        зн = (Q[0] - P[0]) * (R[1] - Q[1]) - (Q[1] - P[1]) * (R[0] - Q[0])
        знаки.append(зн > 0)
    return all(знаки) or not any(знаки)


@сюжет(6)
def _сюжет_6(rng):
    трапеция = rng.random() < 0.5
    # Из каких вершин выходят биссектрисы: A и B (точка на CD) или C и D
    # (точка на AB). Второй вариант — зеркальное отражение первого, геометрия
    # строится одна и та же, меняются только буквы и посадка чертежа.
    из_CD = rng.random() < 0.5
    сторона = 6.0

    # Роли точек: V1, V2 — концы общей стороны, из них идут биссектрисы;
    # V4 — сосед V1, V3 — сосед V2; K лежит на V3V4.
    #
    # У трапеции две посадки. Конфигурация жёсткая (AB = AD + BC), поэтому
    # «обычная» трапеция с острым углом при V4 выходит высокой; вторая
    # посадка — с тупым углом при V4, верхнее основание выступает за нижнее,
    # обе боковые стороны наклонены в одну сторону — ближе к квадрату по
    # пропорциям. В обоих случаях угол при V4 держим подальше от 90°, иначе
    # трапеция читается как прямоугольная.
    наклонная = трапеция and rng.random() < 0.5
    while True:
        if трапеция:
            # Углы при боковой стороне V1V2 в сумме 180°.
            if наклонная:
                угол1 = rng.uniform(54, 64)
                угол4 = rng.uniform(100, 108)   # проекция K на нижнее основание выйдет за V4
            else:
                угол1 = rng.uniform(70, 76)
                угол4 = rng.uniform(74, 80)     # проекция K на верхнее основание выйдет за V3
            угол2 = 180.0 - угол1
        else:
            # Оба угла при общей стороне тупые: их сумма далека от 180°, и
            # фигура не похожа на трапецию; углы при V3 и V4 острые, поэтому
            # все три основания перпендикуляров ложатся на сами стороны.
            угол1 = rng.uniform(96, 110)
            угол2 = rng.uniform(114, 130)
            угол4 = rng.uniform(60, 76)
        угол3 = 360.0 - угол1 - угол2 - угол4
        if not трапеция and not (58.0 <= угол3 <= 76.0):
            continue
        V1, V2, V3, V4, K = _четырёхугольник(угол1, угол2, угол4, сторона)
        if not _выпуклый([V1, V2, V3, V4]):
            continue
        if not (0.05 < _доля_6(V4, V3, K) < 0.95):
            continue
        if трапеция:
            отношение = _расстояние(V1, V4) / _расстояние(V2, V3)
            if not (1.6 <= отношение <= 3.3):
                continue
        break

    # Посадка. Трапецию кладём основаниями горизонтально: поворачиваем так,
    # чтобы V1V4 легло на ось x, и отражаем, чтобы фигура была над осью.
    # Четырёхугольник оставляем общей стороной вниз. Для варианта «из C и D»
    # зеркалим: у трапеции слева направо, у четырёхугольника сверху вниз.
    точки = [V1, V2, V3, V4, K]
    if трапеция:
        точки = [_повернуть(p, -угол1) for p in точки]
        точки = [(x, -y) for x, y in точки]
    if из_CD:
        точки = [(-x, y) for x, y in точки] if трапеция else [(x, -y) for x, y in точки]
    V1, V2, V3, V4, K = точки

    if из_CD:
        буква = {'V1': 'D', 'V2': 'C', 'V3': 'B', 'V4': 'A'}
    else:
        буква = {'V1': 'A', 'V2': 'B', 'V3': 'C', 'V4': 'D'}
    X, Y, Z, W = буква['V1'], буква['V2'], буква['V3'], буква['V4']

    def имя_стороны(p, q):
        return ''.join(sorted([p, q]))

    общая = имя_стороны(X, Y)          # AB или CD
    сторона_X = имя_стороны(X, W)      # AD
    сторона_Y = имя_стороны(Y, Z)      # BC
    сторона_K = имя_стороны(Z, W)      # CD или AB
    угол_X, угол_Y = sorted([X, Y])

    имя_K = rng.choice(['K', 'O', 'P', 'M'])
    запас = [б for б in ['E', 'F', 'H', 'L', 'M', 'N', 'T'] if б != имя_K]
    f_общ, f_X, f_Y = sorted(rng.sample(запас, 3))

    # Основания перпендикуляров.
    F_общ = проекция(V1, V2, K)
    F_X = проекция(V1, V4, K)
    F_Y = проекция(V2, V3, K)
    F_X_за_краем = _доля_6(V1, V4, F_X) > 1.0
    F_Y_за_краем = _доля_6(V2, V3, F_Y) > 1.0

    # ── условие ───────────────────────────────────────────────────────────
    п = {
        'X': X, 'Y': Y, 'Z': Z, 'W': W, 'K': имя_K,
        'f0': f_общ, 'fX': f_X, 'fY': f_Y,
        's0': общая, 'sX': сторона_X, 'sY': сторона_Y, 'sK': сторона_K,
        'uX': угол_X, 'uY': угол_Y,
    }
    if трапеция:
        начало = ('<p>В трапеции \\(ABCD\\) с основаниями \\(AD\\) и \\(BC\\) '
                  'биссектрисы углов \\(%(uX)s\\) и \\(%(uY)s\\) пересекаются в '
                  'точке \\(%(K)s\\), лежащей на боковой стороне \\(%(sK)s\\). ')
    else:
        начало = ('<p>В выпуклом четырёхугольнике \\(ABCD\\) биссектрисы углов '
                  '\\(%(uX)s\\) и \\(%(uY)s\\) пересекаются в точке \\(%(K)s\\), '
                  'лежащей на стороне \\(%(sK)s\\). ')
    вопрос = rng.choice([
        'Докажите, что точка \\(%(K)s\\) равноудалена от прямых '
        '\\(%(s0)s\\), \\(%(sX)s\\) и \\(%(sY)s\\).</p>',
        'Докажите, что расстояния от точки \\(%(K)s\\) до прямых '
        '\\(%(s0)s\\), \\(%(sX)s\\) и \\(%(sY)s\\) равны.</p>',
    ])
    условие = (начало + вопрос) % п

    # ── доказательство ────────────────────────────────────────────────────
    if F_X_за_краем:
        про_край = (' На чертеже основание \\(%(fX)s\\) попало на продолжение '
                    'стороны \\(%(sX)s\\) за точку \\(%(W)s\\) — это не мешает: '
                    'расстояние измеряется до прямой, а не до отрезка.')
    elif F_Y_за_краем:
        про_край = (' На чертеже основание \\(%(fY)s\\) попало на продолжение '
                    'стороны \\(%(sY)s\\) за точку \\(%(Z)s\\) — это не мешает: '
                    'расстояние измеряется до прямой, а не до отрезка.')
    else:
        про_край = (' Если бы какое-то из оснований попало не на сторону, а на '
                    'её продолжение, рассуждение не изменилось бы: расстояние '
                    'измеряется до прямой.')

    доказательство = (
        '<p>1. Расстояние от точки до прямой — это длина перпендикуляра, '
        'опущенного из точки на эту прямую. Поэтому опустим из точки '
        '\\(%(K)s\\) перпендикуляры на все три прямые: '
        '\\(%(K)s%(fX)s \\perp %(sX)s\\), \\(%(K)s%(f0)s \\perp %(s0)s\\), '
        '\\(%(K)s%(fY)s \\perp %(sY)s\\); точки \\(%(fX)s\\), \\(%(f0)s\\), '
        '\\(%(fY)s\\) — основания перпендикуляров.' + про_край +
        ' Требуется доказать, что '
        '\\(%(K)s%(fX)s = %(K)s%(f0)s = %(K)s%(fY)s\\).</p>'

        '<p>2. Рассмотрим треугольники \\(%(X)s%(K)s%(fX)s\\) и '
        '\\(%(X)s%(K)s%(f0)s\\). Оба они прямоугольные: углы при вершинах '
        '\\(%(fX)s\\) и \\(%(f0)s\\) прямые по построению. Гипотенуза '
        '\\(%(X)s%(K)s\\) у них общая. Острые углы при вершине \\(%(X)s\\) '
        'равны: \\(\\angle %(K)s%(X)s%(fX)s = \\angle %(K)s%(X)s%(f0)s\\), '
        'так как по условию \\(%(X)s%(K)s\\) — биссектриса угла \\(%(X)s\\), '
        'а точки \\(%(fX)s\\) и \\(%(f0)s\\) лежат на лучах \\(%(X)s%(W)s\\) и '
        '\\(%(X)s%(Y)s\\), то есть на сторонах этого угла. Основания попадают '
        'именно на эти лучи, а не на их продолжения за точку \\(%(X)s\\): '
        'углы \\(%(K)s%(X)s%(W)s\\) и \\(%(K)s%(X)s%(Y)s\\) равны половине '
        'угла \\(%(X)s\\) четырёхугольника и потому острые; если бы, например, '
        'основание \\(%(fX)s\\) лежало на продолжении луча \\(%(X)s%(W)s\\) за '
        'точку \\(%(X)s\\), то в прямоугольном треугольнике '
        '\\(%(X)s%(K)s%(fX)s\\) угол при вершине \\(%(X)s\\) равнялся бы '
        '\\(180^\\circ - \\angle %(K)s%(X)s%(W)s\\), то есть был бы тупым, что '
        'невозможно. Следовательно, '
        '\\(\\triangle %(X)s%(K)s%(fX)s = \\triangle %(X)s%(K)s%(f0)s\\) по '
        'гипотенузе и острому углу (признак равенства прямоугольных '
        'треугольников). В равных треугольниках против равных углов лежат '
        'равные стороны, поэтому катеты, лежащие против равных углов при '
        'вершине \\(%(X)s\\), равны: \\(%(K)s%(fX)s = %(K)s%(f0)s\\).</p>'

        '<p>3. Точно так же рассмотрим прямоугольные треугольники '
        '\\(%(Y)s%(K)s%(f0)s\\) и \\(%(Y)s%(K)s%(fY)s\\) (углы при вершинах '
        '\\(%(f0)s\\) и \\(%(fY)s\\) прямые). Гипотенуза \\(%(Y)s%(K)s\\) '
        'общая, а \\(\\angle %(K)s%(Y)s%(f0)s = \\angle %(K)s%(Y)s%(fY)s\\), '
        'потому что \\(%(Y)s%(K)s\\) — биссектриса угла \\(%(Y)s\\), а точки '
        '\\(%(f0)s\\) и \\(%(fY)s\\) лежат на его сторонах — лучах '
        '\\(%(Y)s%(X)s\\) и \\(%(Y)s%(Z)s\\) (а не на их продолжениях за '
        'точку \\(%(Y)s\\) — по той же причине: половина угла \\(%(Y)s\\) — '
        'острый угол). Значит, '
        '\\(\\triangle %(Y)s%(K)s%(f0)s = \\triangle %(Y)s%(K)s%(fY)s\\) по '
        'гипотенузе и острому углу, и катеты против равных углов при вершине '
        '\\(%(Y)s\\) равны: \\(%(K)s%(f0)s = %(K)s%(fY)s\\).</p>'

        '<p>4. Перпендикуляр \\(%(K)s%(f0)s\\) к общей стороне \\(%(s0)s\\) '
        'вошёл в обе пары треугольников, и через него два равенства '
        'соединяются в одну цепочку: из пунктов 2 и 3 получаем '
        '\\[%(K)s%(fX)s = %(K)s%(f0)s = %(K)s%(fY)s.\\] '
        'Это и означает, что расстояния от точки \\(%(K)s\\) до прямых '
        '\\(%(sX)s\\), \\(%(s0)s\\) и \\(%(sY)s\\) равны, то есть точка '
        '\\(%(K)s\\) равноудалена от этих трёх прямых. Что и требовалось '
        'доказать.</p>'
    ) % п

    if трапеция:
        доказательство += (
            '<p><i>Замечание.</i> Параллельность оснований в рассуждении не '
            'понадобилась: утверждение верно для любого выпуклого '
            'четырёхугольника, у которого биссектрисы двух углов при одной '
            'стороне пересекаются на противоположной стороне. Не понадобилось '
            'и то, что точка \\(%(K)s\\) лежит именно на стороне \\(%(sK)s\\) '
            '(использовано лишь то, что она лежит на обеих биссектрисах): это '
            'условие объясняет, почему прямая \\(%(sK)s\\) не входит в список — '
            'расстояние до неё равно нулю.</p>') % п

    # ── чертёж ────────────────────────────────────────────────────────────
    # Размеры пометок задаём в пикселях и пересчитываем в мировые единицы по
    # ожидаемому масштабу: иначе у высокой трапеции и широкого
    # четырёхугольника дужки и квадратики получились бы разной величины.
    ч = Чертёж(width=380, height=(330 if трапеция else 280))
    все = [V1, V2, V3, V4, K, F_общ, F_X, F_Y]
    xs, ys = [p[0] for p in все], [p[1] for p in все]
    k_ожид = min((ч.width - 2 * ч.поле) / (max(xs) - min(xs)),
                 (ч.height - 2 * ч.поле) / (max(ys) - min(ys)))
    радиус_дуги = 26.0 / k_ожид
    квадратик = 14.0 / k_ожид
    хвост = 22.0 / k_ожид          # на сколько продлить пунктир за основание

    ч.многоугольник([V1, V2, V3, V4])
    # Биссектрисы — часть условия, рисуем обычной линией, чуть тоньше сторон.
    ч.отрезок(V1, K, ширина=1.3)
    ч.отрезок(V2, K, ширина=1.3)

    # Продолжения сторон там, где основание перпендикуляра вышло за край.
    # Хвост за основание нужен, чтобы квадратику прямого угла было на чём
    # стоять с дальней от вершины стороны.
    if F_X_за_краем:
        конец = _сумма(F_X, _умножить(_единичный_6(_вектор(V4, F_X)), хвост))
        ч.отрезок(V4, конец, пунктир=True, вспомогательный=True)
    if F_Y_за_краем:
        конец = _сумма(F_Y, _умножить(_единичный_6(_вектор(V3, F_Y)), хвост))
        ч.отрезок(V3, конец, пунктир=True, вспомогательный=True)

    # Перпендикуляры — вспомогательное построение: серые, с прямыми углами и
    # штрихами равенства (равенство — то, что доказано).
    for F in (F_общ, F_X, F_Y):
        ч.отрезок(K, F, вспомогательный=True)
        ч.равенство(K, F)

    # Квадратик прямого угла ставим в сторону дальнего конца прямой: там
    # больше места и он не налезает на вершину.
    def квадрат(F, P, Q, за_краем):
        if за_краем:
            # На продолжении: в сторону хвоста, прочь от вершины Q.
            прочь = _сумма(F, _единичный_6(_вектор(Q, F)))
        else:
            прочь = P if _расстояние(F, P) > _расстояние(F, Q) else Q
        ч.прямой_угол(F, K, прочь, размер=квадратик)

    квадрат(F_общ, V1, V2, False)
    квадрат(F_X, V1, V4, F_X_за_краем)
    квадрат(F_Y, V2, V3, F_Y_за_краем)

    # Равные углы: при V1 по одной дужке, при V2 по две.
    ч.дуга_угла(V1, V4, K, радиус=радиус_дуги)
    ч.дуга_угла(V1, K, V2, радиус=радиус_дуги)
    ч.дуга_угла(V2, V1, K, радиус=радиус_дуги, штрихов=2)
    ч.дуга_угла(V2, K, V3, радиус=радиус_дуги, штрихов=2)

    # Подписи. Вершины — против биссектрисы угла; точки на сторонах — по
    # внешней нормали. Если основание перпендикуляра оказалось рядом с
    # вершиной, разводим их подписи в стороны друг от друга.
    центр = середина(середина(V1, V3), середина(V2, V4))
    близко = 1.1  # мировых единиц; при масштабе 35–50 px это 40–55 px

    направление_вершины = {
        'V1': _наружу_из_вершины(V1, V4, V2),
        'V2': _наружу_из_вершины(V2, V1, V3),
        'V3': _наружу_из_вершины(V3, V2, V4),
        'V4': _наружу_из_вершины(V4, V3, V1),
    }
    вершины = {'V1': V1, 'V2': V2, 'V3': V3, 'V4': V4}
    точки_на_сторонах = [
        (F_общ, f_общ, _нормаль_наружу(V1, V2, центр)),
        (F_X, f_X, _нормаль_наружу(V1, V4, центр)),
        (F_Y, f_Y, _нормаль_наружу(V2, V3, центр)),
        (K, имя_K, _нормаль_наружу(V3, V4, центр)),
    ]
    подписи_точек = []
    for P, имя, нормаль in точки_на_сторонах:
        направление = нормаль
        for роль, V in вершины.items():
            if _расстояние(P, V) < близко:
                от_вершины = _единичный_6(_вектор(V, P))
                направление = _сумма(направление, _умножить(от_вершины, 1.4))
                направление_вершины[роль] = _сумма(
                    направление_вершины[роль], _умножить(от_вершины, -1.4))
        # Сдвиг вдоль стороны не должен положить букву на саму сторону.
        подписи_точек.append((P, имя, _сторона_подписи(направление, нормаль)))

    подписать_вершины(ч, *[(вершины[р], буква[р], _компас(направление_вершины[р]))
                           for р in ('V1', 'V2', 'V3', 'V4')])
    подписать_вершины(ч, *подписи_точек)

    углы = {X: угол1, Y: угол2, Z: угол3, W: угол4}
    return {
        'title': 'Биссектрисы двух углов при одной стороне: точка их пересечения '
                 'равноудалена от трёх прямых',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Расстояние от точки до прямой — длина перпендикуляра, опущенного из '
            'этой точки на прямую.',
            'Биссектриса делит угол на два равных угла.',
            'Признак равенства прямоугольных треугольников: по гипотенузе и '
            'острому углу.',
            'В равных треугольниках против равных углов лежат равные стороны.',
        ],
        'params': {
            'фигура': 'трапеция' if трапеция else 'четырёхугольник',
            'посадка': ('наклонная' if наклонная else 'обычная') if трапеция else None,
            'биссектрисы_из': угол_X + угол_Y,
            'точка': имя_K,
            'точка_на': сторона_K,
            'основания_перпендикуляров': {общая: f_общ, сторона_X: f_X, сторона_Y: f_Y},
            'углы_град': {б: round(у, 1) for б, у in углы.items()},
            'основание_за_краем': (сторона_X if F_X_за_краем
                                   else сторона_Y if F_Y_за_краем else None),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 7. Середина боковой стороны трапеции равноудалена от концов другой
# ────────────────────────────────────────────────────────────────────────
#
# боковой стороны — трапеция прямоугольная.
#
# Конфигурация. Трапеция ABCD с основаниями AD и BC; M — середина боковой
# стороны AB; известно, что MC = MD. Доказать, что трапеция прямоугольная,
# то есть CD ⊥ AD. Зеркальный вариант — M на CD и MA = MB, тогда AB ⊥ AD.
# Чисел в сюжете нет: варьируются только боковая сторона, на которой взята
# середина, и форма вопроса («трапеция прямоугольная» / «угол D прямой»).
#
# Ключевой ход. Одно построение — N, середина второй боковой стороны, и
# отрезок MN. Этот отрезок играет две роли сразу. Как средняя линия трапеции
# он параллелен основаниям. Как отрезок из вершины M равнобедренного
# треугольника CMD (MC = MD) к середине основания CD он — медиана, а медиана
# к основанию равнобедренного треугольника есть высота: MN ⊥ CD. Остаётся
# склеить: CD перпендикулярна MN, а MN параллельна AD, значит CD
# перпендикулярна и AD.
#
# Почему это работает. Условие MC = MD означает, что M лежит на серединном
# перпендикуляре к CD. Серединный перпендикуляр проходит через N, а прямая MN
# — средняя линия, направление которой задано основаниями. Серединный
# перпендикуляр к боковой стороне может оказаться параллельным основаниям
# только тогда, когда сама боковая сторона им перпендикулярна.
#
# Ловушки.
# * MN ∥ AD надо обосновать именно как среднюю линию трапеции: M и N —
#   середины боковых сторон (не оснований!). Средняя линия треугольника тут
#   ни при чём — в треугольнике CMD отрезок MN выходит из вершины, это медиана.
# * Из MN ⊥ CD нельзя сразу писать CD ⊥ AD: нужен переход «прямая,
#   перпендикулярная одной из двух параллельных, перпендикулярна и другой».
# * «Трапеция прямоугольная» — определение (есть прямой угол); в финале его
#   надо назвать, иначе доказано лишь CD ⊥ AD, а не то, что спрашивали.
#
# Другой путь (для сильных): продлить DM до пересечения с прямой BC в точке K.
# Треугольники AMD и BMK равны по стороне и двум прилежащим углам (AM = MB,
# вертикальные углы при M, накрест лежащие при AD ∥ BC), откуда MK = MD = MC.
# В треугольнике DCK медиана CM равна половине стороны DK, значит ∠DCK = 90°.


# Две зеркальные посадки одного сюжета. Буквы фигуры фиксированы (ABCD,
# основание AD внизу, BC сверху), меняется лишь боковая сторона, на которой
# взята середина M. Условие, доказательство и чертёж собираются из одного
# словаря, чтобы они не могли разойтись между собой.
#   X, Y — концы стороны с серединой (X на нижнем основании, Y на верхнем);
#   U, V — концы другой боковой стороны (U сверху, V снизу): именно она
#          окажется перпендикулярной основаниям.
ВАРИАНТЫ_7 = {
    'AB': dict(сторона='AB', другая='CD', X='A', Y='B', U='C', V='D',
               конец1='C', конец2='D',
               равные='MC = MD', треугольник='CMD',
               угол_низ='ADC', угол_верх='BCD'),
    'CD': dict(сторона='CD', другая='AB', X='D', Y='C', U='B', V='A',
               конец1='A', конец2='B',
               равные='MA = MB', треугольник='AMB',
               угол_низ='BAD', угол_верх='ABC'),
}


@сюжет(7)
def _сюжет_7(rng):
    ключ = rng.choice(['AB', 'CD'])
    формулировка = rng.choice(['трапеция', 'угол'])
    б = ВАРИАНТЫ_7[ключ]

    # ── условие ──────────────────────────────────────────────────────────
    # Три редакции вступления; ни одна не повторяет дословно формулировку
    # банка («В трапеции ABCD с основаниями AD и BC точка M — середина боковой
    # стороны AB, причём MC = MD»).
    начало = rng.choice([
        '<p>Основания трапеции \\(ABCD\\) — \\(AD\\) и \\(BC\\). Точка \\(M\\) — '
        'середина боковой стороны \\(%(сторона)s\\), и оказалось, что '
        '\\(%(равные)s\\). ',
        '<p>Точка \\(M\\) — середина боковой стороны \\(%(сторона)s\\) трапеции '
        '\\(ABCD\\) с основаниями \\(AD\\) и \\(BC\\). Известно, что '
        '\\(%(равные)s\\). ',
        '<p>В трапеции \\(ABCD\\) с основаниями \\(AD\\) и \\(BC\\) середина '
        '\\(M\\) боковой стороны \\(%(сторона)s\\) равноудалена от вершин '
        '\\(%(конец1)s\\) и \\(%(конец2)s\\), то есть \\(%(равные)s\\). ',
    ])
    if формулировка == 'трапеция':
        вопрос = 'Докажите, что трапеция \\(ABCD\\) прямоугольная.</p>'
    else:
        вопрос = 'Докажите, что \\(\\angle %(угол_низ)s = 90^\\circ\\).</p>'
    условие = (начало + вопрос) % б

    # ── доказательство ───────────────────────────────────────────────────
    # Шаги 1–4 общие для обеих формулировок: они доказывают перпендикулярность
    # боковой стороны основаниям. Различается только последний абзац — что
    # именно спрашивали и как это назвать.
    шаги = (
        '<p>1. Отметим точку \\(N\\) — середину боковой стороны \\(%(другая)s\\) — '
        'и проведём отрезок \\(MN\\). Точки \\(M\\) и \\(N\\) — середины боковых '
        'сторон трапеции \\(ABCD\\), поэтому \\(MN\\) — её средняя линия. '
        'По теореме о средней линии трапеции \\(MN \\parallel AD\\) и '
        '\\(MN \\parallel BC\\).</p>'
        '<p>2. Рассмотрим треугольник \\(%(треугольник)s\\). По условию '
        '\\(%(равные)s\\), значит, этот треугольник равнобедренный с основанием '
        '\\(%(другая)s\\). Отрезок \\(MN\\) соединяет вершину \\(M\\) с серединой '
        '\\(N\\) основания \\(%(другая)s\\), то есть \\(MN\\) — медиана '
        'треугольника \\(%(треугольник)s\\), проведённая к основанию.</p>'
        '<p>3. В равнобедренном треугольнике медиана, проведённая к основанию, '
        'является и высотой. Следовательно, \\(MN \\perp %(другая)s\\), то есть '
        '\\(\\angle MN%(U)s = \\angle MN%(V)s = 90^\\circ\\).</p>'
        '<p>4. По пункту 1 \\(MN \\parallel AD\\), по пункту 3 '
        '\\(%(другая)s \\perp MN\\). Прямая, перпендикулярная одной из двух '
        'параллельных прямых, перпендикулярна и другой. Значит, '
        '\\(%(другая)s \\perp AD\\), то есть \\(\\angle %(угол_низ)s = 90^\\circ\\). '
        'Точно так же из \\(MN \\parallel BC\\) получаем \\(%(другая)s \\perp BC\\) '
        'и \\(\\angle %(угол_верх)s = 90^\\circ\\).</p>'
    )
    if формулировка == 'трапеция':
        финал = (
            '<p>5. Трапеция называется прямоугольной, если один из её углов '
            'прямой. У трапеции \\(ABCD\\) угол \\(%(угол_низ)s\\) прямой '
            '(пункт 4), значит, она прямоугольная, что и требовалось доказать.</p>'
        )
    else:
        финал = (
            '<p>5. Итак, \\(\\angle %(угол_низ)s = 90^\\circ\\), что и требовалось '
            'доказать. Попутно получили, что трапеция \\(ABCD\\) прямоугольная: '
            'у неё есть прямой угол.</p>'
        )
    доказательство = (шаги + финал) % б

    # ── чертёж ───────────────────────────────────────────────────────────
    # Рисуем сразу «ответ»: боковая сторона UV вертикальна, тогда равенство
    # MU = MV выполняется само (M лежит на средней линии, а она — серединный
    # перпендикуляр к вертикальной UV). Нижнее основание длиннее верхнего,
    # чтобы трапеция выглядела как в учебнике; наклон второй боковой стороны
    # 45–59°, далеко и от «почти прямоугольника», и от вырожденной.
    h = 5.0
    низ = 10.0
    верх = rng.choice([5.0, 6.0, 7.0])
    if ключ == 'AB':
        A, B, C, D = (0.0, 0.0), (низ - верх, h), (низ, h), (низ, 0.0)
    else:
        A, B, C, D = (0.0, 0.0), (0.0, h), (верх, h), (низ, 0.0)
    точки = {'A': A, 'B': B, 'C': C, 'D': D}
    X, Y, U, V = (точки[б[имя]] for имя in ('X', 'Y', 'U', 'V'))
    M = середина(X, Y)
    N = середина(U, V)

    ч = Чертёж()
    ч.многоугольник([A, B, C, D])
    ч.отрезок(M, U)                    # данные отрезки MU = MV — сплошные
    ч.отрезок(M, V)
    ч.отрезок(M, N, пунктир=True)      # дополнительное построение
    # Три разных равенства — три разных пометки, чтобы штрихи не путались.
    ч.равенство(X, M, 1)
    ч.равенство(M, Y, 1)
    ч.равенство(M, U, 2)
    ч.равенство(M, V, 2)
    ч.равенство(U, N, 3)
    ч.равенство(N, V, 3)
    ч.прямой_угол(N, M, V, размер=0.4)  # шаг 3: MN ⊥ UV
    ч.прямой_угол(V, U, X)              # шаг 4: углы трапеции при UV прямые
    ч.прямой_угол(U, V, Y)
    # Подписи M и N выносим наружу трапеции. Наклонная сторона идёт снизу
    # вверх к середине чертежа, её внешняя нормаль смотрит вверх и наружу —
    # поэтому M подписываем по диагонали («сз»/«св»), а не строго вбок:
    # при чисто боковой подписи нижний край буквы ложится на линию (зазор
    # 2–4 px против 9–10 px по диагонали). У вертикальной стороны N просто
    # выносим на сторону, противоположную фигуре.
    подписать_вершины(
        ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'), (D, 'D', 'юв'),
        (M, 'M', 'сз' if ключ == 'AB' else 'св'),
        (N, 'N', 'в' if ключ == 'AB' else 'з'))

    return {
        'title': 'Трапеция: середина боковой стороны равноудалена от концов '
                 'другой боковой стороны',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Средняя линия трапеции (отрезок, соединяющий середины боковых '
            'сторон) параллельна основаниям.',
            'В равнобедренном треугольнике медиана, проведённая к основанию, '
            'является высотой и биссектрисой.',
            'Прямая, перпендикулярная одной из двух параллельных прямых, '
            'перпендикулярна и другой.',
            'Трапеция называется прямоугольной, если один из её углов прямой.',
        ],
        'params': {'сторона_с_серединой': ключ, 'формулировка': формулировка,
                   'AD': низ, 'BC': верх, 'h': h},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 8. Равнобедренная трапеция: точка, равноудалённая от концов основания,
# ────────────────────────────────────────────────────────────────────────
#
# — середина другого основания.
#
# Конфигурация. Равнобедренная трапеция ABCD с основаниями AD и BC. На одном
# из оснований (в банке — на большем, AD) отмечена точка M, равноудалённая от
# концов другого основания: MB = MC. Доказать, что M — середина своего
# основания. Чисел нет; варьируется только посадка (M на AD, равноудалена от
# B и C, либо зеркально — M на BC, равноудалена от A и D) и словесная форма
# требования («M — середина AD» или «AM = MD»).
#
# Ключевой ход. Из MB = MC треугольник BMC равнобедренный, ∠MBC = ∠MCB. У
# равнобедренной трапеции углы при основании BC равны: ∠ABC = ∠DCB. Вычитаем
# из равных углов равные и получаем ∠ABM = ∠DCM — ровно тот угол, которого
# не хватало для первого признака: AB = DC (боковые стороны), BM = CM
# (условие), а угол между ними теперь равен. △ABM = △DCM, откуда AM = DM,
# и раз M лежит на отрезке AD — она его середина.
#
# Почему это работает. Точка, равноудалённая от B и C, лежит на серединном
# перпендикуляре к BC, а у равнобедренной трапеции он же — серединный
# перпендикуляр к AD (ось симметрии). Но «ось симметрии равнобедренной
# трапеции» в школьном курсе не теорема, ссылаться на неё эксперт не даст,
# поэтому доказательство ведётся через равные треугольники: там каждый шаг
# опирается на признак из учебника.
#
# Ловушки.
#   * Соблазн взять △ABM и △DCM сразу: AB = DC, BM = CM и ∠A = ∠D (углы при
#     основании AD). Это две стороны и угол НЕ между ними — такого признака
#     равенства нет. Нужен именно угол при вершинах B и C, его и добываем
#     вычитанием.
#   * Обратное утверждение («середина AD равноудалена от B и C») верно и
#     доказывается короче — первый признак применяется без подготовки. Но
#     требуется прямое; ученики часто доказывают не то.
#   * Равенство ∠ABM = ∠ABC − ∠MBC законно потому, что M лежит на стороне AD,
#     а не на её продолжении: луч BM проходит внутри угла ABC. Эту фразу в
#     доказательстве надо произнести, иначе шаг висит в воздухе.
#   * Альтернатива через высоты BH и CK (△ABH = △DCK по гипотенузе и острому
#     углу, затем △BHM = △CKM по гипотенузе и катету, AM = AH + HM =
#     = DK + KM = DM) тоже проходит, но требует следить за порядком точек
#     A, H, M на основании. В основном тексте она не используется.


@сюжет(8)
def _сюжет_8(rng):
    # Где стоит точка M: на большем основании AD, как в банке, или зеркально
    # на меньшем BC. Математика одна и та же, различаются только буквы,
    # поэтому всё ниже записано через четвёрку P, Q (концы основания с
    # точкой M) и R, S (концы другого основания); PR и QS — боковые стороны.
    на_AD = rng.random() < 0.65
    if на_AD:
        P, Q, R, S = 'A', 'D', 'B', 'C'
    else:
        P, Q, R, S = 'B', 'C', 'A', 'D'

    б = {
        'P': P, 'Q': Q, 'R': R, 'S': S,
        'PQ': P + Q, 'RS': R + S,          # основания
        'PR': P + R, 'QS': Q + S,          # боковые стороны в порядке треугольников
        'PRS': P + R + S, 'QSR': Q + S + R,      # углы трапеции при основании RS
        'RMS': R + 'M' + S,                     # равнобедренный треугольник
        'MRS': 'M' + R + S, 'MSR': 'M' + S + R,  # его углы при основании
        'PRM': P + R + 'M', 'QSM': Q + S + 'M',  # искомые равные углы = треугольники
    }

    # Две формы одного условия: через «равноудалена» и через равенство
    # отрезков. Заключение подстраивается: «середина» или «PM = MQ».
    форма = rng.choice([1, 2])
    if форма == 1:
        условие = (
            '<p>На основании \\(%(PQ)s\\) равнобедренной трапеции \\(ABCD\\) '
            'отмечена точка \\(M\\), равноудалённая от вершин \\(%(R)s\\) и '
            '\\(%(S)s\\). Докажите, что \\(M\\) — середина основания '
            '\\(%(PQ)s\\).</p>' % б)
    else:
        условие = (
            '<p>В равнобедренной трапеции \\(ABCD\\) с основаниями \\(AD\\) и '
            '\\(BC\\) на основании \\(%(PQ)s\\) взята точка \\(M\\) так, что '
            '\\(M%(R)s = M%(S)s\\). Докажите, что \\(%(P)sM = M%(Q)s\\).</p>' % б)

    доказательство = (
        '<p>1. Трапеция \\(ABCD\\) равнобедренная, поэтому её боковые стороны '
        'равны: \\(AB = CD\\), и равны углы при основании \\(%(RS)s\\): '
        '\\(\\angle %(PRS)s = \\angle %(QSR)s\\) (свойство равнобедренной '
        'трапеции).</p>'
        '<p>2. По условию \\(M%(R)s = M%(S)s\\), значит, треугольник '
        '\\(%(RMS)s\\) равнобедренный с основанием \\(%(RS)s\\). В равнобедренном '
        'треугольнике углы при основании равны: '
        '\\(\\angle %(MRS)s = \\angle %(MSR)s\\).</p>'
        '<p>3. Точка \\(M\\) лежит на стороне \\(%(PQ)s\\) трапеции, поэтому луч '
        '\\(%(R)sM\\) проходит между сторонами угла \\(%(PRS)s\\), а луч '
        '\\(%(S)sM\\) — между сторонами угла \\(%(QSR)s\\). Значит,</p>'
        '\\[\\angle %(PRM)s = \\angle %(PRS)s - \\angle %(MRS)s, \\qquad '
        '\\angle %(QSM)s = \\angle %(QSR)s - \\angle %(MSR)s.\\]'
        '<p>Уменьшаемые равны по пункту 1, вычитаемые — по пункту 2, поэтому '
        'равны и разности: \\(\\angle %(PRM)s = \\angle %(QSM)s\\).</p>'
        '<p>4. Сравним треугольники \\(%(PRM)s\\) и \\(%(QSM)s\\): '
        '\\(%(PR)s = %(QS)s\\) (пункт 1), \\(%(R)sM = %(S)sM\\) (условие), '
        '\\(\\angle %(PRM)s = \\angle %(QSM)s\\) (пункт 3), причём это углы, '
        'заключённые между указанными сторонами. По первому признаку равенства '
        'треугольников (по двум сторонам и углу между ними) '
        '\\(\\triangle %(PRM)s = \\triangle %(QSM)s\\).</p>'
        '<p>5. В равных треугольниках против равных углов лежат равные стороны. '
        'Против угла \\(%(PRM)s\\) лежит сторона \\(%(P)sM\\), против равного ему '
        'угла \\(%(QSM)s\\) — сторона \\(%(Q)sM\\), поэтому '
        '\\(%(P)sM = %(Q)sM\\).</p>'
        '<p>6. Итак, точка \\(M\\) лежит на отрезке \\(%(PQ)s\\) и делит его на два '
        'равных отрезка: \\(%(P)sM = M%(Q)s\\), то есть \\(M\\) — середина '
        'основания \\(%(PQ)s\\). Что и требовалось доказать.</p>' % б)

    # Чертёж. Равнобедренная трапеция симметрична относительно вертикали
    # через середины оснований, зеркалить её бессмысленно; варьируем ширину
    # верхнего основания и высоту. Размеры берём парами, а не независимо:
    # у этой конфигурации много «случайных» совпадений, которые чертёж не
    # должен подсказывать. При M на AD: если BC = AD/2, то AB = BM (ABMC —
    # ромб); если BM ≈ BC, треугольник BMC выглядит равносторонним; если
    # BM ≈ AM, треугольник ABM выглядит равнобедренным, а при ∠ABM ≈ ∠MBC
    # луч BM смотрится биссектрисой. Все четыре пары ниже проверены числом:
    # BM отличается от BC, AM и AB не менее чем на 10 %, ∠ABM от ∠MBC и от
    # ∠BAD — не менее чем на 8°; угол при AD 57–59°.
    ш_низ = 10.0
    if на_AD:
        ш_верх, выс = rng.choice([(2.75, 5.8), (3.0, 5.6), (3.25, 5.5), (3.5, 5.4)])
        # Дужки при B: одинарная (∠MBC) и двойная (∠ABM) — смежные, на одном
        # радиусе они слились бы в одну дугу через весь угол B.
        радиус_двойной = 1.0
    else:
        # Когда M на верхнем основании, искомый угол BAM = ∠A − ∠MAD узкий.
        # Более широкое BC раскрывает его до 25–28°, а двойную дужку в нём
        # рисуем дальше от вершины, иначе она не читается. Высота не выше 4:
        # при h ≈ 5 угол AMD близок к прямому (при h = 5 он прямой в точности),
        # чертёж подсказывал бы AM ⊥ DM. Здесь ∠AMD = 103–108°, а ∠BAM
        # отличается от ∠MAD не менее чем на 10°, чтобы AM не выглядела
        # биссектрисой.
        ш_верх, выс = rng.choice([(6.0, 3.6), (6.0, 3.8), (6.5, 4.0)])
        радиус_двойной = 1.15
    сдвиг = (ш_низ - ш_верх) / 2.0
    A, D = (0.0, 0.0), (ш_низ, 0.0)
    B, C = (сдвиг, выс), (сдвиг + ш_верх, выс)
    точки = {'A': A, 'B': B, 'C': C, 'D': D}
    Pт, Qт, Rт, Sт = (точки[x] for x in (P, Q, R, S))
    M = середина(Pт, Qт)

    ч = Чертёж()
    ч.многоугольник([A, B, C, D])
    # Отрезки из условия, не являющиеся сторонами, — пунктиром, как
    # диагональ в сюжете 1.
    ч.отрезок(M, Rт, пунктир=True)
    ч.отрезок(M, Sт, пунктир=True)
    # Дано: боковые стороны (две засечки), MR = MS (одна засечка), углы при
    # основании равнобедренного треугольника RMS (одна дужка). Получено в
    # доказательстве: равные углы PRM и QSM (две дужки), PM = MQ (три засечки).
    ч.равенство(Pт, Rт, 2)
    ч.равенство(Qт, Sт, 2)
    ч.равенство(M, Rт, 1)
    ч.равенство(M, Sт, 1)
    ч.равенство(Pт, M, 3)
    ч.равенство(M, Qт, 3)
    ч.дуга_угла(Rт, M, Sт)
    ч.дуга_угла(Sт, M, Rт)
    ч.дуга_угла(Rт, Pт, M, радиус=радиус_двойной, штрихов=2)
    ч.дуга_угла(Sт, Qт, M, радиус=радиус_двойной, штрихов=2)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'), (D, 'D', 'юв'))
    ч.вершина(M, 'M', 'ю' if на_AD else 'с')

    return {
        'title': 'Равнобедренная трапеция: точка, равноудалённая от концов '
                 'основания, — середина другого основания',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'В равнобедренной трапеции боковые стороны равны и углы при каждом '
            'основании равны.',
            'В равнобедренном треугольнике углы при основании равны.',
            'Первый признак равенства треугольников: по двум сторонам и углу '
            'между ними.',
            'В равных треугольниках против равных углов лежат равные стороны.',
        ],
        'params': {
            'точка_на': P + Q,
            'равноудалена_от': R + S,
            'форма_условия': форма,
            'ш_верх': ш_верх, 'выс': выс,
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 9. Трапеция: равные отрезки диагоналей при одном основании — трапеция равнобедренная.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация. Трапеция ABCD с основаниями AD и BC, диагонали AC и BD
# пересекаются в точке O. Дано, что точка O равноудалена от концов одного из
# оснований: AO = OD (равенство при большем основании) либо BO = OC (при
# меньшем). Требуется доказать, что AB = CD, то есть что трапеция
# равнобедренная. Чисел в условии нет; от сида к сиду меняются только
# основание, при котором дано равенство, формулировка вывода («AB = CD» или
# «трапеция равнобедренная») и пропорции чертежа.
#
# Ключевой ход. Равенство AO = OD — это равнобедренный треугольник AOD, и
# углы при его основании равны: ∠OAD = ∠ODA. Параллельность оснований
# переносит эти углы во второй треугольник накрест лежащими: ∠OCB = ∠OAD
# (секущая AC) и ∠OBC = ∠ODA (секущая BD). Значит, у треугольника BOC тоже
# равны два угла, и он равнобедренный: BO = OC. Теперь у треугольников AOB и
# DOC есть по две равные стороны (AO = OD и BO = OC) и равные углы между ними
# (∠AOB и ∠DOC вертикальные) — первый признак равенства даёт AB = CD.
#
# Почему это работает. Связка «равнобедренный треугольник ⇔ равные углы при
# основании» применяется дважды и в разные стороны: в треугольнике AOD от
# сторон к углам, в треугольнике BOC от углов к сторонам. Мостик между
# треугольниками — накрест лежащие углы, и это единственное место, где
# используется, что ABCD трапеция. При данном BO = OC рассуждение то же,
# треугольники AOD и BOC лишь меняются ролями.
#
# Ловушки.
# 1. AO и OD — половины РАЗНЫХ диагоналей. «Диагонали точкой пересечения
#    делятся пополам» — свойство параллелограмма; у трапеции O делит каждую
#    диагональ в отношении AD : BC, и из условия ничего подобного не следует.
# 2. Нельзя сразу писать △AOB = △DOC «по двум сторонам и углу между ними»:
#    вторая пара сторон BO = OC не дана, её надо вывести (пункты 1–3).
# 3. Ссылка на теорему «трапеция с равными диагоналями равнобедренная» не
#    спасает: AC = BD ещё надо получить (это то же BO = OC), а сама теорема
#    в школьном курсе доказывается тем же рассуждением, и эксперт потребует
#    его выписать.
# 4. В первом признаке угол должен лежать между сравниваемыми сторонами:
#    ∠AOB — между AO и OB, ∠DOC — между DO и OC. Соответствие вершин
#    A ↔ D, O ↔ O, B ↔ C, поэтому AB ↔ DC.
# 5. Чертёж обязан быть по-настоящему симметричным — утверждение верно, — но
#    симметрия в доказательстве не используется: «видно, что есть ось
#    симметрии» экспертом не засчитывается.
#
# Равносильный финал: △ABD = △DCA по двум сторонам и углу между ними (AD
# общая, BD = BO + OD = OC + OA = AC, ∠BDA = ∠CAD). Короче не получается:
# равенство BO = OC нужно и там.


@сюжет(9)
def _сюжет_9(rng):
    # Условие может дать равенство при любом из оснований: AO = OD (у
    # большего) или BO = OC (у меньшего). Рассуждение симметрично, поэтому
    # текст собирается из одного шаблона. P и Q — концы основания того
    # треугольника, равнобедренность которого дана; R и S — вершины другого
    # основания, причём P, O, R лежат на одной диагонали, а Q, O, S — на
    # другой. Тогда накрест лежащие углы связывают ∠OPQ с ∠ORS и ∠OQP с
    # ∠OSR, а второй равнобедренный треугольник — это SOR.
    у_большего = rng.random() < 0.6
    if у_большего:
        P, Q, R, S = 'A', 'D', 'C', 'B'
    else:
        P, Q, R, S = 'B', 'C', 'D', 'A'

    # Отрезки от вершин до O называем в привычном порядке: AO, OD, BO, OC,
    # а диагонали — всегда AC и BD, а не CA и DB.
    отрезок_до_O = {'A': 'AO', 'D': 'OD', 'B': 'BO', 'C': 'OC'}

    def диагональ(X, Y):
        return 'AC' if {X, Y} == {'A', 'C'} else 'BD'

    б = {
        'P': P, 'Q': Q, 'R': R, 'S': S,
        'дано': '%s = %s' % (отрезок_до_O[P], отрезок_до_O[Q]),
        'вывод': '%s = %s' % (отрезок_до_O[S], отрезок_до_O[R]),
        'д1': диагональ(P, R),          # диагональ, на которой лежат P, O, R
        'д2': диагональ(Q, S),          # диагональ, на которой лежат Q, O, S
    }
    # В пункте 4 оба равенства нужны сразу; одно из них дано, другое
    # получено в пункте 3 — какое именно, зависит от варианта.
    if у_большего:
        б['ист_AO'], б['ист_BO'] = 'по условию', 'по пункту 3'
    else:
        б['ист_AO'], б['ист_BO'] = 'по пункту 3', 'по условию'

    # ── условие ────────────────────────────────────────────────────────────
    вывод_равнобедренная = rng.random() < 0.5
    что_доказать = ('трапеция \\(ABCD\\) равнобедренная'
                    if вывод_равнобедренная else '\\(AB = CD\\)')
    начало = rng.choice([
        '<p>Диагонали трапеции \\(ABCD\\) с основаниями \\(AD\\) и \\(BC\\) '
        'пересекаются в точке \\(O\\), причём \\(%(дано)s\\). ',
        '<p>В трапеции \\(ABCD\\) с основаниями \\(BC\\) и \\(AD\\) диагонали '
        '\\(AC\\) и \\(BD\\) пересекаются в точке \\(O\\), и оказалось, что '
        '\\(%(дано)s\\). ',
    ])
    условие = (начало + 'Докажите, что %(что)s.</p>') % dict(б, что=что_доказать)

    # ── доказательство ────────────────────────────────────────────────────
    доказательство = (
        '<p>1. По условию \\(%(дано)s\\), поэтому треугольник \\(%(P)sO%(Q)s\\) '
        'равнобедренный с основанием \\(%(P)s%(Q)s\\). В равнобедренном '
        'треугольнике углы при основании равны: '
        '\\(\\angle O%(P)s%(Q)s = \\angle O%(Q)s%(P)s\\).</p>'
        '<p>2. \\(BC \\parallel AD\\) как основания трапеции. Прямая \\(%(д1)s\\) — '
        'секущая при этих параллельных прямых, поэтому '
        '\\(\\angle O%(R)s%(S)s = \\angle O%(P)s%(Q)s\\) как накрест лежащие углы '
        '(\\(\\angle O%(R)s%(S)s\\) — это угол \\(%(P)s%(R)s%(S)s\\), а '
        '\\(\\angle O%(P)s%(Q)s\\) — угол \\(%(R)s%(P)s%(Q)s\\), так как точка '
        '\\(O\\) лежит на диагонали \\(%(д1)s\\)). Прямая \\(%(д2)s\\) — тоже '
        'секущая, и точно так же \\(\\angle O%(S)s%(R)s = \\angle O%(Q)s%(P)s\\).</p>'
        '<p>3. Из пунктов 1 и 2 следует, что '
        '\\(\\angle O%(S)s%(R)s = \\angle O%(R)s%(S)s\\). В треугольнике '
        '\\(%(S)sO%(R)s\\) два угла равны, значит, по признаку равнобедренного '
        'треугольника он равнобедренный с основанием \\(%(S)s%(R)s\\): '
        '\\(%(вывод)s\\).</p>'
        '<p>4. Рассмотрим треугольники \\(AOB\\) и \\(DOC\\). В них \\(AO = OD\\) '
        '%(ист_AO)s, \\(BO = OC\\) %(ист_BO)s, а углы между этими сторонами '
        'равны: \\(\\angle AOB = \\angle DOC\\) как вертикальные. По первому '
        'признаку равенства треугольников (по двум сторонам и углу между ними) '
        '\\(\\triangle AOB = \\triangle DOC\\).</p>'
        '<p>5. В равных треугольниках против равных углов лежат равные стороны: '
        'сторона \\(AB\\) лежит против угла \\(AOB\\), сторона \\(CD\\) — против '
        'равного ему угла \\(DOC\\), поэтому \\(AB = CD\\). Это боковые стороны '
        'трапеции \\(ABCD\\), а трапеция с равными боковыми сторонами по '
        'определению равнобедренная, что и требовалось доказать.</p>'
    ) % б

    # ── чертёж ────────────────────────────────────────────────────────────
    # Основание AD внизу, BC сверху, трапеция симметрична — иначе AO = OD
    # на рисунке будет ложью. Пропорции слегка гуляют от сида к сиду, но
    # боковые стороны всегда заметно наклонены (угол при основании от 48,6°
    # при BC = 4, h = 3,4 до 64,5° при BC = 6, h = 4,2): почти прямоугольная
    # трапеция читалась бы как прямоугольник.
    AD = 10.0
    BC = rng.choice([4.0, 4.5, 5.0, 5.5, 6.0])
    h = rng.choice([3.4, 3.8, 4.2])
    A, D = (0.0, 0.0), (AD, 0.0)
    B, C = ((AD - BC) / 2, h), ((AD + BC) / 2, h)
    O = пересечение(A, C, B, D)
    точка = {'A': A, 'B': B, 'C': C, 'D': D}
    угол_при_основании = degrees(atan2(h, (AD - BC) / 2))

    ч = Чертёж(height=230)
    ч.многоугольник([A, B, C, D])
    ч.отрезок(A, C, ширина=1.2)
    ч.отрезок(B, D, ширина=1.2)
    # Данное равенство отрезков — одним штрихом, выведенное — двумя.
    ч.равенство(точка[P], O, штрихов=1)
    ч.равенство(O, точка[Q], штрихов=1)
    ч.равенство(точка[S], O, штрихов=2)
    ч.равенство(O, точка[R], штрихов=2)
    # Четыре угла при основаниях равны между собой (пункты 1–3) — одна
    # дужка; вертикальные углы при O, на которых держится первый признак,
    # помечены двойной дужкой.
    ч.дуга_угла(A, O, D)
    ч.дуга_угла(D, O, A)
    ч.дуга_угла(B, O, C)
    ч.дуга_угла(C, O, B)
    ч.дуга_угла(O, A, B, радиус=0.45, штрихов=2)
    ч.дуга_угла(O, D, C, радиус=0.45, штрихов=2)
    # Подпись O — снизу: слева и справа от O стоят дужки вертикальных углов,
    # а ниже, между OA и OD, свободно.
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'), (O, 'O', 'ю'))

    return {
        'title': 'Трапеция: равные отрезки диагоналей при одном основании — '
                 'трапеция равнобедренная',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'В равнобедренном треугольнике углы при основании равны; и обратно: '
            'если два угла треугольника равны, то он равнобедренный.',
            'Накрест лежащие углы при параллельных прямых и секущей равны.',
            'Вертикальные углы равны.',
            'Первый признак равенства треугольников: по двум сторонам и углу '
            'между ними; в равных треугольниках против равных углов лежат '
            'равные стороны.',
        ],
        'params': {
            'дано_при_основании': P + Q,
            'дано': б['дано'],
            'выведено': б['вывод'],
            'вывод_в_условии': 'равнобедренная' if вывод_равнобедренная else 'AB = CD',
            'BC': BC, 'AD': AD, 'h': h,
            'угол_при_основании': round(угол_при_основании, 1),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 10. Параллелограмм: прямая через точку пересечения диагоналей отсекает равные отрезки.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация
# ------------
# Параллелограмм ABCD, диагонали пересекаются в точке O. Через O проведена
# прямая; она встречает пару противоположных сторон — либо BC и AD, либо AB
# и CD. Доказать, что отрезки, отсечённые ею на этих сторонах при концах
# одной диагонали, равны: BK = DM, CL = AN, AE = CF или BP = DQ — четыре
# формулировки банка, здесь они выбираются по rng. Чисел в сюжете нет вовсе:
# банк варьирует только буквы и пару сторон, и добавлять длины было бы
# лишними данными.
#
# Ключевой ход
# ------------
# Единственный количественный факт задачи — O делит обе диагонали пополам.
# Берём ту диагональ, концы которой служат вершинами доказываемых отрезков
# (для BK = DM это BD, для AE = CF — AC); обозначим её концы X и Y, точки
# секущей на сторонах — P и Q. Тогда XO = OY, углы XOP и YOQ вертикальные,
# а углы PXO и QYO — накрест лежащие при параллельных сторонах и секущей XY.
# Треугольники XOP и YOQ равны по стороне и двум прилежащим углам, откуда
# XP = YQ как соответственные стороны.
#
# Почему это работает
# -------------------
# O — центр симметрии параллелограмма: симметрия относительно O переводит
# каждую сторону в противоположную, а любую прямую через O — в себя. Значит
# P переходит в Q, X — в Y, и отрезок XP — в равный ему YQ. Школьное
# доказательство через равные треугольники — та же симметрия, записанная
# признаками равенства; ссылка на симметрию без треугольников баллов не даёт.
#
# Ловушки
# -------
# * Не та диагональ. Для BK = DM нужна BD, а не AC: у треугольников должны
#   быть вершины B и D, иначе равных отрезков XO = OY не получить.
# * «Соответственные» вместо «накрест лежащих». Углы KBO и MDO лежат по
#   разные стороны от секущей BD — это накрест лежащие углы; соответственными
#   они были бы при сонаправленных лучах BC и DA, а эти лучи противоположны.
# * Секущая по диагонали. Если прямая совпадает с рабочей диагональю,
#   точки P и Q сливаются с X и Y: утверждение верно тривиально, но углов
#   XOP и YOQ нет. Условие банка этого случая не исключает (прямая BD
#   «пересекает сторону BC» в точке B), поэтому доказательство одной фразой
#   закрывает его в начале шага 3 и дальше считает P ≠ X, Q ≠ Y. Чертёж
#   держит угол между секущей и диагональю не меньше 22°, иначе дуги
#   вертикальных углов при O не разглядеть.
# * Продолжения сторон. Любая прямая через O пересекает границу ровно в двух
#   точках, симметричных относительно O, то есть лежащих на противоположных
#   сторонах, а не на их продолжениях. На чертеже P берётся внутри стороны,
#   а Q — как пересечение секущей с противоположной стороной, так что
#   картинка не может разойтись с условием.


# Четыре формулировки банка. X и Y — концы рабочей диагонали, X1 и Y1 —
# вторые концы сторон, по которым идёт секущая (X1 и Y1 — концы другой
# диагонали). P лежит на стороне XX1, Q — на стороне YY1; доказываем XP = YQ.
ВАРИАНТЫ_10 = (
    dict(X='B', X1='C', Y='D', Y1='A', P='K', Q='M'),   # секущая по BC и AD: BK = DM
    dict(X='C', X1='B', Y='A', Y1='D', P='L', Q='N'),   # секущая по BC и AD: CL = AN
    dict(X='A', X1='B', Y='C', Y1='D', P='E', Q='F'),   # секущая по AB и CD: AE = CF
    dict(X='B', X1='A', Y='D', Y1='C', P='P', Q='Q'),   # секущая по AB и CD: BP = DQ
)

# С какой стороны подписывать точку секущей на каждой стороне: снаружи
# параллелограмма, где нет ни диагоналей, ни дуг.
ПОДПИСЬ_НА_СТОРОНЕ = {'BC': 'с', 'AD': 'ю', 'AB': 'з', 'CD': 'в'}

# Куда попадает центр буквы при каждой стороне подписи (экранные px, y вниз).
# Смещения geom_svg.СТОРОНЫ задают базовую линию текста, центр буквы при
# кегле 13 лежит примерно на 4,5 px выше неё.
ЦЕНТР_БУКВЫ = {
    'с': (0, -14.5), 'ю': (0, 11.5), 'з': (-12, -0.5), 'в': (12, -0.5),
    'сз': (-11, -12.5), 'св': (11, -12.5), 'юз': (-11, 9.5), 'юв': (11, 9.5),
}


def _имя_10(u, v):
    """Сторона или диагональ по двум вершинам в привычной записи: DA → AD, CB → BC."""
    return u + v if u + v in ('AB', 'BC', 'CD', 'AD', 'AC', 'BD') else v + u


def _угол_10(O, U, V):
    """Угол UOV в градусах — чтобы проверять посадку чертежа числом."""
    ux, uy = U[0] - O[0], U[1] - O[1]
    vx, vy = V[0] - O[0], V[1] - O[1]
    c = (ux * vx + uy * vy) / (math.hypot(ux, uy) * math.hypot(vx, vy))
    return math.degrees(math.acos(max(-1.0, min(1.0, c))))


def _подписать_O(ч, O, т, k):
    """Букву O ставим в самый широкий свободный сектор между лучами из O.

    Через O проходят шесть лучей: обе диагонали и секущая. В секторах XOP и
    YOQ стоят дужки вертикальных углов, остальные четыре свободны: POX1,
    X1OY и вертикальные им QOY1, Y1OX. «Просто справа снизу» буква ляжет
    либо на линию, либо на дужку, поэтому выбираем самый широкий сектор и
    ставим букву на его биссектрису; чем сектор уже, тем дальше от точки,
    чтобы до обеих линий оставалось не меньше 9,5 px (при 6,5 px белая обводка
    буквы в секторе 60–65° резала пунктир обеих диагоналей и упиралась в
    концы дужек — видно на увеличенном рендере). Подпись умеет вставать
    только на восемь сторон света, поэтому берём ближайшую, а остаток сдвига
    компенсируем якорем. Масштаб k известен заранее: всё, что учитывается
    при подборе масштаба, лежит внутри параллелограмма.
    """
    def орт(T):
        dx, dy = T[0] - O[0], T[1] - O[1]
        d = math.hypot(dx, dy)
        return dx / d, dy / d

    секторы = [(т['P'], т['X1']), (т['X1'], т['Y']), (т['Q'], т['Y1']), (т['Y1'], т['X'])]
    лучший = None
    for U, V in секторы:
        раствор = _угол_10(O, U, V)
        (ux, uy), (vx, vy) = орт(U), орт(V)
        bx, by = ux + vx, uy + vy
        d = math.hypot(bx, by)
        bx, by = bx / d, by / d
        # При равных растворах (вертикальные секторы) предпочитаем правый:
        # подпись O справа от точки привычнее.
        ключ = (round(раствор, 6), bx)
        if лучший is None or ключ > лучший[0]:
            лучший = (ключ, раствор, (bx, by))
    _, раствор, (bx, by) = лучший
    # Самый широкий свободный сектор всегда не уже ~62° (см. геометрию выше),
    # так что буква встаёт не дальше 19 px от точки — на радиусе дужек, но в
    # секторе без дужек.
    отступ = max(16.0, min(26.0, 9.5 / math.sin(math.radians(раствор / 2))))
    цель = (отступ * bx, -отступ * by)                 # экранные px, y вниз
    сторона, (cx, cy) = min(
        ЦЕНТР_БУКВЫ.items(),
        key=lambda пара: math.hypot(цель[0] - пара[1][0], цель[1] - пара[1][1]))
    якорь = (O[0] + (цель[0] - cx) / k, O[1] - (цель[1] - cy) / k)
    ч.точка(O)
    ч.подпись(якорь, 'O', сторона)


@сюжет(10)
def _сюжет_10(rng):
    в = rng.choice(ВАРИАНТЫ_10)
    X, X1, Y, Y1 = в['X'], в['X1'], в['Y'], в['Y1']
    имя_P, имя_Q = в['P'], в['Q']
    сторона_P, сторона_Q = _имя_10(X, X1), _имя_10(Y, Y1)
    диаг, диаг2 = _имя_10(X, Y), _имя_10(X1, Y1)

    # Параллелограмм с AD внизу, BC сверху, наклон вправо. Угол при A от 60°
    # до 72°: заметно косой, но не сплющенный. Основание фиксировано —
    # варьируется только форма, масштаб чертёж подберёт сам.
    a = 6.0
    s = rng.uniform(1.2, 1.9)
    h = rng.uniform(3.3, 3.8)
    A, B, C, D = (0.0, 0.0), (s, h), (s + a, h), (a, 0.0)
    вершины = {'A': A, 'B': B, 'C': C, 'D': D}
    O = середина(A, C)
    тX, тX1, тY, тY1 = вершины[X], вершины[X1], вершины[Y], вершины[Y1]

    # P — внутри стороны XX1, дальше от X, чем середина: чем ближе P к X, тем
    # ближе секущая к рабочей диагонали и тем уже вертикальные углы при O.
    # Q берём не симметрией, а честным пересечением секущей со стороной YY1.
    for _ in range(100):
        t = rng.uniform(0.55, 0.74)
        тP = (тX[0] + t * (тX1[0] - тX[0]), тX[1] + t * (тX1[1] - тX[1]))
        тQ = пересечение(тP, O, тY, тY1)
        угол_O = _угол_10(O, тX, тP)
        if угол_O >= 22:
            break

    буквы = dict(X=X, X1=X1, Y=Y, Y1=Y1, P=имя_P, Q=имя_Q,
                 сторонаP=сторона_P, сторонаQ=сторона_Q, диаг=диаг, диаг2=диаг2)

    # Банк формулирует так: «Через точку O пересечения диагоналей
    # параллелограмма ABCD проведена прямая, пересекающая стороны BC и AD в
    # точках K и M соответственно. Докажите, что BK = DM». Обе формулировки
    # ниже нарочно построены иначе — переформулировка обязательна.
    условия = (
        '<p>Диагонали параллелограмма \\(ABCD\\) пересекаются в точке \\(O\\). '
        'Прямая, проходящая через \\(O\\), пересекает сторону \\({сторонаP}\\) '
        'в точке \\({P}\\), а сторону \\({сторонаQ}\\) — в точке \\({Q}\\). '
        'Докажите, что отрезки \\({X}{P}\\) и \\({Y}{Q}\\) равны.</p>',
        '<p>В параллелограмме \\(ABCD\\) проведены диагонали; \\(O\\) — точка их '
        'пересечения. Прямая, проведённая через \\(O\\), встречает стороны '
        '\\({сторонаP}\\) и \\({сторонаQ}\\) в точках \\({P}\\) и \\({Q}\\) '
        'соответственно. Докажите, что \\({X}{P} = {Y}{Q}\\).</p>',
    )
    условие = rng.choice(условия).format_map(буквы)

    доказательство = (
        '<p>1. Точка \\({P}\\) лежит на стороне \\({сторонаP}\\), точка \\({Q}\\) — '
        'на противоположной стороне \\({сторонаQ}\\). Противоположные стороны '
        'параллелограмма параллельны, поэтому \\({сторонаP} \\parallel {сторонаQ}\\).</p>'

        '<p>2. Диагонали параллелограмма точкой пересечения делятся пополам. '
        'Точка \\(O\\) — середина диагонали \\({диаг}\\), значит, \\({X}O = O{Y}\\).</p>'

        '<p>3. Если секущая совпадает с диагональю \\({диаг}\\), то она встречает '
        'стороны \\({сторонаP}\\) и \\({сторонаQ}\\) в самих вершинах: \\({P} = {X}\\), '
        '\\({Q} = {Y}\\), оба отрезка стягиваются в точку и доказывать нечего. Далее '
        'считаем, что секущая отлична от диагонали \\({диаг}\\); тогда \\({P} \\ne {X}\\) '
        'и \\({Q} \\ne {Y}\\). '
        'Точки \\({X}\\), \\(O\\), \\({Y}\\) лежат на одной прямой — диагонали '
        '\\({диаг}\\), причём \\(O\\) находится между \\({X}\\) и \\({Y}\\). Точки '
        '\\({P}\\), \\(O\\), \\({Q}\\) тоже лежат на одной прямой — проведённой через '
        '\\(O\\) секущей, и \\(O\\) находится между \\({P}\\) и \\({Q}\\): точка '
        'пересечения диагоналей лежит внутри параллелограмма, а \\({P}\\) и \\({Q}\\) — '
        'на его границе. Поэтому лучи '
        '\\(O{X}\\) и \\(O{Y}\\) противоположны, лучи \\(O{P}\\) и \\(O{Q}\\) '
        'противоположны, а углы \\({X}O{P}\\) и \\({Y}O{Q}\\) — вертикальные. '
        'Вертикальные углы равны: \\(\\angle {X}O{P} = \\angle {Y}O{Q}\\).</p>'

        '<p>4. Рассмотрим параллельные прямые \\({сторонаP}\\) и \\({сторонаQ}\\) '
        'и секущую \\({диаг}\\). Диагональ \\({диаг}\\) разбивает параллелограмм на '
        'треугольники \\({X}{X1}{Y}\\) и \\({X}{Y1}{Y}\\), поэтому вершины \\({X1}\\) '
        'и \\({Y1}\\) лежат по разные стороны от неё, и углы \\({X1}{X}{Y}\\) и '
        '\\({Y1}{Y}{X}\\) — внутренние накрест лежащие. Накрест лежащие углы при '
        'параллельных прямых и секущей равны: \\(\\angle {X1}{X}{Y} = '
        '\\angle {Y1}{Y}{X}\\). Точка \\({P}\\) лежит на луче \\({X}{X1}\\), а точка '
        '\\(O\\) — на луче \\({X}{Y}\\), поэтому \\(\\angle {P}{X}O\\) — это тот же '
        'угол \\({X1}{X}{Y}\\); точно так же \\(\\angle {Q}{Y}O\\) — тот же угол '
        '\\({Y1}{Y}{X}\\). Следовательно, \\(\\angle {P}{X}O = \\angle {Q}{Y}O\\).</p>'

        '<p>5. В треугольниках \\({X}O{P}\\) и \\({Y}O{Q}\\): \\({X}O = O{Y}\\) '
        '(шаг 2), \\(\\angle {X}O{P} = \\angle {Y}O{Q}\\) (шаг 3), '
        '\\(\\angle O{X}{P} = \\angle O{Y}{Q}\\) (шаг 4). Сторона и два прилежащих '
        'к ней угла одного треугольника равны стороне и двум прилежащим к ней '
        'углам другого, поэтому по второму признаку равенства треугольников '
        '\\(\\triangle {X}O{P} = \\triangle {Y}O{Q}\\).</p>'

        '<p>6. В равных треугольниках против равных углов лежат равные стороны. '
        'Сторона \\({X}{P}\\) лежит против угла \\({X}O{P}\\), сторона \\({Y}{Q}\\) — '
        'против равного ему угла \\({Y}O{Q}\\). Значит, \\({X}{P} = {Y}{Q}\\), '
        'что и требовалось доказать.</p>'

        '<p><i>Замечание.</i> Те же рассуждения с диагональю \\({диаг2}\\) и '
        'треугольниками \\({X1}O{P}\\) и \\({Y1}O{Q}\\) дают \\({X1}{P} = {Y1}{Q}\\). '
        'Причина одна: точка \\(O\\) — центр симметрии параллелограмма, и любая '
        'прямая через \\(O\\) отсекает на противоположных сторонах равные отрезки.</p>'
    ).format_map(буквы)

    # Чертёж. Обе диагонали пунктиром (они даны, но не они главные), секущая
    # сплошная. Пометки — ровно то, чем пользуется доказательство: половины
    # рабочей диагонали одним штрихом, вертикальные углы при O двойной
    # дужкой, накрест лежащие углы при X и Y одинарной. Доказанное равенство
    # XP = YQ — двумя штрихами, чтобы ученик сверил с ним свой рисунок.
    ч = Чертёж(width=380, height=240)
    ч.многоугольник([A, B, C, D])
    ч.отрезок(A, C, пунктир=True)
    ч.отрезок(B, D, пунктир=True)
    ч.отрезок(тP, тQ)
    ч.равенство(тX, O)
    ч.равенство(O, тY)
    ч.дуга_угла(O, тX, тP, радиус=0.38, штрихов=2)
    ч.дуга_угла(O, тY, тQ, радиус=0.38, штрихов=2)
    ч.дуга_угла(тX, тP, O, радиус=0.55)
    ч.дуга_угла(тY, тQ, O, радиус=0.55)
    ч.равенство(тX, тP, штрихов=2)
    ч.равенство(тY, тQ, штрихов=2)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'), (D, 'D', 'юв'),
                      (тP, имя_P, ПОДПИСЬ_НА_СТОРОНЕ[сторона_P]),
                      (тQ, имя_Q, ПОДПИСЬ_НА_СТОРОНЕ[сторона_Q]))
    # Масштаб чертежа: все учтённые точки лежат в прямоугольнике [0; a+s]×[0; h].
    k = min((ч.width - 2 * ч.поле) / (a + s), (ч.height - 2 * ч.поле) / h)
    _подписать_O(ч, O, dict(X=тX, X1=тX1, Y=тY, Y1=тY1, P=тP, Q=тQ), k)

    return {
        'title': 'Параллелограмм: прямая через точку пересечения диагоналей '
                 'отсекает на противоположных сторонах равные отрезки',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Противоположные стороны параллелограмма параллельны; диагонали '
            'параллелограмма точкой пересечения делятся пополам.',
            'Вертикальные углы равны.',
            'Внутренние накрест лежащие углы при двух параллельных прямых и секущей равны.',
            'Второй признак равенства треугольников: по стороне и двум прилежащим '
            'к ней углам; в равных треугольниках соответственные стороны равны.',
        ],
        'params': {
            'вариант': ВАРИАНТЫ_10.index(в) + 1,
            'доказать': '%s%s = %s%s' % (X, имя_P, Y, имя_Q),
            'секущая_по': (сторона_P, сторона_Q),
            'рабочая_диагональ': диаг,
            't': round(t, 3),
            'сдвиг': round(s, 2),
            'высота': round(h, 2),
            'угол_при_O': round(угол_O, 1),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 11. Параллелограмм: секущая через точку пересечения диагоналей,
# ────────────────────────────────────────────────────────────────────────
#
# CL = AG через дополнительное построение и теорему Фалеса.
#
# Конфигурация. Параллелограмм ABCD, диагонали AC и BD пересекаются в точке O.
# Через O проведена прямая; она встречает сторону BC в точке L, а сторону AD —
# в точке G. Доказать CL = AG. Чертёж тот же, что в сюжете 10 (BK = DM,
# AE = CF), но банк решает именно эту задачу иначе — через дополнительное
# построение, и этот ход здесь и показываем.
#
# Ключевой ход. Через C проводим прямую, параллельную LG, до пересечения с
# прямой AD в точке K. Дальше отрезок CL «переезжает» на нижнюю сторону в два
# приёма:
#   * LCKG — параллелограмм (LC ∥ GK как части BC и AD, CK ∥ LG по
#     построению), поэтому CL = GK;
#   * в треугольнике ACK точка O — середина AC (диагонали делятся пополам),
#     а OG ∥ CK, поэтому по теореме Фалеса G — середина AK: AG = GK.
# Складываем: CL = GK = AG.
#
# Почему работает. Теореме Фалеса нужны равные отрезки на первой секущей — их
# даёт свойство диагоналей параллелограмма (AO = OC), а не что-то про саму
# прямую LG. Параллелограмм LCKG нужен, чтобы перенести CL с верхней стороны
# на нижнюю: без него сравнивать CL и AG напрямую не с чем — они лежат на
# разных прямых.
#
# Ловушки.
#   * Точка K лежит на отрезке AD, только если G ближе к A, чем середина AD
#     (тогда AK = 2·AG ≤ AD). Если G ближе к D, точка K уходит на продолжение
#     AD за D. Доказательство от этого не меняется, поэтому в тексте K —
#     точка пересечения с ПРЯМОЙ AD; на чертеже выбрана посадка, при которой
#     K попадает на саму сторону, чтобы рисунок не спорил с текстом.
#   * Существование K надо оговорить: LG пересекает AD (в точке G), значит,
#     не параллельна ей; тогда и параллельная ей CK пересекает прямую AD.
#   * Типичная потеря балла: «по теореме Фалеса AG = GK» без указания, откуда
#     берутся равные отрезки на другой секущей. Шаг AO = OC обязателен.
#   * Есть короткий путь без построения: △AOG = △COL по стороне и двум
#     прилежащим углам. Он верный и упомянут в замечании после доказательства,
#     но сюжет именно про путь через Фалеса — так решает банк, и так же
#     полезно уметь.
#   * Вырожденное положение секущей — совпадение с диагональю AC — условием
#     формально не запрещено (она «пересекает сторону BC» в точке C), а
#     построение там рассыпается: параллельная к LG через C есть сама AC,
#     K = A, треугольника ACK нет. Утверждение при этом верно тривиально
#     (CL = AG = 0), поэтому в начале шага 1 этот случай отделён одной фразой,
#     и дальше считается L ≠ C — из этого же следует, что C ∉ LG, а значит,
#     L, C, K, G различны и LCKG действительно четырёхугольник. Совпадение с
#     BD не вырожденное: L = B, G = D, K лежит за D, и доказательство проходит
#     без изменений (CL = BC = DK = AD = AG).


@сюжет(11)
def _сюжет_11(rng):
    # Чисел в условии нет, поэтому rng меняет только посадку чертежа:
    # пропорции параллелограмма и наклон секущей. Долю t = AG : AD держим
    # меньше 1/2 — тогда AK = 2·AG короче AD и точка K остаётся на стороне
    # (см. ловушки в докстринге). Наклон боковой стороны ~55–67°, чтобы
    # параллелограмм не выглядел ни прямоугольником, ни «лежачим».
    ш = rng.choice([9.0, 10.0, 11.0])       # длина AD
    в = rng.choice([5.0, 5.5, 6.0])         # высота параллелограмма
    сдвиг = rng.choice([2.5, 3.0, 3.5])     # насколько B правее A
    t = rng.choice([0.25, 0.3, 0.35])       # AG : AD

    условие = (
        '<p>Диагонали параллелограмма \\(ABCD\\) пересекаются в точке \\(O\\). '
        'Прямая, проходящая через точку \\(O\\), пересекает сторону \\(BC\\) '
        'в точке \\(L\\), а сторону \\(AD\\) — в точке \\(G\\). '
        'Докажите, что \\(CL = AG\\).</p>')

    доказательство = (
        '<p>1. <b>Дополнительное построение.</b> Если прямая \\(LG\\) совпадает '
        'с диагональю \\(AC\\), то \\(L = C\\), \\(G = A\\) и равенство очевидно; '
        'далее считаем, что \\(L \\ne C\\); тогда точка \\(C\\) не лежит на '
        'прямой \\(LG\\) (иначе прямая \\(LG\\) проходила бы через точки '
        '\\(O\\) и \\(C\\), то есть совпадала бы с \\(AC\\)). '
        'Через вершину \\(C\\) проведём прямую, параллельную '
        '\\(LG\\), и обозначим через \\(K\\) точку её пересечения с прямой '
        '\\(AD\\). Такая точка существует: прямая \\(LG\\) пересекает \\(AD\\) '
        'в точке \\(G\\), то есть не параллельна \\(AD\\); значит, и '
        'проведённая через \\(C\\) прямая, параллельная \\(LG\\), не параллельна '
        '\\(AD\\) и пересекает её.</p>'
        '<p>2. Покажем, что \\(LCKG\\) — параллелограмм. Отрезок \\(LC\\) лежит '
        'на стороне \\(BC\\), отрезок \\(GK\\) — на прямой \\(AD\\), а '
        '\\(BC \\parallel AD\\) как противоположные стороны параллелограмма '
        '\\(ABCD\\). Кроме того, \\(CK \\parallel LG\\) по построению. Прямые '
        '\\(BC\\) и \\(AD\\) различны, прямые \\(LG\\) и \\(CK\\) тоже различны '
        '(точка \\(C\\) не лежит на \\(LG\\)), поэтому \\(L\\), \\(C\\), \\(K\\), '
        '\\(G\\) — четыре различные точки, и \\(LCKG\\) — четырёхугольник с '
        'попарно параллельными противоположными сторонами, то есть '
        'параллелограмм по определению. '
        'Противоположные стороны параллелограмма равны:</p>'
        '\\[CL = GK.\\]'
        '<p>3. Диагонали параллелограмма точкой пересечения делятся пополам, '
        'поэтому \\(AO = OC\\): точка \\(O\\) — середина диагонали \\(AC\\).</p>'
        '<p>4. Рассмотрим треугольник \\(ACK\\) (он не вырожден: вершина '
        '\\(C\\) не лежит на прямой \\(AD\\), а \\(K \\ne A\\) — иначе прямая '
        '\\(CK\\) совпала бы с \\(AC\\), и параллельная ей прямая \\(LG\\), '
        'имеющая с \\(AC\\) общую точку \\(O\\), тоже совпала бы с \\(AC\\), '
        'что исключено в шаге 1). Точка \\(O\\) — середина его '
        'стороны \\(AC\\) (шаг 3), а прямая \\(OG\\) — это прямая \\(LG\\): '
        'она параллельна стороне \\(CK\\) по построению и пересекает сторону '
        '\\(AK\\) в точке \\(G\\). Применим теорему Фалеса к углу \\(CAK\\): '
        'параллельные прямые \\(OG\\) и \\(CK\\) отсекают на его стороне '
        '\\(AC\\) равные отрезки \\(AO\\) и \\(OC\\), значит, они отсекают '
        'равные отрезки и на другой его стороне \\(AK\\):</p>'
        '\\[AG = GK.\\]'
        '<p>Иначе говоря, прямая, проведённая через середину стороны \\(AC\\) '
        'треугольника параллельно стороне \\(CK\\), делит третью сторону '
        '\\(AK\\) пополам.</p>'
        '<p>5. Из шагов 2 и 4 получаем \\(CL = GK\\) и \\(AG = GK\\), откуда '
        '\\(CL = AG\\), что и требовалось доказать.</p>'
        '<p><i>Замечание.</i> То же равенство получается и без дополнительного '
        'построения: треугольники \\(AOG\\) и \\(COL\\) равны по стороне и двум '
        'прилежащим углам (\\(AO = OC\\), \\(\\angle AOG = \\angle COL\\) как '
        'вертикальные, \\(\\angle OAG = \\angle OCL\\) как накрест лежащие при '
        '\\(BC \\parallel AD\\) и секущей \\(AC\\)), откуда \\(AG = CL\\).</p>')

    # Чертёж: AD внизу, BC сверху, B правее A. Секущая идёт снизу слева
    # (G у левой половины AD) вверх направо (L у правой половины BC) —
    # такая посадка и даёт K на самой стороне AD.
    A, D = (0.0, 0.0), (ш, 0.0)
    B, C = (сдвиг, в), (сдвиг + ш, в)
    O = середина(A, C)
    G = (t * ш, 0.0)
    L = пересечение(G, O, B, C)
    # K — конец прямой через C, параллельной LG: сдвигаем C на вектор GO
    # и пересекаем полученную прямую с AD.
    C_сдвиг = (C[0] + O[0] - G[0], C[1] + O[1] - G[1])
    K = пересечение(C, C_сдвиг, A, D)

    ч = Чертёж()
    ч.многоугольник([A, B, C, D])
    # Диагонали даны условием, но в доказательстве работает только AC;
    # обе рисуем тоньше основного контура, чтобы секущая LG читалась.
    ч.отрезок(A, C, ширина=1.2)
    ч.отрезок(B, D, ширина=1.2)
    ч.отрезок(L, G)
    ч.отрезок(C, K, пунктир=True, вспомогательный=True)
    # Один штрих — половины диагонали AC (данные для Фалеса), два штриха —
    # три равных отрезка, которые и связывает доказательство.
    ч.равенство(A, O)
    ч.равенство(O, C)
    ч.равенство(C, L, штрихов=2)
    ч.равенство(A, G, штрихов=2)
    ч.равенство(G, K, штрихов=2)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'), (O, 'O', 'с'), (L, 'L', 'с'),
                      (G, 'G', 'ю'), (K, 'K', 'ю'))

    return {
        'title': 'Параллелограмм: CL = AG через построение и теорему Фалеса',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Противоположные стороны параллелограмма параллельны и равны; '
            'четырёхугольник с попарно параллельными противоположными '
            'сторонами — параллелограмм.',
            'Диагонали параллелограмма точкой пересечения делятся пополам.',
            'Теорема Фалеса: если параллельные прямые, пересекающие стороны '
            'угла, отсекают на одной его стороне равные отрезки, то и на другой '
            'его стороне они отсекают равные отрезки.',
            'Следствие: прямая, проходящая через середину стороны треугольника '
            'параллельно другой его стороне, делит третью сторону пополам.',
        ],
        'params': {'AD': ш, 'высота': в, 'сдвиг_B': сдвиг, 'AG_к_AD': t,
                   'K_на_стороне': K[0] <= ш},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 12. Биссектрисы двух углов при одной стороне параллелограмма
# ────────────────────────────────────────────────────────────────────────
#
# пересекаются на противоположной стороне: точка пересечения — её середина.
#
# Конфигурация. Параллелограмм ABCD; взяты углы при концах одной стороны
# (A и B, B и C, C и D либо A и D). По условию их биссектрисы пересекаются в
# точке на противоположной стороне, и надо доказать, что эта точка — её
# середина. Чисел в сюжете нет и быть не может: конфигурация жёсткая, из неё
# самой следует, что сторона с точкой вдвое длиннее смежной, так что любое
# число в условии оказалось бы либо лишним, либо противоречивым.
#
# Ключевой ход — «биссектриса + параллельность = равнобедренный треугольник».
# Пусть биссектрисы выходят из X и Y, точка пересечения T лежит на стороне ZW
# (Z — сосед Y, W — сосед X). Биссектриса YT отсекает треугольник YZT: угол
# при Y в нём — половина угла параллелограмма по определению биссектрисы, а
# угол при T равен второй половине как накрест лежащий (XY ∥ ZW, секущая YT).
# Углы при Y и T равны, значит, по признаку равнобедренного треугольника
# ZT = YZ. Биссектриса XT точно так же даёт WT = XW. А YZ и XW — противоположные
# стороны параллелограмма, они равны, откуда ZT = WT.
#
# Почему это работает. Накрест лежащие углы переносят половину угла из
# вершины параллелограмма в точку T, а равнобедренность переносит длину
# смежной стороны на кусок противоположной. Две смежные стороны равны между
# собой, поэтому равны и два куска.
#
# Ловушки.
# 1. Какие именно углы накрест лежащие. Секущая — сама биссектриса,
#    параллельные — сторона, из концов которой выходят биссектрисы, и
#    противоположная ей. Угол при T берётся со стороны вершины Z, а не W:
#    ∠XYT = ∠YTZ, тогда как ∠YTW — односторонний с ним, а не равный.
# 2. Признак равнобедренного треугольника нужно называть именно как признак
#    (равные углы ⇒ равные стороны), а не как свойство (наоборот) — ученики
#    путают направление, а эксперт это замечает.
# 3. Побочное следствие ZW = 2·ZY: сторона с точкой вдвое длиннее смежной.
#    Если чертить параллелограмм «на глаз», биссектрисы пересекутся не на
#    стороне, а внутри или снаружи, поэтому чертёж строится строго с
#    отношением сторон 2 : 1. Ещё одно следствие — ∠XTY = 90° (половины углов
#    X и Y дают в сумме 90°), но для доказательства оно не нужно.
#
# Варьируется только буквенная разметка: какая пара соседних углов берётся и
# как названа точка пересечения. Чертёж поворачивается так, чтобы сторона с
# биссектрисами лежала горизонтально, и случайно отражается по горизонтали.


def _отр_12(a, b):
    """Имя отрезка с буквами по алфавиту: AD, а не DA; CN, а не NC."""
    return ''.join(sorted((a, b)))


def _угол_12(a, вершина, b):
    return '\\angle %s%s%s' % (a, вершина, b)


def _единичный_12(от, к):
    dx, dy = к[0] - от[0], к[1] - от[1]
    d = hypot(dx, dy)
    return (dx / d, dy / d)


def _на_биссектрисе(V, U1, U2):
    """Точка на биссектрисе угла U1VU2: сумма единичных векторов его сторон."""
    (ax, ay), (bx, by) = _единичный_12(V, U1), _единичный_12(V, U2)
    return (V[0] + ax + bx, V[1] + ay + by)


@сюжет(12)
def _сюжет_12(rng):
    # Пара соседних углов: X и Y — концы одной стороны в порядке обхода
    # A→B→C→D; Z следует за Y, W — за Z. Тогда XY ∥ ZW, а YZ и WX — вторая
    # пара противоположных сторон. Точка пересечения биссектрис T лежит на ZW.
    буквы = 'ABCD'
    i = rng.randrange(4)
    X, Y, Z, W = [буквы[(i + k) % 4] for k in range(4)]
    T = rng.choice('KMNP')

    XY, ZW = _отр_12(X, Y), _отр_12(Z, W)
    YZ, XW = _отр_12(Y, Z), _отр_12(X, W)
    ZT, WT = _отр_12(Z, T), _отр_12(W, T)
    углы = ' и '.join('\\(%s\\)' % б for б in sorted((X, Y)))

    # Банк формулирует так: «Биссектрисы углов A и B параллелограмма ABCD
    # пересекаются в точке K, лежащей на стороне CD. Докажите, что K —
    # середина CD». Обе формулировки ниже намеренно построены иначе.
    формулировка = rng.choice([1, 2])
    if формулировка == 1:
        условие = (
            '<p>В параллелограмме \\(ABCD\\) провели биссектрисы углов при '
            'вершинах %s. Они пересеклись в точке \\(%s\\), и эта точка оказалась '
            'на стороне \\(%s\\). Докажите, что \\(%s\\) — середина стороны '
            '\\(%s\\).</p>' % (углы, T, ZW, T, ZW))
    else:
        условие = (
            '<p>Биссектрисы углов %s параллелограмма \\(ABCD\\) имеют общую точку '
            '\\(%s\\), принадлежащую стороне \\(%s\\). Докажите, что точка '
            '\\(%s\\) делит сторону \\(%s\\) пополам.</p>' % (углы, T, ZW, T, ZW))

    доказательство = (
        '<p>1. \\(ABCD\\) — параллелограмм, поэтому его противоположные стороны '
        'параллельны и равны: \\(%(XY)s \\parallel %(ZW)s\\) и \\(%(YZ)s = %(XW)s\\).</p>'
        '<p>2. Рассмотрим биссектрису \\(%(Y)s%(T)s\\) угла \\(%(Y)s\\). По определению '
        'биссектрисы \\(%(aXYT)s = %(aTYZ)s\\). Прямые \\(%(XY)s\\) и \\(%(ZW)s\\) '
        'параллельны, \\(%(Y)s%(T)s\\) — секущая, поэтому \\(%(aXYT)s = %(aYTZ)s\\) '
        'как накрест лежащие углы. Значит, \\(%(aTYZ)s = %(aYTZ)s\\).</p>'
        '<p>3. В треугольнике \\(%(Y)s%(Z)s%(T)s\\) углы при вершинах \\(%(Y)s\\) и '
        '\\(%(T)s\\) равны. По признаку равнобедренного треугольника против равных '
        'углов лежат равные стороны: \\(%(ZT)s = %(YZ)s\\).</p>'
        '<p>4. Точно так же поступим с биссектрисой \\(%(X)s%(T)s\\) угла \\(%(X)s\\): '
        '\\(%(aYXT)s = %(aTXW)s\\) по определению биссектрисы, а '
        '\\(%(aYXT)s = %(aXTW)s\\) как накрест лежащие углы при параллельных прямых '
        '\\(%(XY)s\\), \\(%(ZW)s\\) и секущей \\(%(X)s%(T)s\\). Следовательно, '
        '\\(%(aTXW)s = %(aXTW)s\\), треугольник \\(%(X)s%(W)s%(T)s\\) равнобедренный '
        'по тому же признаку, и \\(%(WT)s = %(XW)s\\).</p>'
        '<p>5. Соберём полученные равенства в одну цепочку:</p>'
        '\\[%(ZT)s = %(YZ)s = %(XW)s = %(WT)s,\\]'
        '<p>где среднее равенство — это равенство противоположных сторон '
        'параллелограмма из шага 1. Итак, \\(%(ZT)s = %(WT)s\\). Точка \\(%(T)s\\) '
        'лежит на отрезке \\(%(ZW)s\\) и делит его на два равных отрезка, то есть '
        '\\(%(T)s\\) — середина стороны \\(%(ZW)s\\), что и требовалось доказать.</p>'
        '<p><i>Замечание.</i> Попутно получилось, что '
        '\\(%(ZW)s = %(ZT)s + %(WT)s = 2\\,%(YZ)s\\): такая конфигурация возможна '
        'только в параллелограмме, у которого сторона с точкой \\(%(T)s\\) вдвое '
        'длиннее смежной.</p>'
    ) % {
        'X': X, 'Y': Y, 'Z': Z, 'W': W, 'T': T,
        'XY': XY, 'ZW': ZW, 'YZ': YZ, 'XW': XW, 'ZT': ZT, 'WT': WT,
        'aXYT': _угол_12(X, Y, T), 'aTYZ': _угол_12(T, Y, Z), 'aYTZ': _угол_12(Y, T, Z),
        'aYXT': _угол_12(Y, X, T), 'aTXW': _угол_12(T, X, W), 'aXTW': _угол_12(X, T, W),
    }

    # Чертёж. Сторона с биссектрисами лежит горизонтально: тогда все четыре
    # варианта дают одну и ту же картинку из учебника — широкий параллелограмм
    # 2 : 1, две биссектрисы из концов одной горизонтальной стороны сходятся в
    # середине другой. Отношение сторон 2 : 1 навязано сюжетом: при другом
    # биссектрисы пересеклись бы не на стороне. Обход A→B→C→D — по часовой
    # стрелке (A слева внизу, B слева вверху, ...), как принято на чертежах.
    длинная, короткая = 8.0, 4.0
    угол = rng.choice([60, 64, 68, 72])   # острый угол параллелограмма, градусы
    наклон = rng.choice([1, -1])          # верхняя сторона сдвинута вправо/влево
    s = (наклон * короткая * cos(radians(угол)), короткая * sin(radians(угол)))
    места = [(0.0, 0.0), s, (s[0] + длинная, s[1]), (длинная, 0.0)]
    стороны_подписей = ['юз', 'сз', 'св', 'юв']
    # При обычной посадке (AD внизу) длинные стороны — AD и BC, это годится
    # для пар B–C и A–D. Для пар A–B и C–D разметку сдвигаем на одну вершину:
    # A слева вверху, B справа вверху, C справа внизу, D слева внизу — длинной
    # становится AB, обход по-прежнему по часовой стрелке.
    поворот = 0 if i in (1, 3) else 3
    коорд = {буквы[(j + поворот) % 4]: места[j] for j in range(4)}
    куда = {буквы[(j + поворот) % 4]: стороны_подписей[j] for j in range(4)}
    Xк, Yк, Zк, Wк = коорд[X], коорд[Y], коорд[Z], коорд[W]

    # Точку T строим честно, как в условии, — пересечением двух биссектрис —
    # и сверяем с серединой ZW: при отношении сторон 2 : 1 они обязаны совпасть,
    # это и есть утверждение задачи. Расхождение означало бы ошибку в посадке.
    Tк = пересечение(Xк, _на_биссектрисе(Xк, Yк, Wк),
                     Yк, _на_биссектрисе(Yк, Xк, Zк))
    M = середина(Zк, Wк)
    assert hypot(Tк[0] - M[0], Tк[1] - M[1]) < 1e-6, 'биссектрисы разошлись с серединой'
    Tк = M

    ч = Чертёж(height=210)
    ч.многоугольник([коорд[б] for б in буквы])
    ч.отрезок(Xк, Tк)
    ч.отрезок(Yк, Tк)
    # Половины угла Y и равный им накрест лежащий угол при T — двойные дужки,
    # половины угла X и накрест лежащий при T — одинарные.
    ч.дуга_угла(Yк, Xк, Tк, штрихов=2)
    ч.дуга_угла(Yк, Tк, Zк, штрихов=2)
    ч.дуга_угла(Tк, Yк, Zк, штрихов=2)
    ч.дуга_угла(Xк, Yк, Tк)
    ч.дуга_угла(Xк, Tк, Wк)
    ч.дуга_угла(Tк, Xк, Wк)
    # Четыре равных отрезка из цепочки ZT = YZ = XW = WT.
    for a, b in ((Zк, Tк), (Wк, Tк), (Yк, Zк), (Xк, Wк)):
        ч.равенство(a, b)
    подписать_вершины(ч, *[(коорд[б], б, куда[б]) for б in буквы])
    ч.вершина(Tк, T, 'с' if Tк[1] > s[1] / 2 else 'ю')

    return {
        'title': 'Параллелограмм: биссектрисы двух углов сходятся в середине '
                 'противоположной стороны',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Противоположные стороны параллелограмма попарно параллельны и равны.',
            'Биссектриса угла делит его на два равных угла.',
            'Накрест лежащие углы при параллельных прямых и секущей равны.',
            'Признак равнобедренного треугольника: если два угла треугольника равны, '
            'то равны и противолежащие им стороны.',
        ],
        'params': {'углы': ''.join(sorted((X, Y))), 'сторона': ZW, 'точка': T,
                   'формулировка': формулировка, 'угол_чертежа': угол,
                   'наклон': наклон},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 13. Параллелограмм: сторона вдвое больше смежной, отрезок из вершины
# ────────────────────────────────────────────────────────────────────────
#
# в середину большей стороны — биссектриса угла.
#
# Конфигурация. Параллелограмм ABCD, одна пара сторон вдвое длиннее другой.
# Берём вершину V и ту из двух не содержащих её сторон, которая длинная; её
# середина — точка M (буквы середин в банке закреплены за сторонами: L на AB,
# K на BC, N на CD, M на AD). Доказать нужно, что VM — биссектриса угла
# параллелограмма при вершине V. Вершин четыре, подходящих сторон у каждой
# две — итого восемь посадок одного чертежа. Все восемь получаются из одной
# схемы: V — вершина, X — сосед V по короткой стороне (он же конец длинной),
# Y — вершина, противоположная V, U — второй сосед V. Тогда длинная сторона —
# XY, короткая — VX, а VU ∥ XY.
#
# Ключевой ход. Середина длинной стороны отсекает от неё отрезок, равный
# короткой: XM = XY/2 = VX. Значит, треугольник VXM равнобедренный и
# ∠XVM = ∠XMV. А угол XMV — накрест лежащий с углом MVU при параллельных
# XY, VU и секущей VM. Цепочка ∠XVM = ∠XMV = ∠MVU и есть биссектриса.
#
# Почему коэффициент 2 неприкосновенен. Всё держится на равенстве XM = VX.
# При XY = n·VX точку пришлось бы брать не в середине, а на расстоянии VX от
# X (деление 1 : (n − 1)), и слово «середина» исчезло бы. Поэтому из чисел
# генерируется только масштаб — пара (m, 2m). Форма параллелограмма роли не
# играет: утверждение верно и для прямоугольника, там получается угол 45°.
#
# Ловушки.
# * Параллельность нужна правильная: та пара, где лежат длинная сторона и
#   второй сосед V (XY ∥ VU), а не пара с короткой стороной. Сославшись на
#   «AB ∥ CD» там, где треугольник построен на BC, накрест лежащих углов
#   не получить.
# * Сюжет 12 — обратная задача (биссектрисы ⇒ середина): там ход идёт от
#   равных углов к равным сторонам, здесь — наоборот. «Биссектриса отсекает
#   равнобедренный треугольник» здесь не дано, а доказывается.
# * В конце надо явно сказать, что луч VM проходит внутри угла при V
#   (точка M лежит на стороне параллелограмма): само по себе равенство двух
#   углов с общей стороной биссектрису ещё не даёт.
# * Чертёж: при угле 60° треугольник VXM с вершиной X при остром угле
#   параллелограмма выходит равносторонним, и картинка подсказывает лишнее.
#   Уже при 64°–66° он на глаз почти равносторонний (основание 1,06–1,09
#   боковой стороны), поэтому угол берём из промежутка 68°–76°: основание
#   не короче 1,12 боковой.


ВЕРШИНЫ_13 = ['A', 'B', 'C', 'D']

# Буквы середин закреплены за сторонами так же, как в банке.
БУКВА_СЕРЕДИНЫ = {'AB': 'L', 'BC': 'K', 'CD': 'N', 'AD': 'M'}

# Как принято называть угол параллелограмма при каждой вершине.
УГОЛ_ПРИ = {'A': 'BAD', 'B': 'ABC', 'C': 'BCD', 'D': 'ADC'}


def _сторона(p, q):
    """Имя стороны в привычном порядке букв: AB, BC, CD, AD."""
    return ''.join(sorted((p, q)))


@сюжет(13)
def _сюжет_13(rng):
    # ── посадка: вершина и длинная сторона ─────────────────────────────
    # Соседей перемешиваем: который из них станет X, тот и задаёт, какая
    # из двух не содержащих V сторон объявлена длинной. Так перебираются
    # все 4 × 2 = 8 расстановок банка.
    i = rng.randrange(4)
    V = ВЕРШИНЫ_13[i]
    Y = ВЕРШИНЫ_13[(i + 2) % 4]
    соседи = [ВЕРШИНЫ_13[(i - 1) % 4], ВЕРШИНЫ_13[(i + 1) % 4]]
    rng.shuffle(соседи)
    X, U = соседи                      # VX — короткая, XY — длинная, VU ∥ XY
    Mб = БУКВА_СЕРЕДИНЫ[_сторона(X, Y)]
    угол = УГОЛ_ПРИ[V]

    # Имена отрезков и углов в том порядке букв, в каком их читают.
    VX, XY, VU = _сторона(V, X), _сторона(X, Y), _сторона(V, U)
    VM, XM, MY = V + Mб, X + Mб, Mб + Y
    трVXM = V + X + Mб
    углXVM, углXMV, углMVU = X + V + Mб, X + Mб + V, Mб + V + U

    # ── числа: только масштаб, коэффициент 2 жёсткий ───────────────────
    m = rng.choice([3, 4, 5, 6, 7, 8, 9, 10, 12])
    a, b = m, 2 * m
    с_числами = rng.random() < 0.5

    # ── условие ────────────────────────────────────────────────────────
    if с_числами:
        условие = (
            '<p>В параллелограмме \\(ABCD\\) известно, что \\(%s = %d\\), '
            '\\(%s = %d\\), а точка \\(%s\\) — середина стороны \\(%s\\). '
            'Докажите, что \\(%s\\) — биссектриса угла \\(%s\\).</p>'
            % (VX, a, XY, b, Mб, XY, VM, угол))
        шаг1 = (
            '<p>1. По условию \\(%s = %d\\) и \\(%s = %d\\). Точка \\(%s\\) — '
            'середина стороны \\(%s\\), поэтому '
            '\\(%s = %s = \\dfrac{%s}{2} = \\dfrac{%d}{2} = %d\\). '
            'Итак, \\(%s = %s = %d\\).</p>'
            % (VX, a, XY, b, Mб, XY, XM, MY, XY, b, a, XM, VX, a))
    else:
        условие = (
            '<p>В параллелограмме \\(ABCD\\) сторона \\(%s\\) в два раза длиннее '
            'стороны \\(%s\\), а точка \\(%s\\) — середина стороны \\(%s\\). '
            'Докажите, что отрезок \\(%s\\) — биссектриса угла \\(%s\\).</p>'
            % (XY, VX, Mб, XY, VM, угол))
        шаг1 = (
            '<p>1. Обозначим \\(%s = x\\); тогда по условию \\(%s = 2x\\). '
            'Точка \\(%s\\) — середина стороны \\(%s\\), поэтому '
            '\\(%s = %s = \\dfrac{%s}{2} = x\\). Итак, \\(%s = %s\\).</p>'
            % (VX, XY, Mб, XY, XM, MY, XY, XM, VX))

    # ── доказательство ─────────────────────────────────────────────────
    доказательство = шаг1 + (
        '<p>2. В треугольнике \\(%s\\) стороны \\(%s\\) и \\(%s\\) равны, '
        'значит, он равнобедренный с основанием \\(%s\\). Углы при основании '
        'равнобедренного треугольника равны: \\(\\angle %s = \\angle %s\\).</p>'
        '<p>3. \\(%s\\) и \\(%s\\) — противоположные стороны параллелограмма '
        '\\(ABCD\\), поэтому \\(%s \\parallel %s\\). Прямая \\(%s\\) — секущая '
        'при этих параллельных прямых, причём точки \\(%s\\) и \\(%s\\) лежат '
        'по разные стороны от неё. Значит, \\(\\angle %s\\) и \\(\\angle %s\\) — '
        'внутренние накрест лежащие углы, а такие углы при параллельных прямых '
        'равны: \\(\\angle %s = \\angle %s\\).</p>'
        '<p>4. Соединяем пункты 2 и 3: '
        '\\[\\angle %s = \\angle %s = \\angle %s,\\] '
        'то есть \\(\\angle %s = \\angle %s\\).</p>'
        '<p>5. Точка \\(%s\\) лежит на стороне \\(%s\\) параллелограмма, '
        'поэтому луч \\(%s\\) проходит внутри угла \\(%s\\) и разбивает его '
        'на углы \\(%s\\) и \\(%s\\). Эти углы равны, следовательно, по '
        'определению биссектрисы \\(%s\\) — биссектриса угла \\(%s\\), '
        'что и требовалось доказать.</p>'
        % (трVXM, VX, XM, VM, углXVM, углXMV,
           XY, VU, XY, VU, VM, X, U, углXMV, углMVU, углXMV, углMVU,
           углXVM, углXMV, углMVU, углXVM, углMVU,
           Mб, XY, VM, угол, углXVM, углMVU, VM, угол))

    # ── чертёж ─────────────────────────────────────────────────────────
    # Длинную пару сторон кладём горизонтально: короткая сторона — единица,
    # длинная — двойка, тогда середина длинной стороны честно отстоит от X
    # ровно на короткую сторону. Наклон и его направление варьируем.
    α = math.radians(rng.randint(68, 76))
    dx, h = rng.choice([1, -1]) * math.cos(α), math.sin(α)
    if XY in ('AD', 'BC'):
        коорд = {'A': (0.0, 0.0), 'D': (2.0, 0.0),
                 'B': (dx, h), 'C': (dx + 2.0, h)}
    else:
        коорд = {'A': (0.0, 0.0), 'B': (2.0, 0.0),
                 'C': (2.0 + dx, h), 'D': (dx, h)}
    pV, pX, pY, pU = (коорд[t] for t in (V, X, Y, U))
    pM = середина(pX, pY)

    # Подпись вершины уводим от центра фигуры, чтобы она не легла на линии.
    cx = sum(p[0] for p in коорд.values()) / 4.0
    cy = h / 2.0

    def куда(p):
        return ('ю' if p[1] < cy else 'с') + ('з' if p[0] < cx else 'в')

    ч = Чертёж(height=230)
    ч.многоугольник([коорд[t] for t in ВЕРШИНЫ_13])
    ч.отрезок(pV, pM)
    # Три равных отрезка: короткая сторона и две половины длинной.
    ч.равенство(pV, pX)
    ч.равенство(pX, pM)
    ч.равенство(pM, pY)
    # Три равных угла: два при V (их равенство и доказываем) и угол при M,
    # через который они связаны.
    r = 0.24
    ч.дуга_угла(pV, pX, pM, радиус=r)
    ч.дуга_угла(pV, pM, pU, радиус=r)
    ч.дуга_угла(pM, pX, pV, радиус=r)
    подписать_вершины(ч, *[(коорд[t], t, куда(коорд[t])) for t in ВЕРШИНЫ_13])
    ч.вершина(pM, Mб, 'с' if pM[1] > cy else 'ю')

    return {
        'title': 'Параллелограмм: сторона вдвое больше смежной, '
                 'отрезок в середину — биссектриса угла',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Противоположные стороны параллелограмма параллельны.',
            'В равнобедренном треугольнике углы при основании равны.',
            'Внутренние накрест лежащие углы при параллельных прямых и секущей равны.',
            'Биссектриса угла — луч из его вершины, делящий угол на два равных угла.',
        ],
        'params': {
            'вершина': V, 'середина': Mб,
            'короткая': VX, 'длинная': XY,
            'a': a, 'b': b, 'соотношение': 'b = 2·a',
            'с_числами': с_числами,
            'угол_градусов': round(math.degrees(α)),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 14. Точка внутри параллелограмма: два «противоположных» треугольника
# ────────────────────────────────────────────────────────────────────────
#
# дают половину площади.
#
# Конфигурация. Параллелограмм ABCD и произвольная точка внутри него (буква
# меняется: E, F, M, P). Точку соединяют с четырьмя вершинами, и параллелограмм
# распадается на четыре треугольника. Берутся два из них, стоящие на
# противоположных сторонах, — BEC и AED (основания BC и AD) либо AEB и CED
# (основания AB и CD). Нужно доказать, что вместе они дают ровно половину
# площади параллелограмма, где бы точка ни стояла.
#
# Ключевой ход. Через точку проводят общий перпендикуляр к двум параллельным
# сторонам; он пересекает их прямые в K и L. Отрезок KL — высота
# параллелограмма h, а его куски KE = x и EL = h − x — высоты обоих
# треугольников, потому что KL перпендикулярен обеим сторонам сразу. Основания
# треугольников равны как противоположные стороны параллелограмма (a). Тогда
#
#     S₁ + S₂ = ½·a·x + ½·a·(h − x) = ½·a·h = ½·S(ABCD).
#
# Почему это работает: x входит в два слагаемых с противоположными знаками и
# сокращается, поэтому от положения точки сумма не зависит. Отсюда же и
# вторая пара треугольников даёт половину — оставшуюся.
#
# Ловушки.
# 1. Точка обязана лежать внутри, то есть между прямыми BC и AD: именно отсюда
#    KE + EL = KL. Для точки вне полосы одна из «высот» меняет знак, и сумма
#    превращается в разность.
# 2. Основания перпендикуляра могут упасть на продолжения сторон, если
#    параллелограмм сильно скошен. Поэтому в доказательстве речь идёт о прямых
#    BC и AD, а не об отрезках, а высота треугольника — это расстояние от
#    вершины до прямой, содержащей сторону. Чертёж при этом строится так,
#    чтобы K и L попали на сами стороны: ученик срисовывает его как образец.
# 3. Точку нельзя ставить в центр параллелограмма или на диагональ: картинка
#    станет подсказкой «частного случая», а доказать нужно для произвольной
#    точки. Генератор такие положения отбрасывает.
# 4. Пара треугольников должна быть противоположной. Для соседних (AEB и BEC)
#    постоянной суммы нет — она меняется вместе с точкой.
#
# Чисел в сюжете нет: варьируются буква точки, пара сторон и формулировка.


# Рамка буквы для проверки столкновений, px при размере шрифта 13: полуширина
# самой широкой из букв точки (M) и полувысота прописной буквы.
ПОЛУШИРИНА_БУКВЫ, ПОЛУВЫСОТА_БУКВЫ = 5.5, 4.5
# Наименьший зазор между рамкой буквы и любой линией чертежа, px. Белая
# обводка буквы в geom_svg — 1,5 px, при таком зазоре она линию не задевает.
ЗАЗОР_ПОДПИСИ = 2.0
# Радиусы, на которых пробуем ставить букву точки, px от самой точки.
РАДИУСЫ_ПОДПИСИ = (18, 21, 24, 27)

# Две пары противоположных сторон. осн1 — сторона, на прямой которой лежит K,
# осн2 — на прямой которой лежит L; перп_к — сторона, к которой по условию
# проводится перпендикуляр (она же множитель в формуле площади
# параллелограмма), другая — вторая сторона пары, перпендикулярность которой
# приходится доказывать.
ПАРЫ = {
    'BC-AD': dict(осн1='BC', осн2='AD', перп_к='AD', другая='BC'),
    'AB-CD': dict(осн1='AB', осн2='CD', перп_к='AB', другая='CD'),
}

БУКВЫ_ТОЧКИ = ('E', 'E', 'F', 'M', 'P')

# Сторона квадратика прямого угла в мировых единицах. Квадратик раскрывается
# от K (или L) в сторону середины стороны, где стоит штрих равенства, поэтому
# от размера зависит, насколько далеко от середины должна лечь точка.
РАЗМЕР_УГЛА = 0.38

# Положение точки внутри параллелограмма в долях сторон: E = A + u·AD + v·AB.
# Ближе 0,2 к стороне точку не ставим: треугольник на этой стороне получился
# бы плоским, и отрезок-высота стал бы неразличимо коротким.
СЕТКА = [round(0.20 + 0.025 * i, 3) for i in range(25)]       # 0,20 … 0,80


def _доля_14(P, Q, X):
    """Положение точки X прямой PQ как доля отрезка PQ: 0 в P, 1 в Q."""
    dx, dy = Q[0] - P[0], Q[1] - P[1]
    return ((X[0] - P[0]) * dx + (X[1] - P[1]) * dy) / float(dx * dx + dy * dy)


def _длина(P, Q):
    return ((Q[0] - P[0]) ** 2 + (Q[1] - P[1]) ** 2) ** 0.5


def _единичный_14(P, Q):
    """Единичный вектор от P к Q."""
    d = _длина(P, Q) or 1.0
    return ((Q[0] - P[0]) / d, (Q[1] - P[1]) / d)


def _масштаб(a, h, s):
    """Пикселей в мировой единице — тот же расчёт, что в Чертёж._преобразование.

    Рамку чертежа задают вершины параллелограмма (ширина a + s, высота h);
    все остальные точки лежат внутри неё и на масштаб не влияют.
    """
    ч = Чертёж()
    return min((ч.width - 2 * ч.поле) / float(a + s),
               (ч.height - 2 * ч.поле) / float(h))


def _расстояние_до_отрезка(X, P, Q):
    px, py = P
    dx, dy = Q[0] - px, Q[1] - py
    L2 = dx * dx + dy * dy
    t = ((X[0] - px) * dx + (X[1] - py) * dy) / L2 if L2 else 0.0
    t = max(0.0, min(1.0, t))
    return math.hypot(X[0] - px - t * dx, X[1] - py - t * dy)


def _пересекаются(P1, P2, P3, P4):
    def ccw(A, B, C):
        return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])
    return (ccw(P1, P3, P4) != ccw(P2, P3, P4)
            and ccw(P1, P2, P3) != ccw(P1, P2, P4))


def _зазор(центр, отрезки):
    """Наименьшее расстояние от рамки буквы с данным центром до отрезков, px.

    Ноль, если хоть один отрезок задевает рамку.
    """
    x0, y0 = центр[0] - ПОЛУШИРИНА_БУКВЫ, центр[1] - ПОЛУВЫСОТА_БУКВЫ
    x1, y1 = центр[0] + ПОЛУШИРИНА_БУКВЫ, центр[1] + ПОЛУВЫСОТА_БУКВЫ
    углы = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
    рёбра = list(zip(углы, углы[1:] + углы[:1]))
    лучший = float('inf')
    for P, Q in отрезки:
        for X in (P, Q):
            if x0 <= X[0] <= x1 and y0 <= X[1] <= y1:
                return 0.0
        if any(_пересекаются(P, Q, C, D) for C, D in рёбра):
            return 0.0
        d = min(_расстояние_до_отрезка(X, P, Q) for X in углы)
        d = min([d] + [_расстояние_до_отрезка(X, C, D)
                       for X in (P, Q) for C, D in рёбра])
        лучший = min(лучший, d)
    return лучший


def _линии_чертежа(точки, E, K, L, осн1, осн2, tK, tL, k):
    """Все линии чертежа как отрезки в экранных px относительно точки E.

    Стороны, шесть отрезков из E, оба квадратика прямого угла и оба штриха
    равенства — ровно то, что рисует _сюжет_14, чтобы буква точки ни на что
    из этого не легла. Ось y, как на экране, направлена вниз.
    """
    A, B, C, D = (точки[б] for б in 'ABCD')
    P1, Q1 = точки[осн1[0]], точки[осн1[1]]
    P2, Q2 = точки[осн2[0]], точки[осн2[1]]
    линии = [(A, B), (B, C), (C, D), (D, A),
             (E, A), (E, B), (E, C), (E, D), (E, K), (E, L)]
    # Квадратики: те же направления, что в ч.прямой_угол ниже.
    for верш, дальний in ((K, Q1 if tK < 0.5 else P1),
                          (L, Q2 if tL < 0.5 else P2)):
        u1, u2 = _единичный_14(верш, E), _единичный_14(верш, дальний)
        p1 = (верш[0] + РАЗМЕР_УГЛА * u1[0], верш[1] + РАЗМЕР_УГЛА * u1[1])
        p3 = (верш[0] + РАЗМЕР_УГЛА * u2[0], верш[1] + РАЗМЕР_УГЛА * u2[1])
        p2 = (p1[0] + РАЗМЕР_УГЛА * u2[0], p1[1] + РАЗМЕР_УГЛА * u2[1])
        линии += [(p1, p2), (p2, p3)]
    # Штрихи равенства: 10 px поперёк середины стороны.
    for P, Q in ((P1, Q1), (P2, Q2)):
        M, u = середина(P, Q), _единичный_14(P, Q)
        n, пол = (-u[1], u[0]), 5.0 / k
        линии.append(((M[0] - n[0] * пол, M[1] - n[1] * пол),
                      (M[0] + n[0] * пол, M[1] + n[1] * пол)))

    def экран(p):
        return ((p[0] - E[0]) * k, -(p[1] - E[1]) * k)

    return [(экран(P), экран(Q)) for P, Q in линии]


def _место_подписи(E, соседи, линии):
    """Куда ставить букву точки E: центр буквы в px относительно E и зазор.

    Из E выходят шесть отрезков, и восьми фиксированных сторон geom_svg мало:
    их смещения 10–17 px, а между соседними лучами в среднем 60°, и на таком
    расстоянии буква ложится на один из них. Поэтому пробуем биссектрисы всех
    промежутков между соседними лучами на нескольких радиусах и берём
    ближайшее к точке место, где рамка буквы отстоит от каждой линии хотя бы
    на ЗАЗОР_ПОДПИСИ; если такого нет — место с наибольшим зазором.
    """
    углы = sorted(math.atan2(-(N[1] - E[1]), N[0] - E[0]) for N in соседи)
    биссектрисы = []
    for i, ψ in enumerate(углы):
        след = углы[(i + 1) % len(углы)]
        if i == len(углы) - 1:
            след += 2 * math.pi
        биссектрисы.append((ψ + след) / 2)
    лучшее = None
    for r in РАДИУСЫ_ПОДПИСИ:
        for φ in биссектрисы:
            центр = (r * math.cos(φ), r * math.sin(φ))
            з = _зазор(центр, линии)
            if лучшее is None or з > лучшее[1]:
                лучшее = (центр, з)
        if лучшее[1] >= ЗАЗОР_ПОДПИСИ:
            break
    return лучшее


def _якорь_подписи_14(E, центр, k):
    """Переводим желаемый центр буквы (px от E) в аргументы ч.подпись.

    geom_svg ставит букву со смещением СТОРОНЫ[сторона] от якоря, а центр
    прописной буквы лежит на ПОЛУВЫСОТА_БУКВЫ выше базовой линии. Берём
    сторону, чьё смещение ближе всего по направлению к нужному, и сдвигаем
    якорь так, чтобы буква легла точно в рассчитанное место. Якорь при этом
    остаётся в паре десятков px от E, внутри параллелограмма, и масштаб
    чертежа не меняет.
    """
    φ = math.atan2(центр[1], центр[0])

    def отклонение(сторона):
        dx, dy = СТОРОНЫ[сторона]
        return abs((math.atan2(dy, dx) - φ + math.pi) % (2 * math.pi) - math.pi)

    сторона = min(sorted(СТОРОНЫ), key=отклонение)
    dx, dy = СТОРОНЫ[сторона]
    якорь = (центр[0] - dx, центр[1] - (dy - ПОЛУВЫСОТА_БУКВЫ))
    return сторона, (E[0] + якорь[0] / k, E[1] - якорь[1] / k)


def _свободная_сторона(E, соседи):
    """Куда ставить подпись точки E, из которой выходят отрезки к соседям.

    Из восьми сторон geom_svg.СТОРОНЫ берём ту, чьё направление дальше всего
    по углу от всех лучей E→сосед: тогда буква не ложится ни на один из них.
    Смещения подписей заданы в экранных координатах (ось y вниз), поэтому
    у мировых направлений переворачиваем y.
    """
    лучи = [math.atan2(-(N[1] - E[1]), N[0] - E[0]) for N in соседи]

    def зазор(сторона):
        dx, dy = СТОРОНЫ[сторона]
        φ = math.atan2(dy, dx)
        return min(abs((φ - ψ + math.pi) % (2 * math.pi) - math.pi)
                   for ψ in лучи)

    return max(sorted(СТОРОНЫ), key=зазор)


def _допустимые_положения(a, h, s, точки, осн1, осн2):
    """Все (u, v) из сетки, при которых чертёж получается честным.

    Отсекаем: основания перпендикуляра на продолжениях сторон (иначе ученик
    срисует картинку, где высота «висит» снаружи); основание рядом с
    серединой стороны (там стоит штрих равенства, точка на него налезет);
    точку на диагонали или в центре (частный случай вместо произвольного);
    положения, где букве точки негде встать, не задев одну из линий.
    """
    P1, Q1 = точки[осн1[0]], точки[осн1[1]]
    P2, Q2 = точки[осн2[0]], точки[осн2[1]]
    k = _масштаб(a, h, s)
    # Квадратик прямого угла плюс зазор, в долях длины стороны: ближе к
    # середине он наехал бы на штрих равенства.
    зазор1 = (РАЗМЕР_УГЛА + 0.15) / _длина(P1, Q1)
    зазор2 = (РАЗМЕР_УГЛА + 0.15) / _длина(P2, Q2)
    годные = []
    for u in СЕТКА:
        for v in СЕТКА:
            if abs(u - v) < 0.1 or abs(u + v - 1) < 0.1:
                continue                       # диагонали AC и BD
            E = (u * a + v * s, v * h)
            K, L = проекция(P1, Q1, E), проекция(P2, Q2, E)
            tK, tL = _доля_14(P1, Q1, K), _доля_14(P2, Q2, L)
            if not (0.15 <= tK <= 0.85 and 0.15 <= tL <= 0.85):
                continue
            if abs(tK - 0.5) < зазор1 or abs(tL - 0.5) < зазор2:
                continue
            линии = _линии_чертежа(точки, E, K, L, осн1, осн2, tK, tL, k)
            соседи = [точки[б] for б in 'ABCD'] + [K, L]
            if _место_подписи(E, соседи, линии)[1] < ЗАЗОР_ПОДПИСИ:
                continue
            годные.append((u, v))
    return годные


@сюжет(14)
def _сюжет_14(rng):
    пара = rng.choice(sorted(ПАРЫ))
    п = dict(ПАРЫ[пара])
    X = rng.choice(БУКВЫ_ТОЧКИ)
    осн1, осн2 = п['осн1'], п['осн2']
    # Имена треугольников — точка посередине: BEC и AED, AEB и CED.
    п.update(X=X, т1=осн1[0] + X + осн1[1], т2=осн2[0] + X + осн2[1])

    if rng.random() < 0.5:
        условие = (
            '<p>Точку \\(%(X)s\\), лежащую внутри параллелограмма \\(ABCD\\), '
            'соединили отрезками со всеми его вершинами. Докажите, что площади '
            'треугольников \\(%(т1)s\\) и \\(%(т2)s\\) в сумме составляют '
            'половину площади параллелограмма, где бы ни была взята точка '
            '\\(%(X)s\\).</p>' % п)
    else:
        условие = (
            '<p>Точка \\(%(X)s\\) выбрана внутри параллелограмма \\(ABCD\\) '
            'произвольно. Докажите, что '
            '\\(S_{%(т1)s} + S_{%(т2)s} = \\dfrac{1}{2}\\,S_{ABCD}\\).</p>' % п)

    доказательство = (
        '<p>1. Проведём через точку \\(%(X)s\\) прямую, перпендикулярную '
        'стороне \\(%(перп_к)s\\). Пусть она пересекает прямую \\(%(осн1)s\\) '
        'в точке \\(K\\), а прямую \\(%(осн2)s\\) — в точке \\(L\\). '
        'Стороны \\(%(осн1)s\\) и \\(%(осн2)s\\) параллельны как противоположные '
        'стороны параллелограмма, а прямая, перпендикулярная одной из двух '
        'параллельных прямых, перпендикулярна и другой. По построению '
        '\\(KL \\perp %(перп_к)s\\), значит, и \\(KL \\perp %(другая)s\\). '
        'Итак, \\(KL\\) — общий перпендикуляр к прямым \\(%(осн1)s\\) и '
        '\\(%(осн2)s\\); его длина равна расстоянию между этими прямыми, то есть '
        'высоте параллелограмма, проведённой к стороне \\(%(перп_к)s\\). '
        'Обозначим \\(KL = h\\).</p>'

        '<p>2. Точка \\(%(X)s\\) лежит внутри параллелограмма, то есть в полосе '
        'между параллельными прямыми \\(%(осн1)s\\) и \\(%(осн2)s\\). Поэтому на '
        'прямой \\(KL\\) она находится между точками \\(K\\) и \\(L\\), и '
        '\\(%(X)sK + %(X)sL = KL = h\\). Обозначим \\(%(X)sK = x\\); тогда '
        '\\(%(X)sL = h - x\\).</p>'

        '<p>3. \\(%(осн1)s = %(осн2)s\\) как противоположные стороны '
        'параллелограмма. Обозначим их общую длину через \\(a\\).</p>'

        '<p>4. В треугольнике \\(%(т1)s\\) точка \\(K\\) лежит на прямой '
        '\\(%(осн1)s\\) и \\(%(X)sK \\perp %(осн1)s\\), значит, \\(%(X)sK\\) — '
        'высота этого треугольника, проведённая к стороне \\(%(осн1)s\\). '
        'Площадь треугольника равна половине произведения стороны на '
        'проведённую к ней высоту:</p>'
        '\\[S_{%(т1)s} = \\frac{1}{2}\\cdot %(осн1)s \\cdot %(X)sK = '
        '\\frac{1}{2}\\,a x.\\]'
        '<p>Точно так же в треугольнике \\(%(т2)s\\) отрезок \\(%(X)sL\\) — '
        'высота, проведённая к стороне \\(%(осн2)s\\), поэтому</p>'
        '\\[S_{%(т2)s} = \\frac{1}{2}\\cdot %(осн2)s \\cdot %(X)sL = '
        '\\frac{1}{2}\\,a\\,(h - x).\\]'

        '<p>5. Сложим найденные площади:</p>'
        '\\[S_{%(т1)s} + S_{%(т2)s} = \\frac{1}{2}\\,a x + '
        '\\frac{1}{2}\\,a\\,(h - x) = \\frac{1}{2}\\,a h.\\]'
        '<p>Слагаемые с \\(x\\) взаимно уничтожились, поэтому сумма не зависит '
        'от того, где именно внутри параллелограмма взята точка '
        '\\(%(X)s\\).</p>'

        '<p>6. Площадь параллелограмма равна произведению стороны на '
        'проведённую к ней высоту: \\(S_{ABCD} = %(перп_к)s \\cdot KL = a h\\). '
        'Следовательно,</p>'
        '\\[S_{%(т1)s} + S_{%(т2)s} = \\frac{1}{2}\\,a h = '
        '\\frac{1}{2}\\,S_{ABCD},\\]'
        '<p>что и требовалось доказать.</p>' % п)

    # ── Чертёж ────────────────────────────────────────────────────────────
    # AD внизу горизонтально, B над A со сдвигом s вправо — учебная посадка.
    if пара == 'BC-AD':
        a, h, s = 6.0, 3.6, rng.choice([1.4, 1.7, 2.0])
    else:
        # Перпендикуляр к боковой стороне идёт почти горизонтально, и чтобы
        # его концы легли на сами AB и CD, а не на продолжения, параллелограмм
        # берём выше и с меньшим скосом.
        a, h, s = 4.8, 4.2, rng.choice([1.1, 1.3, 1.5])
    A, D = (0.0, 0.0), (a, 0.0)
    B, C = (s, h), (s + a, h)
    точки = {'A': A, 'B': B, 'C': C, 'D': D}
    P1, Q1 = точки[осн1[0]], точки[осн1[1]]
    P2, Q2 = точки[осн2[0]], точки[осн2[1]]

    годные = _допустимые_положения(a, h, s, точки, осн1, осн2)
    u, v = rng.choice(годные) if годные else (0.35, 0.55)
    E = (u * a + v * s, v * h)
    K = проекция(P1, Q1, E)
    L = проекция(P2, Q2, E)
    tK, tL = _доля_14(P1, Q1, K), _доля_14(P2, Q2, L)

    ч = Чертёж()
    ч.многоугольник([A, B, C, D], залить=False)
    # Два треугольника из условия закрашены: сразу видно, о какой половине
    # площади речь. Их стороны — это и есть отрезки из E ко всем вершинам.
    ч.многоугольник([P1, E, Q1])
    ч.многоугольник([P2, E, Q2])
    ч.отрезок(K, L, пунктир=True)                    # вспомогательное построение
    # Квадратик прямого угла рисуем в сторону дальнего конца стороны — тогда
    # он не упирается в подпись K или L.
    ч.прямой_угол(K, E, Q1 if tK < 0.5 else P1, размер=РАЗМЕР_УГЛА)
    ч.прямой_угол(L, E, Q2 if tL < 0.5 else P2, размер=РАЗМЕР_УГЛА)
    ч.равенство(P1, Q1)
    ч.равенство(P2, Q2)

    # Из точки выходят шесть отрезков (к четырём вершинам, к K и к L), и
    # свободный сектор гуляет вместе с точкой. Букву ставим на биссектрису
    # самого просторного промежутка, отодвинув настолько, чтобы её рамка не
    # задевала ни одной линии чертежа (положения без такого места отсеяны в
    # _допустимые_положения). Для K и L лучей всего три и свободна внешняя
    # сторона параллелограмма — там хватает фиксированных сторон geom_svg.
    k = _масштаб(a, h, s)
    линии = _линии_чертежа(точки, E, K, L, осн1, осн2, tK, tL, k)
    центр_X, зазор_X = _место_подписи(E, [A, B, C, D, K, L], линии)
    сторона_X, якорь_X = _якорь_подписи_14(E, центр_X, k)
    сторона_K = _свободная_сторона(K, [P1, Q1, E])
    сторона_L = _свободная_сторона(L, [P2, Q2, E])
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'), (K, 'K', сторона_K), (L, 'L', сторона_L))
    ч.точка(E)
    ч.подпись(якорь_X, X, сторона_X)

    return {
        'title': 'Точка внутри параллелограмма: сумма площадей двух '
                 'противоположных треугольников',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Противоположные стороны параллелограмма равны и параллельны.',
            'Прямая, перпендикулярная одной из двух параллельных прямых, '
            'перпендикулярна и другой; длина общего перпендикуляра — расстояние '
            'между этими прямыми, и оно постоянно.',
            'Площадь треугольника равна половине произведения стороны на '
            'высоту, проведённую к этой стороне.',
            'Площадь параллелограмма равна произведению стороны на высоту, '
            'проведённую к этой стороне.',
        ],
        'params': {'точка': X, 'пара': пара, 'u': u, 'v': v, 's': s,
                   'tK': round(tK, 3), 'tL': round(tL, 3)},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 15. Диагонали параллелограмма: площадь параллелограмма вчетверо
# ────────────────────────────────────────────────────────────────────────
#
# больше площади треугольника при стороне и точке пересечения диагоналей.
#
# Конфигурация. Параллелограмм ABCD, диагонали пересекаются в точке K (в
# части вариантов банка — O). Требуется доказать S(ABCD) = 4·S(AKD): площадь
# треугольника, отсечённого стороной и двумя половинками диагоналей, — ровно
# четверть параллелограмма. Чисел в условии нет; «четыре» — заключение, а не
# параметр: оно жёстко следует из построения и не меняется.
#
# Ключевой ход — двойное деление пополам:
#   1. диагональ AC режет параллелограмм на два равных треугольника ACD и
#      ABC (по трём сторонам: AC общая, противоположные стороны равны), и
#      потому каждый из них — половина площади;
#   2. в треугольнике ACD отрезок DK — медиана (K — середина AC по свойству
#      диагоналей), а медиана делит треугольник на два равновеликих: у AKD и
#      CKD основания AK = KC лежат на одной прямой, высота DH общая.
# Половина от половины — четверть. Можно идти и через другую диагональ: тогда
# большой треугольник ABD, медиана AK; оба пути равноправны, и здесь выбор
# делается по чертежу — так, чтобы высота к диагонали ложилась внутрь неё, а
# не почти вдоль стороны параллелограмма.
#
# Почему это работает для любого параллелограмма: единственное, что нужно, —
# K делит обе диагонали пополам, и это верно всегда. Отсюда же более сильный
# факт: все четыре треугольника AKB, BKC, CKD, AKD равновелики.
#
# Ловушки.
#   * «Треугольники AKD и AKB равны» — неверно: они лишь равновелики. Равны
#     (конгруэнтны) в общем случае только противоположные пары, AKD = CKB и
#     AKB = CKD (соседние равны лишь в ромбе).
#     Обосновывать четверть через «четыре равных треугольника» нельзя.
#   * «Диагональ делит параллелограмм пополам» без обоснования эксперт
#     засчитает как пробел; нужно назвать признак равенства треугольников
#     (или свойство площадей равных фигур).
#   * «Медиана делит треугольник на два равновеликих» — факт из учебника, но
#     его стоит доказать одной строкой через общую высоту: тогда вопросов к
#     полноте не будет, а высота должна быть на чертеже.
#   * Высоту к диагонали нельзя проводить «из любой вершины»: из вершины
#     острого угла её основание уходит за конец диагонали или почти совпадает
#     со стороной, и чертёж перестаёт помогать. Поэтому вершина выбирается
#     по чертежу, а не по букве.


# Порядок обхода вершин; противоположная вершина — через одну.
_ВЕРШИНЫ = 'ABCD'
_ПРОТИВ = {'A': 'C', 'B': 'D', 'C': 'A', 'D': 'B'}

# Компас для подписей: угол направления (в мировых координатах, ось y
# вверх) и сторона из geom_svg.СТОРОНЫ.
_КОМПАС = [('в', 0), ('св', 45), ('с', 90), ('сз', 135),
           ('з', 180), ('юз', 225), ('ю', 270), ('юв', 315)]


def _куда(dx, dy):
    """Ближайшая из восьми сторон света к направлению (dx, dy)."""
    угол = math.degrees(math.atan2(dy, dx)) % 360

    def отклонение(пара):
        d = abs(угол - пара[1])
        return min(d, 360 - d)

    return min(_КОМПАС, key=отклонение)[0]


def _имя_15(*буквы, точка=None):
    """Имя треугольника или отрезка в школьном порядке: вершины
    параллелограмма по алфавиту, буква точки пересечения — посередине
    (AKD, а не DKA; BKC, а не CKB)."""
    свои = sorted(б for б in буквы if б != точка)
    if точка is not None and точка in буквы:
        return свои[0] + точка + свои[1]
    return ''.join(свои)


def _параметр(P, Q, H):
    """Доля отрезка PQ, на которой стоит точка H прямой PQ (0 в P, 1 в Q)."""
    ux, uy = Q[0] - P[0], Q[1] - P[1]
    return ((H[0] - P[0]) * ux + (H[1] - P[1]) * uy) / float(ux * ux + uy * uy)


@сюжет(15)
def _сюжет_15(rng):
    # Варьируется только то, что честно варьируется: буква точки
    # пересечения, сторона, при которой стоит треугольник, наклон чертежа
    # и оборот речи в условии. Число 4 — вывод, его не трогаем.
    K = rng.choice(['K', 'O'])
    i = rng.randrange(4)
    P, Q = _ВЕРШИНЫ[i], _ВЕРШИНЫ[(i + 1) % 4]      # сторона PQ
    цель = _имя_15(P, K, Q, точка=K)                  # треугольник, о котором речь

    # ── Чертёж: AD внизу, BC сверху; наклон в любую сторону ──────────────
    w, h = 5.2, 3.8
    s = rng.choice([1.4, 1.5, 1.6]) * rng.choice([1, -1])
    т = {'A': (0.0, 0.0), 'D': (w, 0.0), 'B': (s, h), 'C': (s + w, h)}
    тK = пересечение(т['A'], т['C'], т['B'], т['D'])

    # Из какой вершины треугольника вести медиану и высоту. Кандидатов два
    # (из P к диагонали через Q, из Q к диагонали через P); берём тот,
    # у которого основание высоты дальше от концов диагонали и от штрихов
    # равенства на её половинках — иначе на чертеже всё слипается.
    лучший = None
    for В, С in ((P, Q), (Q, P)):
        Д = _ПРОТИВ[С]                              # диагональ СД, В — вне её
        тH = проекция(т[С], т[Д], т[В])
        t = _параметр(т[С], т[Д], тH)
        оценка = min(t, 1 - t, 2 * abs(t - 0.25), 2 * abs(t - 0.75))
        if лучший is None or оценка > лучший[0]:
            лучший = (оценка, В, С, Д, тH)
    _, В, С, Д, тH = лучший
    Ч = _ПРОТИВ[В]                                  # четвёртая вершина

    диаг = _имя_15(С, Д)                               # диагональ, на которой K — середина
    другая = _имя_15(В, Ч)
    большой = _имя_15(В, С, Д)                         # половина параллелограмма
    второй = _имя_15(Ч, С, Д)                          # другая половина
    близнец = _имя_15(В, K, Д, точка=K)                # второй кусок от медианы
    медиана = В + K
    высота = В + 'H'

    # ── Условие ───────────────────────────────────────────────────────────
    условие = rng.choice([
        '<p>В параллелограмме \\(ABCD\\) диагонали пересекаются в точке \\(%(K)s\\). '
        'Докажите, что площадь треугольника \\(%(цель)s\\) в четыре раза меньше '
        'площади параллелограмма.</p>',
        '<p>Пусть \\(%(K)s\\) — точка пересечения диагоналей параллелограмма '
        '\\(ABCD\\). Докажите, что \\(S_{ABCD} = 4\\,S_{%(цель)s}\\).</p>',
        '<p>В параллелограмме \\(ABCD\\) проведены диагонали, \\(%(K)s\\) — точка их '
        'пересечения. Докажите, что площадь треугольника \\(%(цель)s\\) составляет '
        'четверть площади параллелограмма.</p>',
    ]) % {'K': K, 'цель': цель}

    # ── Доказательство ────────────────────────────────────────────────────
    буквы = {
        'K': K, 'В': В, 'С': С, 'Д': Д, 'Ч': Ч,
        'цель': цель, 'близнец': близнец, 'большой': большой, 'второй': второй,
        'диаг': диаг, 'другая': другая, 'медиана': медиана, 'высота': высота,
        'СK': С + K, 'KД': K + Д, 'ВK': В + K, 'KЧ': K + Ч,
        # пары противоположных сторон: ВС = ЧД и ВД = ЧС
        'ВС': _имя_15(В, С), 'ЧД': _имя_15(Ч, Д), 'ВД': _имя_15(В, Д), 'ЧС': _имя_15(Ч, С),
    }
    доказательство = (
        '<p>1. Диагонали параллелограмма точкой пересечения делятся пополам, '
        'поэтому \\(%(СK)s = %(KД)s\\) и \\(%(ВK)s = %(KЧ)s\\).</p>'

        '<p>2. Диагональ \\(%(диаг)s\\) разбивает параллелограмм на треугольники '
        '\\(%(большой)s\\) и \\(%(второй)s\\). Сторона \\(%(диаг)s\\) у них общая, а '
        '\\(%(ВС)s = %(ЧД)s\\) и \\(%(ВД)s = %(ЧС)s\\) как противоположные стороны '
        'параллелограмма. Значит, треугольники равны по трём сторонам, а равные '
        'треугольники имеют равные площади. Вместе эти два треугольника составляют '
        'весь параллелограмм, поэтому</p>'
        '\\[S_{%(большой)s} = S_{%(второй)s} = \\tfrac12\\,S_{ABCD}.\\]'

        '<p>3. В треугольнике \\(%(большой)s\\) точка \\(%(K)s\\) — середина стороны '
        '\\(%(диаг)s\\) (шаг 1), поэтому \\(%(медиана)s\\) — медиана. Она разбивает '
        'треугольник \\(%(большой)s\\) на треугольники \\(%(цель)s\\) и \\(%(близнец)s\\). '
        'Проведём высоту \\(%(высота)s\\) треугольника \\(%(большой)s\\) к стороне '
        '\\(%(диаг)s\\) (на чертеже — пунктиром, \\(%(высота)s \\perp %(диаг)s\\)). '
        'Основания \\(%(СK)s\\) и \\(%(KД)s\\) треугольников \\(%(цель)s\\) и '
        '\\(%(близнец)s\\) лежат на одной прямой \\(%(диаг)s\\), значит, \\(%(высота)s\\) '
        '— высота каждого из них. По формуле площади треугольника</p>'
        '\\[S_{%(цель)s} = \\tfrac12\\,%(СK)s \\cdot %(высота)s, \\qquad '
        'S_{%(близнец)s} = \\tfrac12\\,%(KД)s \\cdot %(высота)s,\\]'
        '<p>а так как \\(%(СK)s = %(KД)s\\), то \\(S_{%(цель)s} = S_{%(близнец)s}\\). '
        'Сумма этих площадей равна \\(S_{%(большой)s}\\), откуда '
        '\\(S_{%(цель)s} = \\tfrac12\\,S_{%(большой)s}\\).</p>'

        '<p>4. Соединяем шаги 2 и 3:</p>'
        '\\[S_{%(цель)s} = \\tfrac12\\,S_{%(большой)s} = '
        '\\tfrac12 \\cdot \\tfrac12\\,S_{ABCD} = \\tfrac14\\,S_{ABCD},\\]'
        '<p>то есть \\(S_{ABCD} = 4\\,S_{%(цель)s}\\), что и требовалось доказать.</p>'
    ) % буквы

    # ── Чертёж ────────────────────────────────────────────────────────────
    A, B, C, D = т['A'], т['B'], т['C'], т['D']
    ч = Чертёж()
    # Контур без заливки, залит только треугольник из условия — глаз сразу
    # видит, о какой четверти речь.
    ч.многоугольник([A, B, C, D], залить=False)
    ч.многоугольник([т[P], тK, т[Q]])
    ч.отрезок(A, C)
    ч.отрезок(B, D)
    # Высота — вспомогательное построение: серым пунктиром, с квадратиком
    # прямого угла в сторону того конца диагонали, который дальше от H.
    ч.отрезок(т[В], тH, пунктир=True, вспомогательный=True)
    дальний = т[Д] if _параметр(т[С], т[Д], тH) < 0.5 else т[С]
    ч.прямой_угол(тH, т[В], дальний, размер=0.3)
    # Половинки одной диагонали — одним штрихом, другой — двумя.
    ч.равенство(A, тK, 1)
    ч.равенство(тK, C, 1)
    ч.равенство(B, тK, 2)
    ч.равенство(тK, D, 2)

    # Подпись K — в сектор, противоположный треугольнику из условия, вдоль
    # биссектрисы этого сектора: там нет ни заливки, ни высоты.
    единичные = []
    for X in (Ч, Д):
        dx, dy = т[X][0] - тK[0], т[X][1] - тK[1]
        L = math.hypot(dx, dy)
        единичные.append((dx / L, dy / L))
    бx, бy = (единичные[0][0] + единичные[1][0], единичные[0][1] + единичные[1][1])
    Lб = math.hypot(бx, бy)
    сторона_K = _куда(бx, бy)
    # Сектор между диагоналями узкий (около 75°), а сторон света всего
    # восемь: подпись у самой точки задевает диагональ. Поэтому якорь
    # подписи отодвигаем от K на 0.17 единицы вдоль биссектрисы (точку при
    # этом ставим на месте).
    якорь_K = (тK[0] + 0.17 * бx / Lб, тK[1] + 0.17 * бy / Lб)
    # Подпись H — по ту сторону диагонали от вершины, из которой опущена
    # высота, и со сдвигом вдоль диагонали к ближнему её концу: иначе она
    # встаёт вплотную к подписи K, ведь H и K соседствуют на одной прямой.
    ближний = т[С] if дальний is т[Д] else т[Д]
    перп = (тH[0] - т[В][0], тH[1] - т[В][1])
    вдоль = (ближний[0] - тH[0], ближний[1] - тH[1])
    Lп, Lв = math.hypot(*перп), math.hypot(*вдоль)
    сторона_H = _куда(перп[0] / Lп + вдоль[0] / Lв, перп[1] / Lп + вдоль[1] / Lв)

    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'), (тH, 'H', сторона_H))
    ч.точка(тK)
    ч.подпись(якорь_K, K, сторона_K)

    return {
        'title': 'Диагонали параллелограмма: треугольник при стороне — четверть площади',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Диагонали параллелограмма точкой пересечения делятся пополам; '
            'противоположные стороны параллелограмма равны.',
            'Третий признак равенства треугольников (по трём сторонам); равные '
            'треугольники имеют равные площади.',
            'Площадь треугольника равна половине произведения стороны на '
            'проведённую к ней высоту; отсюда медиана делит треугольник на два '
            'равновеликих.',
            'Площадь фигуры равна сумме площадей частей, на которые она разбита.',
        ],
        'params': {
            'точка': K, 'треугольник': цель, 'сторона': _имя_15(P, Q),
            'диагональ': диаг, 'медиана': медиана, 'высота': высота,
            'коэффициент': 4, 'наклон': s,
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 16. Параллелограмм: середина стороны равноудалена от концов
# ────────────────────────────────────────────────────────────────────────
#
# противоположной стороны — параллелограмм оказывается прямоугольником.
#
# Конфигурация. Параллелограмм ABCD, M — середина стороны AB, и известно, что
# MC = MD. Доказать, что ABCD — прямоугольник. У задачи есть зеркальная
# посадка (M — середина CD и MA = MB); rng выбирает одну из двух, условие,
# доказательство и чертёж строятся по выбранной.
#
# Ключевой ход. Отрезки MC и MD отрезают от параллелограмма два «крайних»
# треугольника AMD и BMC. Они равны по трём сторонам: AM = MB (середина),
# AD = BC (противоположные стороны параллелограмма), MD = MC (условие). Из
# равенства треугольников ∠A = ∠B. А углы параллелограмма при одной стороне
# в сумме дают 180°, значит, каждый из них прямой. Параллелограмм с прямыми
# углами — прямоугольник.
#
# Почему работает. Само по себе MC = MD говорит лишь, что M лежит на
# серединном перпендикуляре к CD. Параллелограмм добавляет к этому AD = BC,
# а середина — AM = MB; вместе это ровно три пары сторон для третьего
# признака. Равенство ∠A = ∠B ещё не прямоугольник (у любого
# параллелограмма ∠A = ∠C), решает именно сумма односторонних углов: два
# равных угла с суммой 180° — прямые.
#
# Ловушки.
#   * Соответствие вершин в равных треугольниках: A ↔ B, M ↔ M, D ↔ C.
#     Нужны углы, лежащие против MD и MC, — это ∠MAD и ∠MBC. Углы при
#     вершине M (∠AMD = ∠BMC) тоже равны, но к прямоугольнику не ведут.
#   * Из ∠A = ∠B нельзя сразу писать «значит, по 90°»: обязателен шаг про
#     сумму углов при стороне AB — односторонние углы при AD ∥ BC и
#     секущей AB.
#   * Финал должен опираться на определение прямоугольника, а не на слово
#     «очевидно»: все четыре угла прямые (через равенство противоположных
#     углов параллелограмма).
#   * Чертёж. Честный чертёж по условию — уже прямоугольник: если вершину B
#     сдвинуть вдоль AD на s, то MC² − MD² = 2·AD·s ≠ 0, и равенства MC = MD
#     нет. Рисовать наклонный параллелограмм с пометкой MC = MD значит
#     рисовать неравные отрезки как равные. Поэтому чертёж прямоугольный,
#     но прямые углы на нём не отмечены — они заключение, а не данное;
#     отмечены три пары равных отрезков и равные углы при A и B, которые
#     даёт шаг с равными треугольниками.
#   * Сборник решает иначе: отрезок из M в середину CD параллелен BC и
#     одновременно является медианой равнобедренного треугольника MCD, то
#     есть его высотой; отсюда BC ⊥ CD. Путь верный и упомянут в замечании
#     после доказательства, но требует дополнительной точки и обоснования
#     параллельности; равенство треугольников короче и не выходит за
#     признаки равенства и свойства параллелограмма.


# Две посадки одной задачи. X, Y — концы стороны, на которой лежит M;
# W — вершина, соседняя с X, Z — соседняя с Y (обход A→B→C→D сохраняется,
# поэтому XW и YZ — противоположные стороны параллелограмма).
_ПОСАДКИ = {
    'AB': dict(X='A', Y='B', W='D', Z='C'),
    'CD': dict(X='C', Y='D', W='B', Z='A'),
}


def _отрезок(p, q):
    """Имя отрезка в привычном порядке: M впереди, вершины — по алфавиту
    (AD, а не DA; MC, а не CM)."""
    if 'M' in (p, q):
        return 'M' + (q if p == 'M' else p)
    return ''.join(sorted((p, q)))


def _угол_16(a, v, b):
    """Имя угла с вершиной v; концы — по алфавиту (BAD, а не DAB)."""
    return min(a, b) + v + max(a, b)


@сюжет(16)
def _сюжет_16(rng):
    посадка = rng.choice(['AB', 'CD'])
    б = dict(_ПОСАДКИ[посадка])            # буквы для подстановки в текст
    X, Y, Z, W = б['X'], б['Y'], б['Z'], б['W']
    б.update(
        XY=X + Y,
        XW=_отрезок(X, W), YZ=_отрезок(Y, Z),      # противоположные стороны
        ZW=_отрезок(Z, W),                         # сторона напротив M
        MW=_отрезок('M', W), MZ=_отрезок('M', Z),  # равные по условию
        XMW=X + 'M' + W, YMZ=Y + 'M' + Z,          # равные треугольники
        ZMW=Z + 'M' + W,                           # равнобедренный треугольник
        уголX=_угол_16(Y, X, W), уголY=_угол_16(X, Y, Z),
    )

    # Чисел в сюжете нет; кроме посадки rng меняет только способ сказать
    # «MC = MD»: равенством отрезков или словами про равноудалённость.
    формулировка = rng.randint(1, 2)
    if формулировка == 1:
        условие = (
            '<p>Точка \\(M\\) — середина стороны \\(%(XY)s\\) параллелограмма '
            '\\(ABCD\\), причём \\(%(MZ)s = %(MW)s\\). Докажите, что '
            '\\(ABCD\\) — прямоугольник.</p>' % б)
    else:
        условие = (
            '<p>В параллелограмме \\(ABCD\\) середина \\(M\\) стороны '
            '\\(%(XY)s\\) одинаково удалена от вершин \\(%(Z)s\\) и \\(%(W)s\\). '
            'Докажите, что этот параллелограмм — прямоугольник.</p>' % б)

    доказательство = (
        '<p>1. Точка \\(M\\) — середина стороны \\(%(XY)s\\), поэтому '
        '\\(%(X)sM = M%(Y)s\\).</p>'
        '<p>2. \\(%(XW)s = %(YZ)s\\) как противоположные стороны параллелограмма '
        '\\(ABCD\\).</p>'
        '<p>3. Рассмотрим треугольники \\(%(XMW)s\\) и \\(%(YMZ)s\\). В них '
        '\\(%(X)sM = %(Y)sM\\) по шагу 1, \\(%(XW)s = %(YZ)s\\) по шагу 2 и '
        '\\(%(MW)s = %(MZ)s\\) по условию. Три стороны одного треугольника '
        'соответственно равны трём сторонам другого, значит, '
        '\\(\\triangle %(XMW)s = \\triangle %(YMZ)s\\) по третьему признаку '
        'равенства треугольников.</p>'
        '<p>4. В равных треугольниках против равных сторон лежат равные углы. '
        'В треугольнике \\(%(XMW)s\\) против стороны \\(%(MW)s\\) лежит угол '
        '\\(M%(X)s%(W)s\\), в треугольнике \\(%(YMZ)s\\) против равной ей стороны '
        '\\(%(MZ)s\\) — угол \\(M%(Y)s%(Z)s\\). Поэтому</p>'
        '\\[\\angle M%(X)s%(W)s = \\angle M%(Y)s%(Z)s.\\]'
        '<p>Точка \\(M\\) лежит на стороне \\(%(XY)s\\), так что луч \\(%(X)sM\\) — '
        'это луч \\(%(X)s%(Y)s\\), а луч \\(%(Y)sM\\) — луч \\(%(Y)s%(X)s\\). '
        'Значит, \\(\\angle M%(X)s%(W)s\\) — это угол \\(%(уголX)s\\) '
        'параллелограмма, а \\(\\angle M%(Y)s%(Z)s\\) — его угол \\(%(уголY)s\\). '
        'Получаем \\(\\angle %(X)s = \\angle %(Y)s\\).</p>'
        '<p>5. По определению параллелограмма \\(%(XW)s \\parallel %(YZ)s\\), '
        'а прямая \\(%(XY)s\\) — секущая. Углы \\(%(X)s\\) и \\(%(Y)s\\) — '
        'односторонние при этих параллельных прямых и секущей, поэтому '
        '\\(\\angle %(X)s + \\angle %(Y)s = 180^\\circ\\). Вместе с равенством '
        '\\(\\angle %(X)s = \\angle %(Y)s\\) это даёт '
        '\\(2\\angle %(X)s = 180^\\circ\\), откуда '
        '\\(\\angle %(X)s = \\angle %(Y)s = 90^\\circ\\).</p>'
        '<p>6. Противоположные углы параллелограмма равны: '
        '\\(\\angle %(Z)s = \\angle %(X)s = 90^\\circ\\) и '
        '\\(\\angle %(W)s = \\angle %(Y)s = 90^\\circ\\). Все четыре угла '
        'параллелограмма \\(ABCD\\) прямые, а параллелограмм, у которого все '
        'углы прямые, — это прямоугольник по определению. Итак, \\(ABCD\\) — '
        'прямоугольник, что и требовалось доказать.</p>'
        '<p><i>Замечание.</i> К тому же выводу ведёт и другой путь: соединим '
        '\\(M\\) с серединой стороны \\(%(ZW)s\\). Половины сторон \\(%(XY)s\\) '
        'и \\(%(ZW)s\\), прилегающие к вершинам \\(%(Y)s\\) и \\(%(Z)s\\), равны '
        'и параллельны, поэтому вместе со стороной \\(%(YZ)s\\) и проведённым '
        'отрезком они образуют параллелограмм, и этот отрезок параллелен '
        '\\(%(YZ)s\\). В то же время он — медиана равнобедренного треугольника '
        '\\(%(ZMW)s\\), проведённая к основанию \\(%(ZW)s\\), а значит, и его '
        'высота. Отсюда \\(%(ZW)s \\perp %(YZ)s\\), то есть угол при вершине '
        '\\(%(Z)s\\) прямой.</p>' % б)

    # Чертёж. Честный чертёж по условию — прямоугольник (см. докстринг),
    # поэтому вершины ставим в углы прямоугольника a × h; rng меняет только
    # его пропорции. Сторону с точкой M кладём горизонтально (AB — низ,
    # CD — верх): в обеих посадках отрезки из M идут к противоположной
    # стороне, и равнобедренный треугольник ZMW стоит на своём основании.
    a = rng.choice([6.5, 7.0, 7.5])
    h = 4.0
    т = {'A': (0.0, 0.0), 'B': (a, 0.0), 'C': (a, h), 'D': (0.0, h)}
    M = середина(т[X], т[Y])
    ч = Чертёж()
    ч.многоугольник([т['A'], т['B'], т['C'], т['D']])
    ч.отрезок(M, т[Z])
    ч.отрезок(M, т[W])
    # Три пары равных сторон — три вида штрихов: половины стороны XY,
    # отрезки из M, противоположные стороны XW и YZ.
    ч.равенство(т[X], M, 1)
    ч.равенство(M, т[Y], 1)
    ч.равенство(M, т[Z], 2)
    ч.равенство(M, т[W], 2)
    ч.равенство(т[X], т[W], 3)
    ч.равенство(т[Y], т[Z], 3)
    # Равные углы при X и Y — вывод шага 4. Квадратики прямых углов не
    # ставим: прямые углы — заключение задачи, а не её данные.
    ч.дуга_угла(т[X], M, т[W], радиус=0.6)
    ч.дуга_угла(т[Y], M, т[Z], радиус=0.6)
    подписать_вершины(ч, (т['A'], 'A', 'юз'), (т['B'], 'B', 'юв'),
                      (т['C'], 'C', 'св'), (т['D'], 'D', 'сз'),
                      (M, 'M', 'ю' if посадка == 'AB' else 'с'))

    return {
        'title': 'Параллелограмм: середина стороны равноудалена от концов '
                 'противоположной стороны — прямоугольник',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Противоположные стороны параллелограмма равны и параллельны, '
            'противоположные углы равны.',
            'Углы параллелограмма при одной стороне — односторонние при '
            'параллельных прямых и секущей, их сумма равна \\(180^\\circ\\).',
            'Третий признак равенства треугольников (по трём сторонам); '
            'в равных треугольниках против равных сторон лежат равные углы.',
            'Прямоугольник — это параллелограмм, у которого все углы прямые.',
        ],
        'params': {
            'сторона_с_M': посадка,
            'равные_отрезки': (б['MZ'], б['MW']),
            'формулировка': формулировка,
            'a': a, 'h': h,
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 17. Параллелограмм с равными высотами из одной вершины — ромб.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация. Параллелограмм ABCD. Из одной вершины опущены две высоты на
# две стороны, которые этой вершине не принадлежат: в редакции банка — из B
# на AD (основание H) и на CD (основание E). Дано BH = BE, доказать, что ABCD
# — ромб. Чисел в условии нет и быть не может: равенство высот — единственное
# данное, и оно уже жёстко определяет форму (все стороны равны), а любая
# цифра (сторона, угол) была бы лишней.
#
# Ключевой ход — двойной подсчёт площади. Площадь параллелограмма равна
# произведению стороны на высоту к ней, и её можно посчитать через любую из
# двух сторон: S = AD·BH = CD·BE. Раз высоты равны, равны и стороны: AD = CD.
# Дальше работает свойство параллелограмма (противоположные стороны равны):
# BC = AD и AB = CD, то есть все четыре стороны одинаковы — это и есть ромб
# по определению.
#
# Почему именно площадь, а не равные треугольники. Напрашивается второй путь:
# прямоугольные треугольники ABH и CBE равны по катету (BH = BE) и острому
# углу (∠A = ∠C как противоположные углы параллелограмма), откуда AB = CB.
# Он верен, но с оговоркой: если угол A тупой, основания высот падают не на
# стороны, а на их продолжения (H — за точку A, E — за точку C), и равными
# оказываются уже не углы A и C, а смежные с ними. Ученик, который нарисовал
# острый угол при A и написал «∠BAH = ∠BCE как углы параллелограмма», прав
# только для своего чертежа. При прямом угле A треугольников нет вовсе:
# H = A, E = C, и AB = BH = BE = BC получается без всякого признака
# равенства. Площадной путь свободен от разбора случаев:
# формула S = a·h верна независимо от того, куда попало основание высоты.
#
# Ловушки при написании.
# * Остановиться на AD = CD. Равенство двух смежных сторон — ещё не
#   определение ромба (у Атанасяна ромб — параллелограмм, у которого все
#   стороны равны); нужно дописать шаг про противоположные стороны, либо явно
#   сослаться на признак «параллелограмм с равными смежными сторонами — ромб».
# * Написать «S = AD·BH» без слов, почему BH — высота к AD: эксперт ждёт
#   ссылку на BH ⟂ AD из условия и на формулу площади параллелограмма.
# * Делить на BH, не сказав, что это не нуль. Формально высота невырожденного
#   параллелограмма положительна — одной фразы достаточно.
# * Чертёж. Раз BH = BE, фигура на картинке обязана быть ромбом; рисовать
#   «общий» параллелограмм с якобы равными высотами нельзя — он будет лгать.
#   Но и квадрат рисовать нельзя (тогда высоты сольются со сторонами): угол
#   при A берём острый, 63–71°, чтобы основания высот лежали внутри сторон и
#   не попадали в их середины (при 60° E — ровно середина CD, это сбивает).
#
# Вариативность: вершина, из которой опущены высоты (B — редакция банка, D —
# центрально-симметричный вариант с высотами на AB и BC), буквы оснований
# высот (H, E либо H, K), три редакции формулировки и острый угол чертежа.
# Доказательство и чертёж собираются из одних и тех же имён сторон, поэтому
# рассинхрона между текстом и картинкой быть не может.


@сюжет(17)
def _сюжет_17(rng):
    # Из какой вершины опущены высоты. В банке — из B на AD и CD; вариант из
    # D на AB и BC — та же задача, повёрнутая на 180° вокруг центра. Второй
    # даём реже, чтобы основная посадка совпадала с тем, что ученик увидит
    # на экзамене, но не сложилось впечатление «высоты всегда из B».
    из_B = rng.random() < 0.7
    # Буквы оснований высот: H и E — как в банке; H и K — вторая ходовая пара.
    осн1, осн2 = rng.choice([('H', 'E'), ('H', 'E'), ('H', 'K')])

    if из_B:
        и = {
            'V': 'B',                 # вершина, из которой опущены высоты
            'с1': 'AD', 'с2': 'CD',   # стороны, на которые они опущены
            'п1': 'BC', 'п2': 'AB',   # противоположные им стороны
        }
    else:
        и = {
            'V': 'D',
            'с1': 'AB', 'с2': 'BC',
            'п1': 'CD', 'п2': 'AD',
        }
    и['h1'] = и['V'] + осн1          # первая высота, например BH
    и['h2'] = и['V'] + осн2          # вторая высота, например BE
    и['о1'], и['о2'] = осн1, осн2
    # Прямоугольные треугольники для замечания об альтернативном пути:
    # первая высота отсекает треугольник при вершине A, вторая — при C.
    и['т1'] = 'A' + и['V'] + осн1    # например ABH
    и['т2'] = 'C' + и['V'] + осн2    # например CBE
    и['г1'] = 'A' + и['V']           # его гипотенуза AB
    и['г2'] = 'C' + и['V']           # и CB

    формулировки = [
        '<p>Высоты \\(%(h1)s\\) и \\(%(h2)s\\) параллелограмма \\(ABCD\\), '
        'проведённые к сторонам \\(%(с1)s\\) и \\(%(с2)s\\) соответственно, '
        'равны. Докажите, что \\(ABCD\\) — ромб.</p>',

        '<p>В параллелограмме \\(ABCD\\) из вершины \\(%(V)s\\) опущены '
        'высоты \\(%(h1)s\\) на сторону \\(%(с1)s\\) и \\(%(h2)s\\) на сторону '
        '\\(%(с2)s\\), причём \\(%(h1)s = %(h2)s\\). Докажите, что '
        'параллелограмм \\(ABCD\\) — ромб.</p>',

        '<p>Точки \\(%(о1)s\\) и \\(%(о2)s\\) — основания перпендикуляров, '
        'опущенных из вершины \\(%(V)s\\) параллелограмма \\(ABCD\\) на '
        'стороны \\(%(с1)s\\) и \\(%(с2)s\\) соответственно. Известно, что '
        '\\(%(h1)s = %(h2)s\\). Докажите, что \\(ABCD\\) — ромб.</p>',
    ]
    номер_формулировки = rng.randrange(len(формулировки))
    условие = формулировки[номер_формулировки] % и

    доказательство = (
        '<p>1. Обозначим площадь параллелограмма \\(ABCD\\) через \\(S\\). '
        'Площадь параллелограмма равна произведению стороны на высоту, '
        'проведённую к этой стороне. Отрезок \\(%(h1)s\\) — высота к стороне '
        '\\(%(с1)s\\) (по условию \\(%(h1)s \\perp %(с1)s\\)), поэтому '
        '\\(S = %(с1)s \\cdot %(h1)s\\). Отрезок \\(%(h2)s\\) — высота к стороне '
        '\\(%(с2)s\\) (\\(%(h2)s \\perp %(с2)s\\)), поэтому '
        '\\(S = %(с2)s \\cdot %(h2)s\\).</p>'

        '<p>2. Оба произведения равны одному и тому же числу \\(S\\), значит, '
        'равны между собой:</p>'
        '\\[%(с1)s \\cdot %(h1)s = %(с2)s \\cdot %(h2)s.\\]'
        '<p>По условию \\(%(h1)s = %(h2)s\\). Это число положительно: высота '
        'невырожденного параллелограмма не может быть нулевой. Разделим левую '
        'часть равенства на \\(%(h1)s\\), а правую — на равное ему \\(%(h2)s\\), '
        'и получим \\(%(с1)s = %(с2)s\\).</p>'

        '<p>3. Противоположные стороны параллелограмма равны: '
        '\\(%(п1)s = %(с1)s\\) и \\(%(п2)s = %(с2)s\\). Вместе с равенством '
        '\\(%(с1)s = %(с2)s\\) из шага 2 это даёт</p>'
        '\\[AB = BC = CD = DA.\\]'

        '<p>4. Параллелограмм, у которого все стороны равны, по определению '
        'является ромбом. Следовательно, \\(ABCD\\) — ромб, что и требовалось '
        'доказать.</p>'

        '<p><i>Замечание.</i> К тому же выводу ведёт равенство прямоугольных '
        'треугольников \\(%(т1)s\\) и \\(%(т2)s\\): у них равны катеты '
        '\\(%(h1)s = %(h2)s\\) и острые углы при вершинах \\(A\\) и \\(C\\) '
        '(противоположные углы параллелограмма), откуда по катету и острому '
        'углу \\(%(г1)s = %(г2)s\\). Но здесь нужно отдельно следить, куда '
        'попадают основания высот: если угол \\(A\\) тупой, они лежат на '
        'продолжениях сторон, и острыми углами треугольников служат уже не '
        'сами углы \\(A\\) и \\(C\\), а смежные с ними (они тоже равны между '
        'собой); если угол \\(A\\) прямой, треугольников '
        'нет вовсе (\\(%(о1)s\\) совпадает с \\(A\\), \\(%(о2)s\\) — с \\(C\\), '
        'и \\(%(г1)s = %(h1)s = %(h2)s = %(г2)s\\) сразу). Подсчёт площади от '
        'разбора случаев свободен: формула \\(S = a \\cdot h\\) верна при любом '
        'положении основания высоты.</p>'
    ) % и

    # ── Чертёж ──────────────────────────────────────────────────────────
    # Раз высоты равны, фигура и есть ромб — рисуем честный ромб, иначе
    # картинка спорила бы с условием. Острый угол при A берём в 63–71°: при
    # 60° основание высоты попадает ровно в середину стороны (лишняя
    # «закономерность», которой в задаче нет), ближе к 90° ромб становится
    # квадратом и высоты сливаются со сторонами. A — слева внизу, AD —
    # нижняя сторона, как принято в учебнике.
    α = math.radians(rng.choice([63, 67, 71]))
    a = 5.0
    A = (0.0, 0.0)
    D = (a, 0.0)
    B = (a * math.cos(α), a * math.sin(α))
    C = (B[0] + a, B[1])

    ч = Чертёж()
    ч.многоугольник([A, B, C, D])

    if из_B:
        # Высоты из B: на нижнюю сторону AD и на правую сторону CD. При остром
        # угле A оба основания лежат внутри сторон (AH = CE = a·cos α < a).
        H = проекция(A, D, B)
        E = проекция(C, D, B)
        ч.отрезок(B, H)
        ч.отрезок(B, E)
        # Квадратики прямых углов — внутрь ромба: при H между HB и HD, при E
        # между EB и ED.
        ч.прямой_угол(H, B, D, размер=0.32)
        ч.прямой_угол(E, B, D, размер=0.32)
        подписать_вершины(ч, (H, осн1, 'ю'), (E, осн2, 'в'))
    else:
        # Высоты из D: на левую сторону AB и на верхнюю сторону BC — та же
        # картинка, повёрнутая на 180° вокруг центра параллелограмма.
        H = проекция(A, B, D)
        E = проекция(B, C, D)
        ч.отрезок(D, H)
        ч.отрезок(D, E)
        ч.прямой_угол(H, D, B, размер=0.32)
        ч.прямой_угол(E, D, B, размер=0.32)
        подписать_вершины(ч, (H, осн1, 'з'), (E, осн2, 'с'))

    # Штрихи равенства — только на высотах: это дано. Стороны не помечаем,
    # их равенство как раз доказывается.
    вершина = B if из_B else D
    ч.равенство(вершина, H)
    ч.равенство(вершина, E)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'), (D, 'D', 'юв'))

    return {
        'title': 'Параллелограмм с равными высотами к смежным сторонам — ромб',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Площадь параллелограмма равна произведению стороны на высоту, '
            'проведённую к этой стороне.',
            'Противоположные стороны параллелограмма равны.',
            'Ромб — параллелограмм, у которого все стороны равны.',
        ],
        'params': {
            'вершина': и['V'],
            'высоты': (и['h1'], и['h2']),
            'стороны': (и['с1'], и['с2']),
            'формулировка': номер_формулировки,
            'угол_A_градусы': round(math.degrees(α)),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 18. Две высоты остроугольного треугольника: углы при основаниях
# ────────────────────────────────────────────────────────────────────────
#
# высот равны.
#
# Конфигурация. Остроугольный треугольник ABC, из двух его вершин опущены
# высоты. Назовём эти вершины X и Y, третью — Z; основания высот X₁ ∈ YZ и
# Y₁ ∈ XZ. Требуется доказать ∠XX₁Y₁ = ∠XYY₁: угол между высотой из X и
# отрезком X₁Y₁ равен углу, под которым из вершины Y видна высота YY₁. Чисел
# в сюжете нет и быть не может — утверждение чисто угловое и не меняется при
# подобии; единственная скрытая величина — оба угла равны 90° − ∠X.
#
# Ключевой ход — увидеть окружность, которой нет на чертеже. Из точек X₁ и Y₁
# отрезок XY виден под прямым углом (это и есть определение высоты), значит,
# обе они лежат на окружности с диаметром XY. Строже: в прямоугольном
# треугольнике XX₁Y медиана X₁O к гипотенузе равна её половине, то есть
# X₁O = OX = OY, и точка X₁ лежит на окружности с центром O и радиусом OX;
# то же для Y₁. Четыре точки X, Y, X₁, Y₁ оказываются на одной окружности,
# а ∠XX₁Y₁ и ∠XYY₁ — вписанные углы, опирающиеся на одну хорду XY₁ с одной
# стороны, потому они равны.
#
# Почему это работает. Прямой угол — самый удобный признак вписанности: два
# прямых угла на общий отрезок сразу дают окружность с известным центром
# (середина отрезка) и радиусом. После этого равенство углов, разнесённых по
# разным треугольникам, превращается в равенство двух вписанных углов на
# одну дугу — это уже теорема, а не рассуждение.
#
# Ловушки.
# 1. Слово «остроугольный» выбросить нельзя. При ∠Z = 90° основания обеих
#    высот совпадают с Z, и отрезка X₁Y₁ нет. При тупом ∠Z точки X₁, Y₁ уходят
#    на продолжения сторон за вершину Z, четыре точки по-прежнему лежат на
#    окружности с диаметром XY, но вершины X₁ и Y попадают по разные стороны
#    от хорды XY₁, и углы становятся не равными, а дополняющими друг друга до
#    180° (числовая проверка: A(0;0), B(4;0), C(0,5;0,5) даёт 135° и 45°).
#    Поэтому первый шаг доказательства — обосновать, что основания высот лежат
#    на самих сторонах; без него нельзя сказать, на какую дугу опираются углы.
# 2. На какую хорду опираются углы. Ученики пишут «опираются на дугу XY» — но
#    XY здесь диаметр, и углы на него прямые. Углы ∠XX₁Y₁ и ∠XYY₁ опираются на
#    хорду XY₁; симметричная пара ∠YY₁X₁ = ∠YXX₁ (второй подтип банка) — на
#    хорду YX₁.
# 3. Направление теоремы. «Вписанный угол, опирающийся на диаметр, прямой» —
#    это не то, что нужно: нужна обратная теорема (угол прямой ⇒ вершина на
#    окружности с диаметром — его сторонами). Эксперт замечает подмену, поэтому
#    в доказательстве факт выводится честно, через медиану к гипотенузе.
# 4. Решение без окружности тоже существует: △ZX₁Y₁ ~ △ZXY с коэффициентом
#    cos Z (общий угол Z, ZX₁ = ZX·cos Z, ZY₁ = ZY·cos Z), откуда ∠ZX₁Y₁ = ∠X и
#    ∠XX₁Y₁ = 90° − ∠X, а ∠XYY₁ = 90° − ∠X из прямоугольного треугольника XYY₁.
#    Оно короче записывается, но опирается на косинус, которого в курсе 8 класса
#    для доказательств лучше избегать; здесь оставлено как замечание о величине.
#
# Варьируется буквенная разметка: упорядоченная пара (X, Y) из вершин A, B, C —
# шесть вариантов, ровно столько подтипов в банке (какие две высоты проведены и
# какая из двух симметричных пар углов доказывается), — и формулировка условия.
# Чертёж: A слева внизу, B справа внизу, C сверху; форма треугольника случайна
# в пределах, при которых все углы держатся в промежутке примерно 43°–76°.


# Стороны подписи по кругу от направления «восток» против часовой стрелки —
# так же, как растут углы atan2 в мировых координатах (ось y вверх).
_ПО_КРУГУ = ['в', 'св', 'с', 'сз', 'з', 'юз', 'ю', 'юв']


def _наружу(p, центр):
    """Сторона подписи точки p «от центра»: буква уходит за пределы фигуры."""
    угол = degrees(atan2(p[1] - центр[1], p[0] - центр[0]))
    return _ПО_КРУГУ[int(round(угол / 45.0)) % 8]


def _ед(v):
    d = hypot(v[0], v[1]) or 1.0
    return (v[0] / d, v[1] / d)


def _сторона_основания(P, концы, прочие, O, центр):
    """Сторона подписи основания высоты P.

    Точка P лежит сразу и на стороне треугольника (концы — её вершины), и на
    вспомогательной окружности с центром O, поэтому простого «наружу от
    центра тяжести» мало: когда основание близко к вершине, буква ложится на
    дугу окружности. Из восьми направлений, смотрящих наружу треугольника,
    берём то, что дальше всего по углу от всех линий, выходящих из P: стороны
    в обе стороны, касательной к окружности в обе стороны и внутренних
    отрезков (высоты, отрезка оснований, медианы к центру).
    """
    лучи = [_ед((Q[0] - P[0], Q[1] - P[1])) for Q in tuple(концы) + tuple(прочие)]
    rx, ry = _ед((P[0] - O[0], P[1] - O[1]))
    лучи += [(-ry, rx), (ry, -rx)]           # касательная к окружности в P
    ux, uy = _ед((концы[1][0] - концы[0][0], концы[1][1] - концы[0][1]))
    nx, ny = -uy, ux                         # нормаль к стороне, наружу
    if nx * (P[0] - центр[0]) + ny * (P[1] - центр[1]) < 0:
        nx, ny = -nx, -ny
    лучшая, зазор = None, -1.0
    for i, сторона in enumerate(_ПО_КРУГУ):
        dx, dy = cos(radians(45 * i)), sin(radians(45 * i))
        if dx * nx + dy * ny < 0.1:          # только наружу треугольника
            continue
        мин = min(acos(max(-1.0, min(1.0, dx * lx + dy * ly))) for lx, ly in лучи)
        if мин > зазор:
            лучшая, зазор = сторона, мин
    return лучшая


def _величина_угла(V, P, Q):
    """Угол PVQ в градусах — для числовой проверки остроугольности."""
    ax, ay = P[0] - V[0], P[1] - V[1]
    bx, by = Q[0] - V[0], Q[1] - V[1]
    c = (ax * bx + ay * by) / (hypot(ax, ay) * hypot(bx, by))
    return degrees(acos(max(-1.0, min(1.0, c))))


def _отр_18(a, b):
    """Имя отрезка с буквами по алфавиту: AC, а не CA."""
    return ''.join(sorted((a, b)))


def _инд(буква):
    """Подпись вида A₁ для SVG: буква и нижний индекс через tspan."""
    return '%s<tspan font-size="9" dy="3">1</tspan>' % буква


@сюжет(18)
def _сюжет_18(rng):
    # Буквы. X и Y — вершины, из которых опущены высоты; Z — третья. Порядок
    # в паре существен: доказывается именно ∠XX₁Y₁ = ∠XYY₁ (хорда XY₁), а
    # при перестановке X и Y получается симметричная пара на хорде YX₁.
    X, Y, Z = rng.choice(['ABC', 'BAC', 'ACB', 'CAB', 'BCA', 'CBA'])
    б = {
        'X': X, 'Y': Y, 'Z': Z,
        'X1': X + '_1', 'Y1': Y + '_1',
        'XY': _отр_18(X, Y), 'XZ': _отр_18(X, Z), 'YZ': _отр_18(Y, Z),
    }

    формулировка = rng.randrange(3)
    условие = [
        '<p>Треугольник \\(ABC\\) остроугольный, \\(%(X)s%(X1)s\\) и '
        '\\(%(Y)s%(Y1)s\\) — его высоты. Докажите, что '
        '\\(\\angle %(X)s%(X1)s%(Y1)s = \\angle %(X)s%(Y)s%(Y1)s\\).</p>',

        '<p>Из вершин \\(%(X)s\\) и \\(%(Y)s\\) остроугольного треугольника '
        '\\(ABC\\) опущены высоты \\(%(X)s%(X1)s\\) и \\(%(Y)s%(Y1)s\\). '
        'Докажите, что углы \\(%(X)s%(X1)s%(Y1)s\\) и \\(%(X)s%(Y)s%(Y1)s\\) '
        'равны.</p>',

        '<p>Точки \\(%(X1)s\\) и \\(%(Y1)s\\) — основания высот остроугольного '
        'треугольника \\(ABC\\), проведённых из вершин \\(%(X)s\\) и \\(%(Y)s\\). '
        'Докажите, что \\(\\angle %(X)s%(X1)s%(Y1)s = \\angle %(X)s%(Y)s%(Y1)s\\).</p>',
    ][формулировка] % б

    доказательство = (
        # Шаг 1 нужен не для формальности: без него на шаге 4 нельзя сказать,
        # по какую сторону от хорды лежат вершины углов (см. ловушку 1).
        '<p>1. Так как треугольник \\(ABC\\) остроугольный, основания высот лежат '
        'на самих сторонах: точка \\(%(X1)s\\) — внутри отрезка \\(%(YZ)s\\), точка '
        '\\(%(Y1)s\\) — внутри отрезка \\(%(XZ)s\\). Действительно, если бы точка '
        '\\(%(X1)s\\) попала на продолжение стороны \\(%(YZ)s\\) за вершину '
        '\\(%(Z)s\\), то в прямоугольном треугольнике \\(%(X)s%(X1)s%(Z)s\\) угол '
        '\\(%(X)s%(Z)s%(X1)s\\) был бы острым, а смежный с ним угол '
        '\\(%(X)s%(Z)s%(Y)s\\) треугольника \\(ABC\\) — тупым; при '
        '\\(%(X1)s = %(Z)s\\) угол \\(%(Z)s\\) был бы прямым. И то и другое '
        'противоречит условию. Продолжение за вершину \\(%(Y)s\\) и точка '
        '\\(%(Y1)s\\) разбираются так же.</p>'

        '<p>2. По определению высоты \\(%(X)s%(X1)s \\perp %(YZ)s\\) и '
        '\\(%(Y)s%(Y1)s \\perp %(XZ)s\\), поэтому</p>'
        '\\[\\angle %(X)s%(X1)s%(Y)s = 90^\\circ, \\qquad '
        '\\angle %(X)s%(Y1)s%(Y)s = 90^\\circ,\\]'
        '<p>то есть из точек \\(%(X1)s\\) и \\(%(Y1)s\\) отрезок \\(%(XY)s\\) виден '
        'под прямым углом.</p>'

        '<p>3. Дополнительное построение. Пусть \\(O\\) — середина стороны '
        '\\(%(XY)s\\). Проведём окружность с центром \\(O\\) и радиусом '
        '\\(O%(X)s = O%(Y)s\\) — окружность с диаметром \\(%(XY)s\\). В прямоугольном '
        'треугольнике \\(%(X)s%(X1)s%(Y)s\\) отрезок \\(%(X1)sO\\) — медиана, '
        'проведённая к гипотенузе \\(%(XY)s\\), а такая медиана равна половине '
        'гипотенузы:</p>'
        '\\[%(X1)sO = \\frac{%(XY)s}{2} = O%(X)s.\\]'
        '<p>Значит, точка \\(%(X1)s\\) лежит на построенной окружности. Точно так же '
        'в прямоугольном треугольнике \\(%(X)s%(Y1)s%(Y)s\\) медиана \\(%(Y1)sO\\) '
        'равна \\(\\dfrac{%(XY)s}{2}\\), и точка \\(%(Y1)s\\) тоже лежит на этой '
        'окружности. Итак, четыре точки \\(%(X)s\\), \\(%(Y)s\\), \\(%(X1)s\\), '
        '\\(%(Y1)s\\) лежат на одной окружности: четырёхугольник '
        '\\(%(X)s%(Y)s%(X1)s%(Y1)s\\) вписанный.</p>'

        '<p>4. Углы \\(%(X)s%(X1)s%(Y1)s\\) и \\(%(X)s%(Y)s%(Y1)s\\) — вписанные в эту '
        'окружность, и оба опираются на одну хорду \\(%(X)s%(Y1)s\\). Их вершины '
        '\\(%(X1)s\\) и \\(%(Y)s\\) лежат по одну сторону от прямой \\(%(X)s%(Y1)s\\): '
        'это прямая \\(%(XZ)s\\), а точка \\(%(X1)s\\) лежит внутри отрезка '
        '\\(%(YZ)s\\) (шаг 1), который с прямой \\(%(XZ)s\\) имеет единственную общую '
        'точку \\(%(Z)s\\). Поэтому оба угла опираются на одну и ту же дугу '
        '\\(%(X)s%(Y1)s\\). Вписанные углы, опирающиеся на одну дугу, равны:</p>'
        '\\[\\angle %(X)s%(X1)s%(Y1)s = \\angle %(X)s%(Y)s%(Y1)s,\\]'
        '<p>что и требовалось доказать.</p>'

        '<p><i>Замечание.</i> Величину этих углов можно указать явно. В '
        'прямоугольном треугольнике \\(%(X)s%(Y1)s%(Y)s\\) сумма острых углов равна '
        '\\(90^\\circ\\), а его угол при вершине \\(%(X)s\\) — это угол \\(%(X)s\\) '
        'треугольника \\(ABC\\) (точка \\(%(Y1)s\\) лежит на стороне \\(%(XZ)s\\)). '
        'Поэтому \\(\\angle %(X)s%(Y)s%(Y1)s = 90^\\circ - \\angle %(X)s\\), и тому '
        'же равен \\(\\angle %(X)s%(X1)s%(Y1)s\\).</p>'
    ) % б

    # Чертёж: A слева внизу, B справа внизу, C сверху — как в учебнике.
    # Абсцисса C отодвинута от середины основания, чтобы треугольник не
    # выглядел равнобедренным (тогда высоты симметричны и картинка врёт об
    # общности), а высота ограничена снизу, чтобы угол C оставался острым с
    # запасом. Остроугольность всё равно проверяется числом.
    while True:
        cx = 5.0 + rng.choice([-1, 1]) * rng.uniform(0.7, 2.0)
        cy = rng.uniform(6.5, 9.0)
        A, B, C = (0.0, 0.0), (10.0, 0.0), (cx, cy)
        углы = {'A': _величина_угла(A, B, C),
                'B': _величина_угла(B, A, C),
                'C': _величина_угла(C, A, B)}
        if 40.0 < min(углы.values()) and max(углы.values()) < 80.0:
            break

    поз = {'A': A, 'B': B, 'C': C}
    PX, PY, PZ = поз[X], поз[Y], поз[Z]
    PX1 = проекция(PY, PZ, PX)          # основание высоты из X на YZ
    PY1 = проекция(PX, PZ, PY)          # основание высоты из Y на XZ
    O = середина(PX, PY)
    R = hypot(PX[0] - PY[0], PX[1] - PY[1]) / 2.0
    центр = ((A[0] + B[0] + C[0]) / 3.0, (A[1] + B[1] + C[1]) / 3.0)

    ч = Чертёж(width=380, height=330)
    ч.многоугольник([A, B, C])
    ч.отрезок(PX, PX1)
    ч.отрезок(PY, PY1)
    ч.отрезок(PX1, PY1)
    # Дополнительное построение — окружность с диаметром XY и две медианы
    # X₁O, Y₁O, через которые доказывается, что основания высот на ней лежат.
    ч.окружность(O, R, пунктир=True, вспомогательная=True)
    ч.отрезок(O, PX1, пунктир=True, вспомогательный=True)
    ч.отрезок(O, PY1, пунктир=True, вспомогательный=True)
    for конец in (PX, PY, PX1, PY1):
        ч.равенство(O, конец)            # четыре радиуса равны
    # Прямые углы при основаниях высот — те, что «смотрят» на диаметр XY.
    ч.прямой_угол(PX1, PX, PY, размер=0.55)
    ч.прямой_угол(PY1, PY, PX, размер=0.55)
    # Доказываемая пара равных углов.
    ч.дуга_угла(PX1, PX, PY1, радиус=1.0)
    ч.дуга_угла(PY, PX, PY1, радиус=1.0)
    подписать_вершины(
        ч,
        (A, 'A', _наружу(A, центр)),
        (B, 'B', _наружу(B, центр)),
        (C, 'C', _наружу(C, центр)),
        # Основания высот лежат на окружности, поэтому их подписи уводим не
        # просто наружу, а в самый свободный от линий сектор (см. помощник).
        (PX1, _инд(X), _сторона_основания(PX1, (PY, PZ), (PX, PY1, O), O, центр)),
        (PY1, _инд(Y), _сторона_основания(PY1, (PX, PZ), (PY, PX1, O), O, центр)),
        (O, 'O', _наружу(O, центр)),
    )

    return {
        'title': 'Две высоты остроугольного треугольника: углы при основаниях высот равны',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Высота треугольника перпендикулярна стороне, к которой проведена; '
            'в остроугольном треугольнике основания всех высот лежат на самих сторонах.',
            'Медиана прямоугольного треугольника, проведённая к гипотенузе, равна её '
            'половине; поэтому вершина прямого угла лежит на окружности, диаметр '
            'которой — гипотенуза.',
            'Вписанные углы, опирающиеся на одну и ту же дугу, равны.',
            'Сумма острых углов прямоугольного треугольника равна 90° '
            '(для замечания о величине углов).',
        ],
        'params': {
            'X': X, 'Y': Y, 'Z': Z, 'формулировка': формулировка,
            'C': (round(cx, 2), round(cy, 2)),
            'углы': {k: round(v, 1) for k, v in углы.items()},
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 19. Две высоты тупоугольного треугольника: треугольник на основаниях
# ────────────────────────────────────────────────────────────────────────
#
# высот подобен исходному.
#
# Конфигурация. Треугольник ABC с тупым углом при одной из вершин — назовём её
# V, две другие P и Q (в алфавитном порядке). Из P и Q проведены высоты PP₁ и
# QQ₁. Из-за тупого угла их основания ложатся не на стороны, а на продолжения
# сторон QV и PV за вершину V: над тупой вершиной вырастает маленький
# «перевёрнутый» треугольник VP₁Q₁. Доказать нужно, что он подобен исходному:
# VP₁Q₁ ∼ VPQ (V ↔ V, P₁ ↔ P, Q₁ ↔ Q). Три задачи банка — тупой угол при A,
# при B и при C — одна картинка с переставленными буквами, поэтому тупая
# вершина выбирается случайно, а буквы оснований высот следуют за ней.
#
# Ключевой ход. Обе высоты дают прямой угол, опирающийся на одну и ту же
# сторону PQ: ∠PP₁Q = ∠PQ₁Q = 90°. Значит, P₁ и Q₁ лежат на окружности с
# диаметром PQ: медиана прямоугольного треугольника к гипотенузе равна её
# половине, так что середина O отрезка PQ равноудалена от всех четырёх точек.
# Дальше работают вписанные углы: ∠PQ₁P₁ = ∠PQP₁ как опирающиеся на дугу PP₁.
# Остаётся заметить, что это те же самые углы Q₁ и Q двух наших треугольников
# (V лежит на отрезках PQ₁ и QP₁, лучи совпадают), а углы при V вертикальные —
# и подобие по двум углам готово.
#
# Почему нужна именно тупость. При остром угле V основания высот попадают на
# сами стороны, треугольник VP₁Q₁ лежит внутри VPQ, угол V у них общий, а не
# вертикальный — утверждение остаётся верным (это сюжет 18), но доказательство
# и чертёж другие. При прямом угле V основания высот сливаются с V, и
# треугольника VP₁Q₁ нет. Коэффициент подобия равен cos(180° − ∠V) = |cos V|:
# VQ₁ = VQ·cos(180° − ∠V) из прямоугольного треугольника QQ₁V. Через это
# равенство и VP₁ = VP·|cos V| подобие получается и без окружности, по второму
# признаку; мы ведём доказательство через окружность — это тот же приём, что в
# сюжетах 18, 22 и 23, и ученику полезно увидеть его на «неудобной» картинке.
#
# Ловушки.
# * Порядок точек на окружности — P, P₁, Q₁, Q: дуга PP₁ равна 2∠Q, дуга QQ₁
#   равна 2∠P, и вместе они меньше 180°, раз угол V тупой. Поэтому равны углы
#   ∠PQ₁P₁ и ∠PQP₁ (вершины по одну сторону от хорды PP₁). А пара из
#   остроугольного сюжета ∠PP₁Q₁ = ∠PQQ₁ здесь ложна: вершины P₁ и Q лежат по
#   разные стороны от хорды PQ₁, и эти углы дают в сумме 180°.
# * Переход ∠PQ₁P₁ → ∠VQ₁P₁ и ∠PQP₁ → ∠PQV законен только потому, что V лежит
#   между P и Q₁ и между Q и P₁. Это и есть место, где используется тупость
#   угла, и его надо проговорить, а не показать на чертеже.
# * Запись подобия фиксирует соответствие вершин: △AB₁C₁ ∼ △ABC, а не
#   △AC₁B₁ ∼ △ABC. Основание высоты из B соответствует самой вершине B.
# * Чертёж: половина окружности с диаметром PQ уходит под основание, поэтому
#   холст выше обычного. Угол при V берём из промежутка 106°–124°, углы при
#   основании — заметно разными, иначе картинка подсказывает равнобедренность.
#   Отсечённый треугольник мал (коэффициент |cos V| ≈ 0,3–0,55), и при сильно
#   разных углах при основании его короткая сторона сжимается до пары десятков
#   пикселей — дужки перестают помещаться и налезают друг на друга. Поэтому
#   короткую из сторон VP₁, VQ₁ проверяем числом и не даём ей стать меньше 0,8
#   при основании 6.


ВЕРШИНЫ_19 = ['A', 'B', 'C']


def _индекс(буква):
    """Подпись вида B₁ для SVG: буква и нижний индекс через tspan."""
    return '%s<tspan font-size="9" dy="3">1</tspan>' % буква


def _угол_19(a, b, c):
    """Величина угла abc в градусах — для числовой проверки формы."""
    ux, uy = a[0] - b[0], a[1] - b[1]
    vx, vy = c[0] - b[0], c[1] - b[1]
    cos = (ux * vx + uy * vy) / math.hypot(ux, uy) / math.hypot(vx, vy)
    return math.degrees(math.acos(max(-1.0, min(1.0, cos))))


@сюжет(19)
def _сюжет_19(rng):
    # ── буквы ──────────────────────────────────────────────────────────
    # V — тупая вершина, P и Q — две другие в алфавитном порядке. Высота из
    # P падает на прямую VQ, высота из Q — на прямую VP.
    V = rng.choice(ВЕРШИНЫ_19)
    P, Q = [t for t in ВЕРШИНЫ_19 if t != V]
    P1, Q1 = P + '_1', Q + '_1'

    # Имена отрезков в привычном порядке букв: AB, AC, BC.
    VP = ''.join(sorted((V, P)))
    VQ = ''.join(sorted((V, Q)))
    PQ = P + Q
    # Отсечённый треугольник называем так, чтобы буквы стояли под своими
    # прообразами: AB₁C₁ под ABC, A₁BC₁ под ABC, A₁B₁C под ABC.
    малый = ''.join(t if t == V else t + '_1' for t in ВЕРШИНЫ_19)
    уголV = P + V + Q          # BAC, ABC, ACB — как принято называть угол
    д = dict(V=V, P=P, Q=Q, P1=P1, Q1=Q1, VP=VP, VQ=VQ, PQ=PQ,
             малый=малый, уголV=уголV)

    # ── условие ────────────────────────────────────────────────────────
    if rng.random() < 0.5:
        условие = (
            '<p>В треугольнике \\(ABC\\) угол \\(%(V)s\\) тупой. Проведены '
            'высоты \\(%(P)s%(P1)s\\) и \\(%(Q)s%(Q1)s\\) (точки \\(%(P1)s\\) и '
            '\\(%(Q1)s\\) лежат на прямых \\(%(VQ)s\\) и \\(%(VP)s\\)). Докажите, '
            'что треугольник \\(%(малый)s\\) подобен треугольнику \\(ABC\\).</p>'
            % д)
    else:
        условие = (
            '<p>Из вершин \\(%(P)s\\) и \\(%(Q)s\\) треугольника \\(ABC\\), у '
            'которого угол \\(%(V)s\\) тупой, проведены высоты \\(%(P)s%(P1)s\\) '
            'и \\(%(Q)s%(Q1)s\\) (\\(%(P1)s\\) и \\(%(Q1)s\\) лежат на прямых '
            '\\(%(VQ)s\\) и \\(%(VP)s\\)). Докажите подобие треугольников '
            '\\(%(малый)s\\) и \\(ABC\\).</p>' % д)

    # ── доказательство ─────────────────────────────────────────────────
    доказательство = (
        '<p>1. Выясним, где лежат основания высот. Точка \\(%(P1)s\\) лежит '
        'на прямой \\(%(VQ)s\\). С точкой \\(%(V)s\\) она не совпадает: иначе '
        '\\(%(VP)s \\perp %(VQ)s\\) и угол \\(%(V)s\\) был бы прямым. Лежать на '
        'луче \\(%(V)s%(Q)s\\) она тоже не может: тогда угол '
        '\\(%(P)s%(V)s%(P1)s\\) совпал бы с углом \\(%(уголV)s\\), но первый из '
        'них — острый угол прямоугольного треугольника \\(%(P)s%(P1)s%(V)s\\), '
        'а второй тупой. Значит, \\(%(P1)s\\) лежит на продолжении стороны '
        '\\(%(VQ)s\\) за точку \\(%(V)s\\), то есть точка \\(%(V)s\\) находится '
        'между \\(%(Q)s\\) и \\(%(P1)s\\). Точно так же \\(%(Q1)s\\) лежит на '
        'продолжении стороны \\(%(VP)s\\) за точку \\(%(V)s\\): точка \\(%(V)s\\) '
        'находится между \\(%(P)s\\) и \\(%(Q1)s\\).</p>'

        '<p>2. По определению высоты \\(%(P)s%(P1)s \\perp %(VQ)s\\), а точка '
        '\\(%(Q)s\\) лежит на прямой \\(%(VQ)s\\), поэтому '
        '\\(\\angle %(P)s%(P1)s%(Q)s = 90^\\circ\\). Аналогично '
        '\\(%(Q)s%(Q1)s \\perp %(VP)s\\), точка \\(%(P)s\\) лежит на прямой '
        '\\(%(VP)s\\), поэтому \\(\\angle %(P)s%(Q1)s%(Q)s = 90^\\circ\\).</p>'

        '<p>3. Пусть \\(O\\) — середина стороны \\(%(PQ)s\\). В прямоугольном '
        'треугольнике \\(%(P)s%(P1)s%(Q)s\\) отрезок \\(%(P1)sO\\) — медиана, '
        'проведённая к гипотенузе \\(%(PQ)s\\), а такая медиана равна половине '
        'гипотенузы: \\(O%(P1)s = \\tfrac12 %(PQ)s = O%(P)s = O%(Q)s\\). Точно '
        'так же в прямоугольном треугольнике \\(%(P)s%(Q1)s%(Q)s\\) получаем '
        '\\(O%(Q1)s = \\tfrac12 %(PQ)s\\). Итак, точки \\(%(P)s\\), \\(%(Q)s\\), '
        '\\(%(P1)s\\), \\(%(Q1)s\\) равноудалены от \\(O\\), то есть лежат на '
        'одной окружности — с центром \\(O\\) и диаметром \\(%(PQ)s\\).</p>'

        '<p>4. Углы \\(%(P)s%(Q1)s%(P1)s\\) и \\(%(P)s%(Q)s%(P1)s\\) — вписанные '
        'в эту окружность, и оба опираются на дугу \\(%(P)s%(P1)s\\): их '
        'вершины \\(%(Q1)s\\) и \\(%(Q)s\\) лежат по одну сторону от хорды '
        '\\(%(P)s%(P1)s\\) — по ту же, что и \\(%(V)s\\), ведь по пункту 1 '
        'точка \\(%(Q1)s\\) лежит на луче \\(%(P)s%(V)s\\), а \\(%(Q)s\\) — на '
        'луче \\(%(P1)s%(V)s\\). Вписанные углы, опирающиеся на одну дугу, '
        'равны: \\(\\angle %(P)s%(Q1)s%(P1)s = \\angle %(P)s%(Q)s%(P1)s\\).</p>'

        '<p>5. Перепишем это равенство через углы треугольников '
        '\\(%(малый)s\\) и \\(ABC\\). Точка \\(%(V)s\\) лежит между \\(%(P)s\\) и '
        '\\(%(Q1)s\\), поэтому лучи \\(%(Q1)s%(P)s\\) и \\(%(Q1)s%(V)s\\) '
        'совпадают и \\(\\angle %(P)s%(Q1)s%(P1)s = \\angle %(V)s%(Q1)s%(P1)s\\). '
        'Точка \\(%(V)s\\) лежит между \\(%(Q)s\\) и \\(%(P1)s\\), поэтому лучи '
        '\\(%(Q)s%(P1)s\\) и \\(%(Q)s%(V)s\\) совпадают и '
        '\\(\\angle %(P)s%(Q)s%(P1)s = \\angle %(P)s%(Q)s%(V)s\\). Следовательно,'
        '\\[\\angle %(V)s%(Q1)s%(P1)s = \\angle %(P)s%(Q)s%(V)s.\\]'
        'Кроме того, луч \\(%(V)s%(P1)s\\) противоположен лучу \\(%(V)s%(Q)s\\), '
        'а луч \\(%(V)s%(Q1)s\\) — лучу \\(%(V)s%(P)s\\) (пункт 1). Значит, углы '
        '\\(%(P1)s%(V)s%(Q1)s\\) и \\(%(уголV)s\\) вертикальные, а вертикальные '
        'углы равны: \\(\\angle %(P1)s%(V)s%(Q1)s = \\angle %(уголV)s\\).</p>'

        '<p>6. В треугольниках \\(%(малый)s\\) и \\(ABC\\) два угла одного '
        'соответственно равны двум углам другого: '
        '\\(\\angle %(P1)s%(V)s%(Q1)s = \\angle %(уголV)s\\) и '
        '\\(\\angle %(V)s%(Q1)s%(P1)s = \\angle %(P)s%(Q)s%(V)s\\). По первому '
        'признаку подобия \\(\\triangle %(малый)s \\sim \\triangle ABC\\), '
        'причём вершине \\(%(V)s\\) соответствует \\(%(V)s\\), вершине '
        '\\(%(P1)s\\) — \\(%(P)s\\), вершине \\(%(Q1)s\\) — \\(%(Q)s\\). Что и '
        'требовалось доказать.</p>'
    ) % д

    # ── чертёж ─────────────────────────────────────────────────────────
    # Тупая вершина сверху, P слева, Q справа, основание PQ горизонтально.
    # Углы при основании берём заметно разными: равнобедренная картинка
    # подсказывает лишнее. Тупой угол не слишком близок к 90°, иначе
    # отсечённый треугольник получается крошечным, и не слишком велик,
    # иначе исходный превращается в полоску.
    основание = 6.0
    while True:
        α = rng.randint(106, 124)
        β = rng.randint(20, 160 - α)
        γ = 180 - α - β
        if abs(β - γ) < 8:
            continue
        a, b, g = (math.radians(x) for x in (α, β, γ))
        PV = основание * math.sin(g) / math.sin(a)      # теорема синусов
        QV = основание * math.sin(b) / math.sin(a)
        # Стороны отсечённого треугольника: VP₁ = VP·|cos V|, VQ₁ = VQ·|cos V|.
        # Короткая из них должна вместить дужку угла и подпись вершины V,
        # иначе при сильном перекосе углов при основании картинка слипается.
        if min(PV, QV) * (-math.cos(a)) >= 0.8:
            break
    pP, pQ = (0.0, 0.0), (основание, 0.0)
    pV = (PV * math.cos(b), PV * math.sin(b))
    pP1 = проекция(pV, pQ, pP)      # основание высоты из P на прямую VQ
    pQ1 = проекция(pV, pP, pQ)      # основание высоты из Q на прямую VP
    pO = середина(pP, pQ)

    # Числовая страховка формы: угол при V тупой, основания высот за V.
    assert _угол_19(pP, pV, pQ) > 90.0
    assert _угол_19(pP1, pV, pQ) > 179.0 and _угол_19(pQ1, pV, pP) > 179.0

    ч = Чертёж(height=350)
    ч.многоугольник([pP, pV, pQ])
    ч.многоугольник([pV, pP1, pQ1])
    # Окружность на диаметре PQ — вспомогательное построение из пункта 3.
    ч.окружность(pO, основание / 2, пунктир=True, вспомогательная=True)
    ч.отрезок(pP, pP1)
    ч.отрезок(pQ, pQ1)
    ч.прямой_угол(pP1, pP, pV, размер=0.3)
    ч.прямой_угол(pQ1, pQ, pV, размер=0.3)
    # Равные углы при Q и Q₁ — одной дужкой, вертикальные углы при V — двумя.
    # Дужка при Q₁ не должна вылезать за V по стороне Q₁V (она короткая),
    # поэтому её радиус подрезаем под длину этой стороны.
    дл_VQ1 = math.hypot(pQ1[0] - pV[0], pQ1[1] - pV[1])
    ч.дуга_угла(pQ, pP, pV, радиус=0.6)
    ч.дуга_угла(pQ1, pV, pP1, радиус=min(0.6, 0.55 * дл_VQ1))
    ч.дуга_угла(pV, pP, pQ, радиус=0.4, штрихов=2)
    ч.дуга_угла(pV, pP1, pQ1, радиус=0.4, штрихов=2)
    подписать_вершины(ч, (pP, P, 'юз'), (pQ, Q, 'юв'),
                      (pP1, _индекс(P), 'сз'), (pQ1, _индекс(Q), 'св'))
    ч.вершина(pO, 'O', 'ю', закрашена=False)

    # Подпись тупой вершины. Снизу и сверху от V — дужки вертикальных углов,
    # свободны только узкие секторы слева и справа, между стороной и её
    # продолжением (ширина 180° − ∠V). Готовое смещение 'з' ставит букву
    # строго слева, а левый сектор наклонён на (∠P − ∠Q)/2, и при разных
    # углах при основании буква цепляет линию. Поэтому якорь подписи
    # сдвигаем так, чтобы центр буквы лёг на биссектрису сектора в 20 px
    # от V. Меньше нельзя: полудиагональ буквы с белой обводкой около 9 px,
    # полуширина сектора не меньше 28°, и уже при 15 px обводка вырезала
    # заметный зазор в стороне; 20·sin 28° ≈ 9,4 px — просвет остаётся.
    # Масштаб холста известен заранее: габарит чертежа — окружность 6 × 6,
    # и её вписывает меньшая сторона холста.
    k = (min(ч.width, ч.height) - 2 * ч.поле) / основание
    θ = math.pi + (b - g) / 2                       # биссектриса, в мировых углах
    # Центр буквы при смещении 'з' лежит в (−12, +0.5) px от якоря.
    якорь = (pV[0] + (20 * math.cos(θ) + 12) / k,
             pV[1] + (20 * math.sin(θ) - 0.5) / k)
    ч.точка(pV)
    ч.подпись(якорь, V, 'з')

    return {
        'title': 'Две высоты тупоугольного треугольника: '
                 'треугольник на основаниях высот подобен исходному',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'В тупоугольном треугольнике основания высот, проведённых из вершин '
            'острых углов, лежат на продолжениях сторон за вершину тупого угла.',
            'Медиана прямоугольного треугольника, проведённая к гипотенузе, равна '
            'её половине; поэтому вершина прямого угла лежит на окружности, '
            'диаметр которой — гипотенуза.',
            'Вписанные углы, опирающиеся на одну и ту же дугу, равны.',
            'Вертикальные углы равны. Первый признак подобия: если два угла одного '
            'треугольника соответственно равны двум углам другого, треугольники '
            'подобны.',
        ],
        'params': {
            'тупая_вершина': V, 'высоты': [P + P1, Q + Q1],
            'малый_треугольник': малый,
            'углы_градусов': {V: α, P: β, Q: γ},
            'коэффициент_подобия': round(-math.cos(a), 3),
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 20. Равные отрезки на стороне треугольника: из AD = CE и BD = BE
# ────────────────────────────────────────────────────────────────────────
#
# следует AB = BC.
#
# Конфигурация. Треугольник ABC, на стороне AC взяты две точки D и E так, что
# AD = CE (отложены от концов стороны на одно и то же расстояние) и BD = BE
# (отрезки из вершины B к ним равны). Требуется доказать AB = BC, то есть что
# треугольник ABC равнобедренный с основанием AC. Чисел в сюжете нет и взять
# их неоткуда: оба условия — равенства отрезков, а любое конкретное число
# либо ничего не добавило бы, либо противоречило бы конфигурации.
#
# Ключевой ход — «равнобедренный треугольник BDE → смежные углы → первый
# признак равенства». Из BD = BE треугольник BDE равнобедренный, углы при его
# основании DE равны: ∠BDE = ∠BED. Точки D и E лежат на одной прямой AC,
# поэтому ∠ADB смежен с ∠BDE, а ∠CEB смежен с ∠BED; углы, смежные с равными,
# равны, значит ∠ADB = ∠CEB. Теперь у треугольников ABD и CBE есть по две
# равные стороны (AD = CE, BD = BE) и равные углы между ними — они равны по
# первому признаку, и против равных углов ADB и CEB лежат равные стороны
# AB и CB.
#
# Почему это работает. Равенство BD = BE само по себе ничего не говорит о
# сторонах AB и BC — оно говорит об углах при D и E. Смежность переносит
# равенство углов из «внутреннего» треугольника BDE наружу, в те углы, что
# зажаты между заданными равными отрезками. Без этого переноса первый признак
# применить не к чему: углы BAD и BCE, которые ученик хочет объявить равными
# сразу, — это то, что доказывается, а не то, что дано.
#
# Второй способ, короче, но с более сильной теоремой: B равноудалена от D и
# E, значит лежит на серединном перпендикуляре к DE; из AD = CE середина DE
# совпадает с серединой AC, так что этот же перпендикуляр — серединный
# перпендикуляр к AC, а каждая его точка равноудалена от A и C. В разборе он
# дан замечанием, основное доказательство — через признак равенства, его
# ждёт эксперт.
#
# Ловушки.
# 1. Порядок точек на стороне. На учебном чертеже D лежит между A и E, то
#    есть AD = CE < AC/2, и углы ADB, BDE смежные. При AD = CE > AC/2 точки
#    меняются местами (порядок A, E, D, C): тогда ∠ADB — это тот же угол,
#    что ∠EDB, а ∠CEB — тот же, что ∠DEB, равенство ∠ADB = ∠CEB получается
#    без смежных углов, остальное не меняется. При AD = CE = AC/2 точки
#    совпадают, BD = BE выполняется само собой, и AB = BC из него не
#    следует — задача имеет смысл только для двух различных точек. Чертёж
#    строится в учебном варианте AD = CE < AC/2, другой порядок оговорён в
#    замечании к доказательству.
# 2. Какой угол между сторонами. В первом признаке нужен угол между равными
#    парами сторон: в треугольнике ABD это ∠ADB (между AD и BD), в
#    треугольнике CBE — ∠CEB (между CE и BE). Ученики берут ∠BAD и ∠BCE —
#    а их равенство и есть цель, получается круг.
# 3. Вывод из равенства треугольников. Нужно назвать, какая сторона какой
#    соответствует: AB лежит против угла ADB, CB — против угла CEB
#    (соответствие вершин A↔C, B↔B, D↔E). Голое «значит, AB = BC» эксперт
#    считает необоснованным шагом.
#
# Варьируется только нечисловое: обозначения точек на стороне (D и E, M и N,
# K и M), формулировка цели («AB = BC» либо «треугольник ABC равнобедренный»)
# и, как отмечено в справочнике, логическая схема: посылку и заключение можно
# поменять местами — из AB = BC и AD = CE вывести BD = BE. Обратная задача
# доказывается тем же первым признаком, только равные углы берутся при
# основании треугольника ABC; она выпадает примерно в трети случаев. На
# чертеже варьируются высота треугольника и отступ точек от концов стороны.


def _угол_20(a, вершина, b):
    return '\\angle %s%s%s' % (a, вершина, b)


@сюжет(20)
def _сюжет_20(rng):
    # Точки на стороне AC: P ближе к A, Q ближе к C. Классическая пара — D и E,
    # поэтому она выпадает вдвое чаще прочих.
    P, Q = rng.choice([('D', 'E'), ('D', 'E'), ('M', 'N'), ('K', 'M')])
    # Прямая задача (AD = CE, BD = BE ⇒ AB = BC) — основная; обратная
    # (AD = CE, AB = BC ⇒ BD = BE) — вторая логическая схема из справочника,
    # выпадает реже.
    обратная = rng.random() < 0.3
    формулировка = rng.choice([1, 2])

    б = {
        'P': P, 'Q': Q,
        'AP': 'A' + P, 'CQ': 'C' + Q, 'BP': 'B' + P, 'BQ': 'B' + Q, 'PQ': P + Q,
        'ABP': 'AB' + P, 'CBQ': 'CB' + Q, 'BPQ': 'B' + P + Q,
        'aBPQ': _угол_20('B', P, Q), 'aBQP': _угол_20('B', Q, P),
        'aAPB': _угол_20('A', P, 'B'), 'aCQB': _угол_20('C', Q, 'B'),
        'aBAP': _угол_20('B', 'A', P), 'aBCQ': _угол_20('B', 'C', Q),
    }

    if not обратная:
        if формулировка == 1:
            условие = (
                '<p>Точки \\(%(P)s\\) и \\(%(Q)s\\) лежат на стороне \\(AC\\) '
                'треугольника \\(ABC\\), причём \\(%(AP)s = %(CQ)s\\) и '
                '\\(%(BP)s = %(BQ)s\\). Докажите, что \\(AB = BC\\).</p>' % б)
        else:
            условие = (
                '<p>В треугольнике \\(ABC\\) на стороне \\(AC\\) взяты точки '
                '\\(%(P)s\\) и \\(%(Q)s\\), для которых \\(%(AP)s = %(CQ)s\\) и '
                '\\(%(BP)s = %(BQ)s\\). Докажите, что треугольник \\(ABC\\) '
                'равнобедренный.</p>' % б)

        доказательство = (
            '<p>1. По условию \\(%(BP)s = %(BQ)s\\), поэтому треугольник '
            '\\(%(BPQ)s\\) равнобедренный с основанием \\(%(PQ)s\\). По свойству '
            'равнобедренного треугольника углы при основании равны: '
            '\\(%(aBPQ)s = %(aBQP)s\\).</p>'
            '<p>2. Точки \\(%(P)s\\) и \\(%(Q)s\\) лежат на отрезке \\(AC\\). '
            'Равные отрезки \\(%(AP)s\\) и \\(%(CQ)s\\) отложены от разных концов '
            'стороны; будем считать, что каждый из них короче половины \\(AC\\) '
            '(случай, когда они длиннее половины, разобран в замечании после '
            'доказательства). Тогда точки идут в порядке '
            '\\(A,\\ %(P)s,\\ %(Q)s,\\ C\\): точка \\(%(P)s\\) лежит между '
            '\\(A\\) и \\(%(Q)s\\), точка \\(%(Q)s\\) — между \\(%(P)s\\) и \\(C\\). '
            'Значит, лучи \\(%(P)sA\\) и \\(%(P)s%(Q)s\\) — дополнительные '
            '(вместе они составляют прямую \\(AC\\)), и угол \\(A%(P)sB\\) '
            'смежен с углом \\(B%(P)s%(Q)s\\); точно так же угол \\(C%(Q)sB\\) '
            'смежен с углом \\(B%(Q)s%(P)s\\).</p>'
            '<p>3. Сумма смежных углов равна \\(180^\\circ\\), поэтому</p>'
            '\\[%(aAPB)s = 180^\\circ - %(aBPQ)s, \\qquad '
            '%(aCQB)s = 180^\\circ - %(aBQP)s.\\]'
            '<p>Вычитаемые равны по шагу 1, следовательно, '
            '\\(%(aAPB)s = %(aCQB)s\\).</p>'
            '<p>4. Рассмотрим треугольники \\(%(ABP)s\\) и \\(%(CBQ)s\\). В них '
            '\\(%(AP)s = %(CQ)s\\) и \\(%(BP)s = %(BQ)s\\) по условию, а углы, '
            'заключённые между этими сторонами, равны: \\(%(aAPB)s = %(aCQB)s\\) '
            'по шагу 3. По первому признаку равенства треугольников (по двум '
            'сторонам и углу между ними) \\(\\triangle %(ABP)s = \\triangle %(CBQ)s\\).</p>'
            '<p>5. В равных треугольниках против равных углов лежат равные '
            'стороны. В треугольнике \\(%(ABP)s\\) против угла \\(A%(P)sB\\) лежит '
            'сторона \\(AB\\), в треугольнике \\(%(CBQ)s\\) против угла \\(C%(Q)sB\\) — '
            'сторона \\(CB\\). Значит, \\(AB = CB\\)%(хвост)s</p>'
            '<p><i>Замечание о порядке точек.</i> Если отрезки \\(%(AP)s = %(CQ)s\\) '
            'длиннее половины \\(AC\\), точки меняются местами и идут в порядке '
            '\\(A,\\ %(Q)s,\\ %(P)s,\\ C\\). Тогда луч \\(%(P)sA\\) проходит через '
            '\\(%(Q)s\\), и угол \\(A%(P)sB\\) — это тот же угол \\(%(Q)s%(P)sB\\), а '
            'угол \\(C%(Q)sB\\) — тот же угол \\(%(P)s%(Q)sB\\). Равенство '
            '\\(%(aAPB)s = %(aCQB)s\\) получается прямо из шага 1, а шаги 4 и 5 '
            'не меняются. Равными половине \\(AC\\) отрезки быть не могут: тогда '
            'обе точки попали бы в середину \\(AC\\) и совпали, а в условии речь '
            'о двух различных точках. Других случаев нет.</p>'
            '<p><i>Другой способ.</i> Точка \\(B\\) равноудалена от \\(%(P)s\\) и '
            '\\(%(Q)s\\), поэтому лежит на серединном перпендикуляре к \\(%(PQ)s\\). '
            'Середина \\(%(PQ)s\\) совпадает с серединой \\(AC\\): к равным отрезкам '
            '\\(%(AP)s\\) и \\(%(CQ)s\\) прибавляются (а при порядке '
            '\\(A,\\ %(Q)s,\\ %(P)s,\\ C\\) — из них вычитаются) равные половины '
            '\\(%(PQ)s\\). '
            'Значит, та же прямая — серединный перпендикуляр к \\(AC\\), а каждая '
            'его точка равноудалена от концов отрезка: \\(BA = BC\\).</p>'
        ) % dict(б, хвост=(
            ', то есть \\(AB = BC\\), что и требовалось доказать.' if формулировка == 1 else
            '. Треугольник, у которого две стороны равны, по определению '
            'равнобедренный: \\(ABC\\) — равнобедренный треугольник с основанием '
            '\\(AC\\), что и требовалось доказать.'))

        факты = [
            'Свойство равнобедренного треугольника: углы при основании равны.',
            'Сумма смежных углов равна 180°, поэтому углы, смежные с равными '
            'углами, равны.',
            'Первый признак равенства треугольников: по двум сторонам и углу '
            'между ними.',
            'В равных треугольниках против равных углов лежат равные стороны.',
        ]
    else:
        if формулировка == 1:
            условие = (
                '<p>В треугольнике \\(ABC\\) известно, что \\(AB = BC\\). Точки '
                '\\(%(P)s\\) и \\(%(Q)s\\) на стороне \\(AC\\) выбраны так, что '
                '\\(%(AP)s = %(CQ)s\\). Докажите, что \\(%(BP)s = %(BQ)s\\).</p>' % б)
        else:
            условие = (
                '<p>На основании \\(AC\\) равнобедренного треугольника \\(ABC\\) '
                'взяты точки \\(%(P)s\\) и \\(%(Q)s\\), причём \\(%(AP)s = %(CQ)s\\). '
                'Докажите, что \\(%(BP)s = %(BQ)s\\).</p>' % б)

        доказательство = (
            '<p>1. %(дано)s По свойству равнобедренного '
            'треугольника углы при основании равны: '
            '\\(\\angle BAC = \\angle BCA\\).</p>'
            '<p>2. Точка \\(%(P)s\\) лежит на стороне \\(AC\\), значит, на луче '
            '\\(AC\\), и угол \\(BA%(P)s\\) — это тот же угол \\(BAC\\). Точно так же '
            'точка \\(%(Q)s\\) лежит на луче \\(CA\\), и угол \\(BC%(Q)s\\) совпадает '
            'с углом \\(BCA\\). Следовательно, \\(%(aBAP)s = %(aBCQ)s\\).</p>'
            '<p>3. Рассмотрим треугольники \\(%(ABP)s\\) и \\(%(CBQ)s\\). В них '
            '\\(AB = CB\\) (шаг 1) и \\(%(AP)s = %(CQ)s\\) по условию, а углы, заключённые '
            'между этими сторонами, равны: \\(%(aBAP)s = %(aBCQ)s\\) по шагу 2. '
            'По первому признаку равенства треугольников (по двум сторонам и '
            'углу между ними) \\(\\triangle %(ABP)s = \\triangle %(CBQ)s\\).</p>'
            '<p>4. В равных треугольниках против равных углов лежат равные '
            'стороны: в треугольнике \\(%(ABP)s\\) против угла \\(BA%(P)s\\) лежит '
            '\\(%(BP)s\\), в треугольнике \\(%(CBQ)s\\) против угла \\(BC%(Q)s\\) — '
            '\\(%(BQ)s\\). Следовательно, \\(%(BP)s = %(BQ)s\\), что и требовалось '
            'доказать.</p>'
        ) % dict(б, дано=(
            'По условию \\(AB = BC\\), то есть треугольник \\(ABC\\) '
            'равнобедренный с основанием \\(AC\\).' if формулировка == 1 else
            'По условию треугольник \\(ABC\\) равнобедренный с основанием '
            '\\(AC\\), то есть \\(AB = BC\\).'))

        факты = [
            'Свойство равнобедренного треугольника: углы при основании равны.',
            'Первый признак равенства треугольников: по двум сторонам и углу '
            'между ними.',
            'В равных треугольниках против равных углов лежат равные стороны.',
        ]

    # Чертёж. Основание AC горизонтально, B — над его серединой: треугольник
    # равнобедренный по утверждению задачи (в прямой — вывод, в обратной —
    # условие), и честный чертёж обязан это показывать. Высота заметно меньше
    # стороны, чтобы треугольник не походил на равносторонний, но и не был
    # плоским. Точки P и Q отстоят от концов AC меньше чем на половину —
    # учебный порядок A, P, Q, C, на который опирается шаг 2.
    AC = 10.0
    h = rng.choice([5.5, 6.0, 6.5, 7.0])
    d = rng.choice([2.2, 2.6, 3.0, 3.4])
    A, C = (0.0, 0.0), (AC, 0.0)
    B = (середина(A, C)[0], h)
    Pк, Qк = (d, 0.0), (AC - d, 0.0)
    # Проверяем то, что чертёж обязан показывать: AB = BC, BP = BQ, точки
    # различны и стоят в учебном порядке.
    assert abs(hypot(B[0] - A[0], B[1] - A[1]) - hypot(B[0] - C[0], B[1] - C[1])) < 1e-9
    assert abs(hypot(B[0] - Pк[0], B[1]) - hypot(B[0] - Qк[0], B[1])) < 1e-9
    assert 0 < d < AC / 2
    # Углы при основании — для отладки: все острые, треугольник не вырожден.
    угол_A = degrees(atan2(h, AC / 2))

    ч = Чертёж()
    ч.многоугольник([A, B, C])
    ч.отрезок(B, Pк)
    ч.отрезок(B, Qк)
    # Одинарные штрихи — равные отрезки на стороне, они даны в обоих вариантах.
    ч.равенство(A, Pк)
    ч.равенство(C, Qк)
    if not обратная:
        # Дано BP = BQ — двойные штрихи. Углы при основании треугольника BPQ —
        # одинарные дужки, смежные им углы APB и CQB — двойные. Радиусы
        # разнесены заметно: дужки сходятся на общем луче PB (QB), и при
        # близких радиусах двойная снаружи читалась бы как продолжение
        # одинарной, будто отмечен один развёрнутый угол.
        ч.равенство(B, Pк, штрихов=2)
        ч.равенство(B, Qк, штрихов=2)
        ч.дуга_угла(Pк, B, Qк, радиус=0.8)
        ч.дуга_угла(Qк, B, Pк, радиус=0.8)
        ч.дуга_угла(Pк, A, B, радиус=0.42, штрихов=2)
        ч.дуга_угла(Qк, C, B, радиус=0.42, штрихов=2)
    else:
        # Дано AB = BC — двойные штрихи; равные углы при основании ABC — дужки.
        ч.равенство(A, B, штрихов=2)
        ч.равенство(C, B, штрихов=2)
        ч.дуга_угла(A, B, C)
        ч.дуга_угла(C, B, A)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'с'), (C, 'C', 'юв'),
                      (Pк, P, 'ю'), (Qк, Q, 'ю'))

    return {
        'title': 'Точки D и E на стороне AC: AD = CE, BD = BE и AB = BC',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': факты,
        'params': {'вариант': 'обратная' if обратная else 'прямая',
                   'формулировка': формулировка, 'точки': P + Q,
                   'высота': h, 'отступ': d, 'AC': AC,
                   'угол_при_основании': round(угол_A, 1)},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 21. Середины сторон равностороннего треугольника — вершины
# ────────────────────────────────────────────────────────────────────────
#
# равностороннего треугольника.
#
# Конфигурация. Равносторонний треугольник ABC, на сторонах AB, BC и AC
# отмечены их середины (в банке — M, N, K). Требуется доказать, что треугольник
# с вершинами в этих серединах тоже равносторонний. Чисел в условии нет и быть
# не может: равносторонность задаёт форму треугольника целиком, размер на
# утверждение не влияет, и любая длина в условии оказалась бы лишней.
#
# Ключевой ход — один из двух, оба из курса 8 класса.
# 1. Средние линии. Отрезок между серединами двух сторон — средняя линия, она
#    равна половине третьей стороны. Три стороны внутреннего треугольника — три
#    средние линии, равные половинам трёх равных сторон, значит, равные между
#    собой.
# 2. Равные угловые треугольники. У вершин A, B, C отсекаются три треугольника;
#    у каждого две стороны — половины сторон ABC (все шесть половин равны), а
#    угол между ними — угол равностороннего треугольника, 60°. По первому
#    признаку три треугольника равны, а их третьи стороны — это стороны
#    внутреннего треугольника.
#
# Почему это работает. Равносторонность — это равенство сторон, а середины
# переводят равенство сторон в равенство их половин. Дальше половины либо
# напрямую оказываются длинами средних линий (ход 1), либо становятся парами
# сторон в равных треугольниках (ход 2). Без равенства сторон ABC утверждение
# ложно: для произвольного треугольника серединный треугольник лишь подобен
# исходному с коэффициентом 1/2, и его стороны различны.
#
# Ловушки.
# 1. Средняя линия равна половине ТРЕТЬЕЙ стороны, а не одной из тех, чьи
#    середины она соединяет: MN (M на AB, N на BC) равна половине AC. Ученики
#    пишут «MN = ½ AB» — в равностороннем треугольнике численно всё сходится,
#    но эксперт это считает ошибкой в обосновании.
# 2. В ходе 2 нельзя писать «треугольники равны» без признака и без указания,
#    какие две стороны и какой угол взяты. Важно и соответствие вершин: против
#    угла A лежит MK, против угла B — MN, против угла C — NK; перепутать —
#    значит получить «равенство» не тех отрезков.
# 3. «Углы треугольника MNK по 60°, значит, он равносторонний» — верно, но
#    само по себе требует доказательства (например, через соответственные углы
#    при MN ∥ AC). Без обоснования это не шаг, а пересказ ответа.
# 4. Чертёж обязан быть равносторонним по-настоящему, а не «примерно»: иначе
#    середины дадут внутренний треугольник, у которого равенство сторон на
#    глаз не читается, и картинка будет спорить с текстом.
#
# Варьируется буквенная разметка середин, формулировка условия и способ
# доказательства (средние линии либо равные треугольники). Чертёж один: AC
# внизу, B сверху; при втором способе добавляются дужки равных углов при
# A, B, C.


def _отр_21(a, b):
    """Имя отрезка с буквами по алфавиту: KM, а не MK; MN, а не NM."""
    return ''.join(sorted((a, b)))


@сюжет(21)
def _сюжет_21(rng):
    # X — середина AB, Y — середина BC, Z — середина AC. Буквы берём из
    # привычных экзаменационных наборов, а порядок внутри набора перемешиваем,
    # чтобы «M всегда на AB» не было единственным вариантом.
    буквы = list(rng.choice(['MNK', 'KLM', 'PKT', 'MNP', 'DEF']))
    rng.shuffle(буквы)
    X, Y, Z = буквы
    XYZ = X + Y + Z
    XY, YZ, XZ = _отр_21(X, Y), _отр_21(Y, Z), _отр_21(X, Z)

    формулировка = rng.choice([1, 2])
    if формулировка == 1:
        условие = (
            '<p>Точки \\(%s\\), \\(%s\\) и \\(%s\\) — середины сторон \\(AB\\), '
            '\\(BC\\) и \\(AC\\) равностороннего треугольника \\(ABC\\) '
            'соответственно. Докажите, что треугольник \\(%s\\) '
            'равносторонний.</p>' % (X, Y, Z, XYZ))
    else:
        условие = (
            '<p>В равностороннем треугольнике \\(ABC\\) отмечены середины сторон: '
            '\\(%s\\) — середина \\(AB\\), \\(%s\\) — середина \\(BC\\), \\(%s\\) — '
            'середина \\(AC\\). Докажите, что \\(%s\\) — равносторонний '
            'треугольник.</p>' % (X, Y, Z, XYZ))

    подстановка = {'X': X, 'Y': Y, 'Z': Z, 'XYZ': XYZ,
                   'XY': XY, 'YZ': YZ, 'XZ': XZ}

    # Два равноправных доказательства; какое показать — решает rng. Оба
    # опираются на одно и то же наблюдение: середины переводят равенство
    # сторон в равенство половин.
    способ = rng.choice(['средние линии', 'равные треугольники'])

    if способ == 'средние линии':
        доказательство = (
            '<p>1. Треугольник \\(ABC\\) равносторонний, поэтому по определению все '
            'его стороны равны: \\(AB = BC = AC\\).</p>'
            '<p>2. Точки \\(%(X)s\\) и \\(%(Y)s\\) — середины сторон \\(AB\\) и '
            '\\(BC\\), значит, отрезок \\(%(XY)s\\) — средняя линия треугольника '
            '\\(ABC\\). По теореме о средней линии треугольника она параллельна '
            'третьей стороне и равна её половине: \\(%(XY)s = \\frac{1}{2}AC\\).</p>'
            '<p>3. Точно так же \\(%(YZ)s\\) — средняя линия, соединяющая середины '
            'сторон \\(BC\\) и \\(AC\\); третья сторона для неё — \\(AB\\), поэтому '
            '\\(%(YZ)s = \\frac{1}{2}AB\\). Отрезок \\(%(XZ)s\\) соединяет середины '
            'сторон \\(AB\\) и \\(AC\\), третья сторона — \\(BC\\), и '
            '\\(%(XZ)s = \\frac{1}{2}BC\\).</p>'
            '<p>4. Стороны \\(AB\\), \\(BC\\) и \\(AC\\) равны между собой, значит, '
            'равны и их половины:</p>'
            '\\[%(XY)s = \\frac{1}{2}AC = \\frac{1}{2}AB = %(YZ)s, \\qquad '
            '%(YZ)s = \\frac{1}{2}AB = \\frac{1}{2}BC = %(XZ)s.\\]'
            '<p>Итак, \\(%(XY)s = %(YZ)s = %(XZ)s\\).</p>'
            '<p>5. У треугольника \\(%(XYZ)s\\) все три стороны равны, то есть он '
            'равносторонний по определению, что и требовалось доказать.</p>'
        ) % подстановка
        факты = [
            'Средняя линия треугольника — отрезок, соединяющий середины двух его '
            'сторон; она параллельна третьей стороне и равна её половине.',
            'Равносторонний треугольник — треугольник, у которого все стороны '
            'равны; определение работает в обе стороны.',
            'Половины равных отрезков равны.',
        ]
    else:
        доказательство = (
            '<p>1. Треугольник \\(ABC\\) равносторонний, поэтому \\(AB = BC = AC\\). '
            'В треугольнике против равных сторон лежат равные углы, значит, '
            '\\(\\angle A = \\angle B = \\angle C\\); сумма углов треугольника равна '
            '\\(180^\\circ\\), поэтому каждый из них равен \\(60^\\circ\\).</p>'
            '<p>2. Точка \\(%(X)s\\) — середина \\(AB\\), поэтому '
            '\\(A%(X)s = %(X)sB = \\frac{1}{2}AB\\). Аналогично '
            '\\(B%(Y)s = %(Y)sC = \\frac{1}{2}BC\\) и '
            '\\(A%(Z)s = %(Z)sC = \\frac{1}{2}AC\\). Стороны \\(AB\\), \\(BC\\), '
            '\\(AC\\) равны, значит, равны и их половины:</p>'
            '\\[A%(X)s = %(X)sB = B%(Y)s = %(Y)sC = C%(Z)s = %(Z)sA.\\]'
            '<p>3. Рассмотрим треугольники \\(A%(X)s%(Z)s\\), \\(B%(Y)s%(X)s\\) и '
            '\\(C%(Z)s%(Y)s\\), отсечённые у вершин \\(A\\), \\(B\\) и \\(C\\). В них '
            '\\(A%(X)s = B%(Y)s = C%(Z)s\\) и \\(A%(Z)s = B%(X)s = C%(Y)s\\) по '
            'шагу 2, а углы между этими сторонами равны: '
            '\\(\\angle %(X)sA%(Z)s = \\angle %(Y)sB%(X)s = \\angle %(Z)sC%(Y)s '
            '= 60^\\circ\\) по шагу 1. По первому признаку равенства треугольников '
            '(по двум сторонам и углу между ними) '
            '\\(\\triangle A%(X)s%(Z)s = \\triangle B%(Y)s%(X)s = '
            '\\triangle C%(Z)s%(Y)s\\).</p>'
            '<p>4. В равных треугольниках против соответственно равных углов лежат '
            'равные стороны. Против углов \\(A\\), \\(B\\) и \\(C\\) лежат стороны '
            '\\(%(XZ)s\\), \\(%(XY)s\\) и \\(%(YZ)s\\) соответственно, поэтому '
            '\\(%(XZ)s = %(XY)s = %(YZ)s\\).</p>'
            '<p>5. Все три стороны треугольника \\(%(XYZ)s\\) равны — он '
            'равносторонний по определению, что и требовалось доказать.</p>'
            '<p><i>Замечание.</i> Каждый из отсечённых треугольников сам '
            'равносторонний: он равнобедренный с углом \\(60^\\circ\\) при вершине, '
            'значит, его углы при основании тоже по \\(60^\\circ\\). Поэтому сторона '
            'треугольника \\(%(XYZ)s\\) равна половине стороны треугольника '
            '\\(ABC\\).</p>'
        ) % подстановка
        факты = [
            'В равностороннем треугольнике все стороны равны, все углы равны и '
            'каждый составляет 60°.',
            'Середина делит отрезок на две равные части.',
            'Первый признак равенства треугольников: по двум сторонам и углу '
            'между ними.',
            'В равных треугольниках против соответственно равных углов лежат '
            'равные стороны.',
        ]

    # Чертёж. Треугольник строится по-настоящему равносторонним (высота
    # a·√3/2), AC внизу, B сверху — так его рисуют в учебнике. Середины не
    # задаются руками, а вычисляются: тогда чертёж не может разойтись с
    # условием.
    a = 6.0
    A, C = (0.0, 0.0), (a, 0.0)
    B = (a / 2, a * sqrt(3) / 2)
    Xк, Yк, Zк = середина(A, B), середина(B, C), середина(A, C)

    # Сверка чертежа с утверждением: три стороны внутреннего треугольника
    # обязаны совпасть по длине. Расхождение означало бы ошибку в посадке.
    длины = [hypot(p[0] - q[0], p[1] - q[1])
             for p, q in ((Xк, Yк), (Yк, Zк), (Zк, Xк))]
    assert max(длины) - min(длины) < 1e-9, 'серединный треугольник не равносторонний'

    ч = Чертёж()
    ч.многоугольник([A, B, C])
    # Внутренний треугольник — только контур: заливка у него та же, что у
    # внешнего, и вторая заливка ничего бы не показала.
    ч.многоугольник([Xк, Yк, Zк], залить=False)
    # Все шесть половин сторон равны (стороны равны, середины делят пополам),
    # поэтому штрих на всех один и тот же.
    for p, q in ((A, Xк), (Xк, B), (B, Yк), (Yк, C), (C, Zк), (Zк, A)):
        ч.равенство(p, q)
    if способ == 'равные треугольники':
        # Углы при вершинах ABC — те самые «углы между сторонами» первого
        # признака; помечаем их одинаковыми дужками.
        for вершина, к1, к2 in ((A, B, C), (B, A, C), (C, A, B)):
            ч.дуга_угла(вершина, к1, к2, радиус=0.5)
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'с'), (C, 'C', 'юв'),
                      (Xк, X, 'сз'), (Yк, Y, 'св'), (Zк, Z, 'ю'))

    return {
        'title': 'Середины сторон равностороннего треугольника — вершины '
                 'равностороннего треугольника',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': факты,
        'params': {'буквы': XYZ, 'способ': способ, 'формулировка': формулировка},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 22. Вписанный четырёхугольник: продолжения пары противоположных
# ────────────────────────────────────────────────────────────────────────
#
# сторон пересекаются вне окружности — отсекаемые треугольники подобны.
#
# Конфигурация. Четырёхугольник ABCD вписан в окружность; продолжения двух
# противоположных сторон пересекаются в точке вне окружности. Из этой точки
# выходят две секущие, на каждой по две вершины четырёхугольника: ближняя к
# точке и дальняя. Окружность отсекает от угла при внешней точке два
# треугольника с общей вершиной: «малый» на ближних вершинах и «большой» на
# дальних. Доказать, что они подобны. Чисел в условии нет вовсе — дана только
# вписанность и сам факт пересечения продолжений.
#
# Две формулировки банка — продолжаются AD и BC (точка K, треугольники KAB и
# KCD) либо AB и CD (точка M, треугольники MBC и MDA) — это одна конфигурация
# с циклическим сдвигом букв, а не два сюжета. Здесь вариант выбирается по rng,
# имя внешней точки — из K, M, P, E; доказательство и чертёж собираются из
# одной и той же схемы «дальняя F1 — ближняя N1 — точка K» на каждой секущей.
#
# Ключевой ход. Внешний угол вписанного четырёхугольника равен внутреннему
# углу при противоположной вершине. Угол малого треугольника при ближней
# вершине (в варианте с AD и BC это ∠KCD) смежен с углом четырёхугольника
# ∠BCD, а ∠BCD + ∠BAD = 180° по свойству вписанного четырёхугольника. Вычитая
# одно равенство из другого, получаем ∠KCD = ∠BAD, а ∠BAD — это и есть угол
# ∠KAB большого треугольника, потому что D лежит на луче AK. Добавляем общий
# угол при K — и подобие по двум углам готово.
#
# Почему работает. Смежный угол и противоположный угол вписанного
# четырёхугольника оба дополняют один и тот же угол ∠BCD до 180°, поэтому
# обязаны быть равны — вписанность нужна ровно для этого шага, больше нигде.
# Из-за этого равенство углов получается «перекрёстным»: угол при ближней
# вершине одной секущей равен углу при дальней вершине другой секущей. Тот же
# результат даёт и путь через вписанные углы (∠BAD и ∠BCD опираются на одну
# хорду BD, но с разных сторон, значит в сумме дают 180°) — это то же
# свойство, записанное иначе.
#
# Ловушки.
#   * Соответствие вершин перекрёстное: в △KAB ∼ △KCD вершине A отвечает C,
#     вершине B — D. Запись «△KAB ∼ △KDC» (по порядку букв) утверждает
#     ∠KAB = ∠KDC, что в общем случае неверно, — эксперт снимает балл.
#   * В доказательстве участвует внешний угол четырёхугольника при ближней
#     вершине, а не внутренний. Фраза «∠KCD = ∠KAB как углы вписанного
#     четырёхугольника» без ссылки на смежность — необоснованный шаг.
#   * Общий угол при K надо назвать явно: без второго равенства углов
#     первый признак подобия не применён.
#   * Расположение точки K: для выпуклого четырёхугольника продолжения
#     противоположных сторон встречаются либо за одной парой вершин, либо за
#     другой. Доказательство пишется для одного случая с оговоркой, что
#     второй симметричен; на чертеже показан именно разобранный случай. Если
#     продолжаемые стороны параллельны (ABCD — равнобедренная трапеция), точки
#     пересечения нет и задачи нет.
#   * Чертёж: две секущие не должны быть симметричны относительно линии
#     центра — иначе ABCD оказывается равнобедренной трапецией и картинка
#     подсказывает свойства, которых в условии нет. Поэтому расстояния от
#     центра до секущих берутся заведомо разными.
#   * Естественное продолжение сюжета (в банке его нет, дано как замечание
#     после доказательства): из подобия KA·KD = KB·KC — теорема об отрезках
#     секущих.


# Стороны света по кругу через 45°, начиная с востока против часовой
# стрелки — в том же порядке, что даёт atan2 в мировых координатах (ось y
# вверх), поэтому индекс = округлённый угол / 45.
_РОЗА = ['в', 'св', 'с', 'сз', 'з', 'юз', 'ю', 'юв']


def _сторона_прочь(p, *соседи, центр=None):
    """Куда ставить подпись точки p, чтобы она не легла на линию.

    Из точки p выходят лучи к соседям (стороны, продолжения). Из восьми
    сторон света выбираем ту, что дальше всего по углу от ближайшего луча:
    так подпись не садится ни на сторону, ни на пунктир, даже когда у
    вершины на секущей три линии сразу. Если p лежит на окружности с
    центром «центр», через неё проходит и сама окружность — вблизи точки
    это касательная, поэтому оба направления касательной тоже считаются
    лучами (без этого буква ложится на дугу окружности).
    """
    лучи = [degrees(atan2(q[1] - p[1], q[0] - p[0])) for q in соседи]
    if центр is not None:
        tx, ty = центр[1] - p[1], p[0] - центр[0]   # касательная ⟂ радиусу
        лучи += [degrees(atan2(ty, tx)), degrees(atan2(-ty, -tx))]
    лучшая, запас = 'юв', -1.0
    for i, сторона in enumerate(_РОЗА):
        угол = 45.0 * i
        зазор = min(abs((угол - л + 180.0) % 360.0 - 180.0) for л in лучи)
        if зазор > запас + 1e-9:
            лучшая, запас = сторона, зазор
    return лучшая


@сюжет(22)
def _сюжет_22(rng):
    # ── Буквы ────────────────────────────────────────────────────────────
    # Схема одна: на каждой секущей дальняя вершина F и ближняя N, внешняя
    # точка K. Четырёхугольник — F1 N1 N2 F2 в порядке обхода, продолжаются
    # стороны F1N1 и F2N2. Вариант 1: AD и BC (K за D и C). Вариант 2: AB и
    # CD (точка за B и C). Ключевое равенство ∠K N2 N1 = ∠K F1 F2 одно и то
    # же; меняются только буквы и порядок, в котором принято называть
    # треугольники в ответе.
    вариант = rng.choice([1, 2])
    K = rng.choice(['K', 'M', 'P', 'E'])
    if вариант == 1:
        F1, N1, N2, F2 = 'A', 'D', 'C', 'B'
        ст_1, ст_2 = 'AD', 'BC'            # сторона через F1,N1 и через F2,N2
        в_условии = (ст_1, ст_2)
    else:
        F1, N1, N2, F2 = 'D', 'C', 'B', 'A'
        ст_1, ст_2 = 'CD', 'AB'
        в_условии = (ст_2, ст_1)           # «AB и CD» читается привычнее
    тр_дальний = K + F1 + F2               # KAB / MDA
    тр_ближний = K + N2 + N1               # KCD / MBC
    if вариант == 1:
        тр1, тр2 = тр_дальний, тр_ближний  # △KAB ∼ △KCD
        пары = [(F1, N2), (F2, N1)]
    else:
        тр1, тр2 = тр_ближний, тр_дальний  # △MBC ∼ △MDA
        пары = [(N2, F1), (N1, F2)]
    соответствие = ('вершине \\(%s\\) соответствует вершина \\(%s\\), '
                    'вершине \\(%s\\) — вершина \\(%s\\)'
                    % (пары[0][0], пары[0][1], пары[1][0], пары[1][1]))

    # ── Условие ──────────────────────────────────────────────────────────
    # Банк: «Известно, что около четырёхугольника ABCD можно описать
    # окружность и что продолжения сторон AD и BC четырёхугольника
    # пересекаются в точке K. Докажите, что треугольники KAB и KCD подобны».
    # Здесь и вступление, и требование перефразированы и варьируются.
    вступление = rng.choice([
        'Четырёхугольник \\(ABCD\\) вписан в окружность',
        'Около четырёхугольника \\(ABCD\\) описана окружность',
        'Все вершины четырёхугольника \\(ABCD\\) лежат на одной окружности',
    ])
    требование = rng.choice([
        'Докажите, что треугольники \\(%s\\) и \\(%s\\) подобны.',
        'Докажите подобие треугольников \\(%s\\) и \\(%s\\).',
        'Докажите, что треугольник \\(%s\\) подобен треугольнику \\(%s\\).',
    ]) % (тр1, тр2)
    условие = (
        '<p>%s, а продолжения его сторон \\(%s\\) и \\(%s\\) пересекаются в '
        'точке \\(%s\\). %s</p>'
        % (вступление, в_условии[0], в_условии[1], K, требование))

    # ── Доказательство ───────────────────────────────────────────────────
    б = {'K': K, 'F1': F1, 'N1': N1, 'N2': N2, 'F2': F2,
         'ст1': ст_1, 'ст2': ст_2, 'тр1': тр1, 'тр2': тр2,
         'усл1': в_условии[0], 'усл2': в_условии[1],
         'дальний': тр_дальний, 'соотв': соответствие}
    доказательство = (
        '<p>1. По условию прямые \\(%(усл1)s\\) и \\(%(усл2)s\\) пересекаются в '
        'точке \\(%(K)s\\), лежащей на продолжениях обеих сторон, то есть вне '
        'четырёхугольника. Разберём случай, изображённый на чертеже: точка '
        '\\(%(K)s\\) лежит на продолжении стороны \\(%(ст1)s\\) за вершину '
        '\\(%(N1)s\\) и на продолжении стороны \\(%(ст2)s\\) за вершину '
        '\\(%(N2)s\\), так что \\(%(N1)s\\) лежит между \\(%(F1)s\\) и '
        '\\(%(K)s\\), а \\(%(N2)s\\) — между \\(%(F2)s\\) и \\(%(K)s\\). Если '
        'точка пересечения лежит за вершинами \\(%(F1)s\\) и \\(%(F2)s\\), '
        'рассуждение то же самое с точностью до обозначений: пары вершин '
        '\\(%(F1)s\\), \\(%(F2)s\\) и \\(%(N1)s\\), \\(%(N2)s\\) меняются '
        'ролями.</p>'

        '<p>2. Точки \\(%(F2)s\\), \\(%(N2)s\\), \\(%(K)s\\) лежат на одной '
        'прямой, причём \\(%(N2)s\\) находится между \\(%(F2)s\\) и '
        '\\(%(K)s\\). Значит, углы \\(%(F2)s%(N2)s%(N1)s\\) и '
        '\\(%(K)s%(N2)s%(N1)s\\) смежные, а сумма смежных углов равна '
        '\\(180^\\circ\\):</p>'
        '\\[\\angle %(K)s%(N2)s%(N1)s = 180^\\circ - \\angle %(F2)s%(N2)s%(N1)s.\\]'

        '<p>3. Около четырёхугольника \\(ABCD\\) описана окружность, а у '
        'вписанного четырёхугольника сумма противоположных углов равна '
        '\\(180^\\circ\\). Углы при вершинах \\(%(F1)s\\) и \\(%(N2)s\\) — '
        'противоположные, поэтому</p>'
        '\\[\\angle %(F2)s%(F1)s%(N1)s + \\angle %(F2)s%(N2)s%(N1)s = 180^\\circ, '
        '\\qquad \\angle %(F2)s%(F1)s%(N1)s = 180^\\circ - \\angle %(F2)s%(N2)s%(N1)s.\\]'

        '<p>4. Правые части равенств из шагов 2 и 3 одинаковы, значит '
        'одинаковы и левые: \\(\\angle %(K)s%(N2)s%(N1)s = '
        '\\angle %(F2)s%(F1)s%(N1)s\\). Точка \\(%(N1)s\\) лежит на луче '
        '\\(%(F1)s%(K)s\\), поэтому \\(\\angle %(F2)s%(F1)s%(N1)s\\) — это '
        'угол \\(%(K)s%(F1)s%(F2)s\\) треугольника \\(%(дальний)s\\). Итак,</p>'
        '\\[\\angle %(K)s%(N2)s%(N1)s = \\angle %(K)s%(F1)s%(F2)s.\\]'
        '<p>(Попутно доказан общий факт: внешний угол вписанного '
        'четырёхугольника равен его внутреннему углу при противоположной '
        'вершине.)</p>'

        '<p>5. Угол при вершине \\(%(K)s\\) у треугольников \\(%(тр1)s\\) и '
        '\\(%(тр2)s\\) общий: луч \\(%(K)s%(F1)s\\) проходит через точку '
        '\\(%(N1)s\\), луч \\(%(K)s%(F2)s\\) — через точку \\(%(N2)s\\), '
        'поэтому \\(\\angle %(F1)s%(K)s%(F2)s\\) и '
        '\\(\\angle %(N1)s%(K)s%(N2)s\\) — один и тот же угол.</p>'

        '<p>6. В треугольниках \\(%(тр1)s\\) и \\(%(тр2)s\\) два угла одного '
        'соответственно равны двум углам другого: '
        '\\(\\angle %(K)s%(N2)s%(N1)s = \\angle %(K)s%(F1)s%(F2)s\\) (шаг 4) '
        'и общий угол при вершине \\(%(K)s\\) (шаг 5). По первому признаку '
        'подобия треугольников \\(\\triangle %(тр1)s \\sim \\triangle %(тр2)s\\), '
        'причём %(соотв)s. Что и требовалось доказать.</p>'

        '<p><b>Замечание.</b> Из подобия следует и равенство второй пары углов '
        '\\(\\angle %(K)s%(N1)s%(N2)s = \\angle %(K)s%(F2)s%(F1)s\\) (на чертеже '
        'они отмечены двойными дужками), а также пропорциональность '
        'сходственных сторон:</p>'
        '\\[\\frac{%(K)s%(F1)s}{%(K)s%(N2)s} = \\frac{%(K)s%(F2)s}{%(K)s%(N1)s} '
        '= \\frac{%(F1)s%(F2)s}{%(N2)s%(N1)s}.\\]'
        '<p>По основному свойству пропорции '
        '\\(%(K)s%(F1)s \\cdot %(K)s%(N1)s = %(K)s%(F2)s \\cdot %(K)s%(N2)s\\) — '
        'это теорема об отрезках секущих, проведённых из одной точки.</p>'
        % б)

    # ── Чертёж ───────────────────────────────────────────────────────────
    # Строим от внешней точки, а не от четырёхугольника: так положение K
    # задаётся напрямую и картинка не расползается. Окружность радиуса R с
    # центром в начале координат, K на оси x на расстоянии d > R. Секущая
    # задаётся расстоянием h от центра до неё (h < R, иначе касательная);
    # обе секущие уходят от K влево, одна вверх, другая вниз. Расстояния h
    # берём заведомо разными — при равных ABCD стал бы равнобедренной
    # трапецией (см. ловушки).
    R = 5.0
    d = rng.choice([8.5, 9.0, 9.5])
    h_пологой = rng.choice([2.0, 2.4, 2.8])
    h_крутой = rng.choice([4.0, 4.3, 4.6])
    крутая_снизу = rng.random() < 0.5
    зеркало = rng.random() < 0.5           # K слева от окружности
    луч1_нижний = rng.random() < 0.5       # где сидят F1 и N1

    def точки_секущей(h, знак):
        """(ближняя, дальняя) точки пересечения с окружностью секущей из
        K = (d, 0), отстоящей от центра на h и идущей влево вверх (знак +1)
        или влево вниз (знак −1)."""
        s = h / d                          # синус угла секущей с осью x
        c = sqrt(1.0 - s * s)
        u = (-c, знак * s)                 # единичный вектор вдоль секущей
        до_основания = sqrt(d * d - h * h)  # от K до проекции центра
        полухорда = sqrt(R * R - h * h)
        t1, t2 = до_основания - полухорда, до_основания + полухорда
        return ((d + t1 * u[0], t1 * u[1]), (d + t2 * u[0], t2 * u[1]))

    h_верх, h_низ = (h_пологой, h_крутой) if крутая_снизу else (h_крутой, h_пологой)
    ближ_в, дал_в = точки_секущей(h_верх, +1)
    ближ_н, дал_н = точки_секущей(h_низ, -1)
    if луч1_нижний:
        pF1, pN1, pF2, pN2 = дал_н, ближ_н, дал_в, ближ_в
    else:
        pF1, pN1, pF2, pN2 = дал_в, ближ_в, дал_н, ближ_н
    pK = (d, 0.0)
    if зеркало:
        pF1, pN1, pF2, pN2, pK = [(-p[0], p[1]) for p in (pF1, pN1, pF2, pN2, pK)]

    # Самопроверка: продолжения сторон действительно сходятся в K, и K лежит
    # на секущих по ту сторону ближних вершин, как сказано в шаге 1.
    kx, ky = пересечение(pF1, pN1, pF2, pN2)
    assert hypot(kx - pK[0], ky - pK[1]) < 1e-6
    for F, N in ((pF1, pN1), (pF2, pN2)):
        assert hypot(pK[0] - F[0], pK[1] - F[1]) > hypot(pK[0] - N[0], pK[1] - N[1])

    ч = Чертёж(width=440, height=300)
    ч.окружность((0.0, 0.0), R)
    ч.многоугольник([pF1, pN1, pN2, pF2])
    ч.отрезок(pN1, pK, пунктир=True)       # продолжения сторон до K
    ч.отрезок(pN2, pK, пунктир=True)
    ч.дуга_угла(pN2, pK, pN1)              # ∠K N2 N1 — ключевая пара
    ч.дуга_угла(pF1, pK, pF2)              # ∠K F1 F2
    ч.дуга_угла(pN1, pK, pN2, штрихов=2)   # вторая пара — из замечания
    ч.дуга_угла(pF2, pK, pF1, штрихов=2)   # ∠K F2 F1
    O = (0.0, 0.0)
    подписать_вершины(
        ч,
        (pF1, F1, _сторона_прочь(pF1, pN1, pF2, центр=O)),
        (pN1, N1, _сторона_прочь(pN1, pF1, pN2, pK, центр=O)),
        (pN2, N2, _сторона_прочь(pN2, pF2, pN1, pK, центр=O)),
        (pF2, F2, _сторона_прочь(pF2, pN2, pF1, центр=O)),
        (pK, K, _сторона_прочь(pK, pN1, pN2)),
    )

    return {
        'title': 'Вписанный четырёхугольник: подобие треугольников при точке '
                 'пересечения продолжений противоположных сторон',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Сумма противоположных углов вписанного четырёхугольника равна '
            '\\(180^\\circ\\).',
            'Сумма смежных углов равна \\(180^\\circ\\).',
            'Следствие двух предыдущих фактов: внешний угол вписанного '
            'четырёхугольника равен внутреннему углу при противоположной вершине.',
            'Первый признак подобия треугольников: если два угла одного '
            'треугольника соответственно равны двум углам другого, треугольники '
            'подобны.',
        ],
        'params': {
            'вариант': вариант,
            'внешняя_точка': K,
            'продолжаются': в_условии,
            'треугольники': (тр1, тр2),
            'соответствие': пары,
            'чисел_в_условии': None,
            'чертёж': {'R': R, 'd': d, 'h_пологой': h_пологой,
                       'h_крутой': h_крутой, 'крутая_снизу': крутая_снизу,
                       'зеркало': зеркало, 'луч1_нижний': луч1_нижний},
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 23. Выпуклый четырёхугольник: равные углы на одну сторону — вписанность.
# ────────────────────────────────────────────────────────────────────────
#
# Конфигурация. Выпуклый четырёхугольник ABCD с диагоналями AC и BD. Дано,
# что два угла между стороной и диагональю, «смотрящие» на одну и ту же
# сторону из двух оставшихся вершин, равны: например ∠BCA = ∠BDA (оба
# опираются на AB, вершины C и D). Доказать, что равна и другая такая пара —
# углы, опирающиеся на соседнюю сторону: ∠ABD = ∠ACD (оба опираются на AD,
# вершины B и C). Чисел нет совсем: любые градусные меры лишь сузили бы
# задачу, а неудачные — сломали бы выпуклость. Варьируется только разметка:
# какая из четырёх сторон играет роль «хорды», — банк даёт ровно четыре
# переобозначения одной конструкции, и все четыре здесь получаются поворотом
# букв по циклу A→B→C→D. Плюс две равносильные формы условия.
#
# Ключевой ход — «туда и обратно» по теореме о вписанном угле. Обратная
# теорема (признак вписанного четырёхугольника): отрезок AB виден из точек C
# и D, лежащих по одну сторону от него, под равными углами, значит A, B, C, D
# лежат на одной окружности. Прямая теорема: теперь ∠ABD и ∠ACD — вписанные
# углы, опирающиеся на одну дугу AD, значит равны. Окружность в условии не
# упомянута; её нужно «увидеть» — это и есть вся задача.
#
# Почему это работает. Геометрическое место точек одной полуплоскости, из
# которых отрезок виден под данным углом, — дуга окружности с концами в
# концах отрезка. Две точки с равными углами попадают на одну и ту же дугу,
# а через A, B и любую точку этой дуги проходит одна и та же окружность.
# Дальше на этой окружности все четыре пары «углов между стороной и
# диагональю» равны автоматически — задача просит доказать лишь одну из трёх
# оставшихся. Сам признак в доказательстве не выводится, а называется: он
# есть в школьном курсе (Мерзляк, 8 класс) и в официальных разборах ФИПИ
# принимается как известный факт. Если ученик захочет проверить его: проведём
# окружность через A, B, C и допустим, что D не лежит на ней (внутри или
# снаружи — рассуждение одно и то же); луч из середины AB через
# D пересекает окружность в точке E с тем же углом, что у C, а из двух точек
# D и E на одном луче ближняя лежит внутри треугольника с вершинами A, B и
# дальней точкой — и видит AB под бо́льшим углом (внешний угол треугольника).
# Противоречие.
#
# Ловушки.
# * Без выпуклости признак не работает: C и D могли бы лежать по разные
#   стороны от AB, и тогда равные углы ничего не дают (симметричная дуга —
#   другая окружность). Слово «выпуклый» из условия должно попасть в
#   доказательство явно, причём дважды: для полуплоскости относительно AB
#   (шаг с признаком) и относительно AD (шаг с прямой теоремой — иначе
#   вписанные углы могут опираться на разные дуги и давать в сумме 180°).
# * Равные углы обязаны опираться на сторону, а не на диагональ: из
#   ∠ABC = ∠ADC (оба смотрят на диагональ AC с разных сторон) вписанность
#   не следует.
# * Ученики путают «∠BCA» с «∠BAC» — вершина угла стоит в середине записи.
#   На чертеже данные углы помечены одной дужкой, доказываемые — двумя.
# * Чертёж должен быть честным: раз четырёхугольник по сути вписанный,
#   вершины строятся на окружности, а сама окружность показывается пунктиром
#   как результат доказательства, а не как данность.


@сюжет(23)
def _сюжет_23(rng):
    # Роли и буквы. Доказательство написано для ролей A, B, C, D: дано
    # ∠BCA = ∠BDA (хорда AB), доказать ∠ABD = ∠ACD (хорда AD). Поворот букв
    # по циклу на k шагов даёт четыре подтипа банка (хорда AB, BC, CD, AD),
    # при этом сам четырёхугольник по-прежнему зовётся ABCD — циклический
    # сдвиг не меняет порядка обхода.
    буквы = 'ABCD'
    k = rng.randrange(4)
    роль = {r: буквы[(i + k) % 4] for i, r in enumerate(буквы)}
    б = dict(роль)
    # Имена сторон и диагоналей пишем в привычном порядке (AD, а не DA):
    # у сторон и диагоналей ABCD алфавитный порядок букв как раз привычный.
    for пара in ('AB', 'AD', 'AC', 'BD', 'BC', 'CD'):
        б[пара] = ''.join(sorted(роль[пара[0]] + роль[пара[1]]))

    # Две равносильные формы условия: «известно, что углы равны» и
    # «проведены диагонали, оказалось, что углы равны». Диагонали в первой
    # форме подразумеваются — углы BCA и BDA без них не возникают. Банк
    # формулирует «В выпуклом четырёхугольнике ABCD углы BCA и BDA равны.
    # Докажите, что углы ABD и ACD также равны» — эту фразу не повторяем.
    форма = rng.randint(0, 1)
    if форма == 0:
        условие = (
            '<p>Про выпуклый четырёхугольник \\(ABCD\\) известно, что '
            '\\(\\angle %(B)s%(C)s%(A)s = \\angle %(B)s%(D)s%(A)s\\). '
            'Докажите, что '
            '\\(\\angle %(A)s%(B)s%(D)s = \\angle %(A)s%(C)s%(D)s\\).</p>' % б)
    else:
        условие = (
            '<p>В выпуклом четырёхугольнике \\(ABCD\\) проведены диагонали '
            '\\(AC\\) и \\(BD\\). Оказалось, что углы \\(%(B)s%(C)s%(A)s\\) и '
            '\\(%(B)s%(D)s%(A)s\\) равны. Докажите, что тогда равны и углы '
            '\\(%(A)s%(B)s%(D)s\\) и \\(%(A)s%(C)s%(D)s\\).</p>' % б)

    доказательство = (
        '<p>1. Четырёхугольник \\(ABCD\\) выпуклый. По определению выпуклый '
        'многоугольник лежит по одну сторону от каждой прямой, проходящей '
        'через его сторону. Поэтому вершины \\(%(C)s\\) и \\(%(D)s\\) лежат '
        'в одной полуплоскости относительно прямой \\(%(AB)s\\), а вершины '
        '\\(%(B)s\\) и \\(%(C)s\\) — в одной полуплоскости относительно '
        'прямой \\(%(AD)s\\). Первое понадобится сейчас, второе — на '
        'шаге 3.</p>'

        '<p>2. Стороны угла \\(%(B)s%(C)s%(A)s\\) проходят через концы '
        'отрезка \\(%(AB)s\\), то есть отрезок \\(%(AB)s\\) виден из точки '
        '\\(%(C)s\\) под углом \\(%(B)s%(C)s%(A)s\\). Точно так же из точки '
        '\\(%(D)s\\) он виден под углом \\(%(B)s%(D)s%(A)s\\). По условию '
        '\\(\\angle %(B)s%(C)s%(A)s = \\angle %(B)s%(D)s%(A)s\\), а точки '
        '\\(%(C)s\\) и \\(%(D)s\\) лежат по одну сторону от прямой '
        '\\(%(AB)s\\). Применим признак вписанного четырёхугольника '
        '(теорему, обратную теореме о вписанном угле): если отрезок виден '
        'из двух точек, лежащих по одну сторону от прямой, содержащей этот '
        'отрезок, под равными углами, то эти две точки и концы отрезка лежат '
        'на одной окружности. Значит, точки \\(A\\), \\(B\\), \\(C\\), \\(D\\) лежат '
        'на одной окружности; обозначим её '
        '\\(\\omega\\) (на чертеже она проведена пунктиром). Иначе говоря, '
        'около четырёхугольника \\(ABCD\\) можно описать окружность.</p>'

        '<p>3. Углы \\(%(A)s%(B)s%(D)s\\) и \\(%(A)s%(C)s%(D)s\\) — '
        'вписанные в \\(\\omega\\): их вершины \\(%(B)s\\) и \\(%(C)s\\) '
        'лежат на окружности, а стороны пересекают её в точках \\(%(A)s\\) '
        'и \\(%(D)s\\) (содержат хорды \\(%(B)s%(A)s\\), \\(%(B)s%(D)s\\) и '
        '\\(%(C)s%(A)s\\), \\(%(C)s%(D)s\\)). Оба угла '
        'опираются на хорду \\(%(AD)s\\). Точки \\(%(B)s\\) и \\(%(C)s\\) '
        'лежат по одну сторону от прямой \\(%(AD)s\\) (шаг 1), поэтому они '
        'принадлежат одной и той же дуге \\(%(AD)s\\), и оба угла '
        'опираются на другую дугу \\(%(AD)s\\) — '
        'ту, которая не содержит \\(%(B)s\\) и \\(%(C)s\\). По теореме о '
        'вписанном угле вписанный угол измеряется половиной дуги, на которую '
        'он опирается. Оба угла измеряются половиной одной и той же дуги, '
        'следовательно, равны между собой:</p>'
        '\\[\\angle %(A)s%(B)s%(D)s = \\angle %(A)s%(C)s%(D)s,\\]'
        '<p>что и требовалось доказать.</p>' % б)

    # Чертёж. Раз четырёхугольник по сути вписанный, честно строим вершины
    # на окружности радиуса R — тогда данные углы равны на самом деле, а не
    # «примерно». Буквы сидят как в учебнике: A слева внизу, B слева вверху,
    # C справа вверху, D справа внизу, обход по часовой стрелке. Дуги между
    # соседними вершинами нарочно разные (75°, 65°, 120°, 100°): у вписанного
    # четырёхугольника с близкими дугами все углы около 90°, и ученик увидит
    # «почти прямоугольник». Небольшой сдвиг каждой вершины по дуге убирает
    # симметрию, но зазоры между вершинами остаются больше 45°, а порядок
    # обхода не меняется — четырёхугольник выпуклый при любом сиде.
    R = 5.0
    базовые = {'A': 210.0, 'B': 135.0, 'C': 70.0, 'D': 310.0}
    градусы = {л: в + rng.uniform(-8.0, 8.0) for л, в in базовые.items()}
    P = {л: (R * math.cos(math.radians(г)), R * math.sin(math.radians(г)))
         for л, г in градусы.items()}
    A, B, C, D = P['A'], P['B'], P['C'], P['D']
    # Положения ролей: дужки ставятся по ролям, а буквы стоят по местам.
    рA, рB, рC, рD = (P[роль[r]] for r in буквы)

    ч = Чертёж(height=330)
    ч.многоугольник([A, B, C, D])
    ч.отрезок(A, C)                                   # диагонали
    ч.отрезок(B, D)
    ч.окружность((0.0, 0.0), R, пунктир=True, вспомогательная=True)
    # Данные равные углы — одна дужка, доказываемые — две. У роли C дужки
    # обеих пар соседствуют (∠BCA и ∠ACD разделены диагональю CA), поэтому
    # радиусы заметно разные: одинарная снаружи, двойная ближе к вершине,
    # иначе у общего луча CA три конца дужек сливаются в один узел.
    ч.дуга_угла(рC, рB, рA, радиус=1.0)              # ∠BCA
    ч.дуга_угла(рD, рB, рA, радиус=1.0)              # ∠BDA
    ч.дуга_угла(рB, рA, рD, радиус=0.6, штрихов=2)   # ∠ABD
    ч.дуга_угла(рC, рA, рD, радиус=0.6, штрихов=2)   # ∠ACD
    подписать_вершины(ч, (A, 'A', 'юз'), (B, 'B', 'сз'), (C, 'C', 'св'),
                      (D, 'D', 'юв'))
    # Подпись окружности — на свободной дуге CD справа, вдали от вершин.
    ч.подпись((R * math.cos(math.radians(8)), R * math.sin(math.radians(8))),
              'ω', 'в')

    дано = '%(B)s%(C)s%(A)s=%(B)s%(D)s%(A)s' % б
    доказать = '%(A)s%(B)s%(D)s=%(A)s%(C)s%(D)s' % б
    return {
        'title': 'Выпуклый четырёхугольник: равные углы на одну сторону — '
                 'вписанность и вторая пара равных углов',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Выпуклый многоугольник лежит по одну сторону от любой прямой, '
            'содержащей его сторону.',
            'Признак вписанного четырёхугольника (обратная теорема о вписанном '
            'угле): если отрезок виден из двух точек, лежащих по одну сторону '
            'от него, под равными углами, то эти точки и концы отрезка лежат '
            'на одной окружности.',
            'Теорема о вписанном угле: вписанный угол измеряется половиной '
            'дуги, на которую опирается; следствие — вписанные углы, '
            'опирающиеся на одну и ту же дугу, равны.',
        ],
        'params': {
            'поворот_букв': k, 'форма_условия': форма,
            'хорда': б['AB'], 'дано': дано, 'доказать': доказать,
            'углы_вершин_на_окружности': {л: round(г, 1)
                                         for л, г in градусы.items()},
        },
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 24. Две пересекающиеся окружности: линия центров перпендикулярна
# ────────────────────────────────────────────────────────────────────────
#
# общей хорде.
#
# Конфигурация. Две окружности разных радиусов с центрами M и N пересекаются в
# точках S и T; ST — их общая хорда. Требуется доказать, что прямая MN
# перпендикулярна прямой ST. Чисел в сюжете нет: ни радиусы, ни расстояние
# между центрами на доказательство не влияют. В банке дополнительно оговорено,
# что центры лежат по одну сторону от прямой ST, — это лишь фиксирует картинку
# (одна окружность заметно меньше другой и «не перешла» через хорду), а не
# условие теоремы; утверждение верно и для обычной «линзы».
#
# Ключевой ход — равенство треугольников по трём сторонам. MS = MT и NS = NT
# как радиусы, MN — общая, поэтому △SMN = △TMN, откуда ∠SMN = ∠TMN. Значит,
# луч MN — биссектриса угла SMT. Треугольник SMT равнобедренный (MS = MT), а
# биссектриса равнобедренного треугольника, проведённая к основанию, есть
# одновременно медиана и высота. Следовательно, MN ⊥ ST, и попутно основание
# H этой высоты — середина хорды.
#
# Почему это работает. У двух центров есть общее свойство — каждый равноудалён
# от S и T. Оно и означает, что оба лежат на серединном перпендикуляре к ST;
# равенство треугольников — школьный способ «увидеть» это без ссылки на
# теорему о серединном перпендикуляре. Короткий вариант доказательства
# (M и N лежат на серединном перпендикуляре, через две точки проходит одна
# прямая) вынесен в замечание после основного.
#
# Ловушки.
# 1. Нужны углы при центре, а не при точках пересечения. Из △SMN = △TMN
#    следует и ∠MSN = ∠MTN, но это равенство никуда не ведёт: биссектрису
#    даёт именно ∠SMN = ∠TMN — угол при вершине равнобедренного треугольника
#    SMT.
# 2. От какого центра вести доказательство. В посадке «центры по одну сторону
#    от хорды» центр N меньшей окружности лежит между M и хордой, поэтому луч
#    NM направлен от хорды прочь, и фраза «NM — биссектриса треугольника SNT»
#    неверна (биссектриса — луч NH, а NM — его продолжение). От центра большей
#    окружности такой беды нет ни в одной посадке, поэтому доказательство
#    всегда ведётся от него, и на чертеже большей окружности отдан первый из
#    двух центров. Что N лежит внутри угла SMT, в тексте сказано одной фразой:
#    как и всякое утверждение о взаимном расположении, в школьном
#    доказательстве оно берётся с чертежа, строже курс не требует.
# 3. Порочный круг. «Прямая MN проходит через середину хорды, а перпендикуляр
#    из центра делит хорду пополам, значит MN ⊥ ST» — то, что MN проходит через
#    середину, и есть недоказанная часть утверждения. Середина хорды получается
#    как следствие, а не как посылка.
# 4. Чертёж. Окружности пересекаются в двух точках при |R₁ − R₂| < d < R₁ + R₂;
#    центры лежат по одну сторону от хорды только при d² < R₁² − R₂², иначе
#    получится «линза», и картинка разойдётся с текстом условия. Расстояние от
#    M до хорды MH = (d² + R₁² − R₂²)/(2d), полухорда √(R₁² − MH²).
#
# Варьируются буквы (пары центров и точек пересечения), формулировка
# требования (MN ⊥ ST; «прямые перпендикулярны»; «линия центров перпендикулярна
# общей хорде»), посадка (центры по одну сторону от хорды либо линза),
# радиусы и расстояние между центрами для чертежа, зеркальные отражения.


# Пары «центры» + «точки пересечения» из банка и учебников. O_1, O_2 — как в
# Атанасяне; в TeX это O_1, на чертеже — O₁.
_БУКВЫ = [
    ('M', 'N', 'S', 'T'),
    ('I', 'J', 'A', 'B'),
    ('P', 'Q', 'K', 'L'),
    ('E', 'F', 'C', 'D'),
    ('O_1', 'O_2', 'A', 'B'),
]

_ЗЕРКАЛО_СТОРОН = {'з': 'в', 'в': 'з', 'сз': 'св', 'св': 'сз',
                   'юз': 'юв', 'юв': 'юз', 'с': 'с', 'ю': 'ю'}


def _на_чертеже(имя):
    return имя.replace('_1', '₁').replace('_2', '₂')


def _угол_24(a, вершина, b):
    return '\\angle %s%s%s' % (a, вершина, b)


def _подпись_у_пересечения(P, буква, окр1, окр2):
    """Куда ставить букву у точки P, в которой пересекаются две окружности.

    Свободный от линий сектор при P — пересечение двух полуплоскостей,
    внешних к окружностям; его биссектриса — сумма единичных радиус-векторов
    из центров в P. По ней выбирается сторона подписи из восьми стандартных, а
    сама точка привязки чуть сдвигается вдоль биссектрисы, чтобы рамка буквы
    отошла от обеих дуг (в узкой линзе сектор всего ~75°, и штатного отступа
    не хватает). Возвращает аргументы для Чертёж.подпись.
    """
    ux = uy = 0.0
    for центр, R in (окр1, окр2):
        ux += (P[0] - центр[0]) / R
        uy += (P[1] - центр[1]) / R
    L = hypot(ux, uy)
    ux, uy = ux / L, uy / L
    порог = 0.4142                     # tg 22.5°: граница между «ю» и «юв»
    верт = ('с' if uy > 0 else 'ю') if abs(uy) >= порог * abs(ux) else ''
    гориз = ('в' if ux > 0 else 'з') if abs(ux) >= порог * abs(uy) else ''
    сторона = верт + гориз
    # Диагональные стороны уже отстоят от точки дальше вертикальных, поэтому
    # им хватает меньшего сдвига; величины в мировых единицах (~20–25 px/ед.).
    сдвиг = 0.4 if сторона in ('с', 'ю') else 0.15
    return (P[0] + сдвиг * ux, P[1] + сдвиг * uy), буква, сторона


@сюжет(24)
def _сюжет_24(rng):
    M, N, S, T = rng.choice(_БУКВЫ)
    H = 'H'
    MN, ST = M + N, S + T

    # Посадка. «Одна сторона» — центры по одну сторону от хорды, как в банке;
    # иначе обычная линза. Доказательство одно и то же, но текст условия и
    # чертёж обязаны совпадать, поэтому формулировка выбирается после посадки.
    одна_сторона = rng.choice([True, False])
    if одна_сторона:
        формулировка = rng.choice([1, 2])
    else:
        формулировка = rng.choice([3, 4])

    # Банк формулирует так: «Окружности с центрами в точках M и N пересекаются
    # в точках S и T, причём точки M и N лежат по одну сторону от прямой ST.
    # Докажите, что MN ⊥ ST». Все четыре редакции ниже нарочно построены иначе.
    if формулировка == 1:
        условие = (
            '<p>Две окружности, центры которых — точки \\(%s\\) и \\(%s\\), имеют '
            'общую хорду \\(%s\\), причём точки \\(%s\\) и \\(%s\\) расположены по одну '
            'сторону от прямой \\(%s\\). Докажите, что \\(%s \\perp %s\\).</p>'
            % (M, N, ST, M, N, ST, MN, ST))
    elif формулировка == 2:
        условие = (
            '<p>Окружности с центрами \\(%s\\) и \\(%s\\) имеют две общие точки '
            '\\(%s\\) и \\(%s\\), и оба центра лежат по одну сторону от прямой '
            '\\(%s\\). Докажите, что линия центров \\(%s\\) перпендикулярна общей '
            'хорде \\(%s\\).</p>' % (M, N, S, T, ST, MN, ST))
    elif формулировка == 3:
        условие = (
            '<p>Окружности с центрами \\(%s\\) и \\(%s\\) имеют ровно две общие '
            'точки — \\(%s\\) и \\(%s\\). Докажите, что прямая \\(%s\\) перпендикулярна '
            'их общей хорде \\(%s\\).</p>' % (M, N, S, T, MN, ST))
    else:
        условие = (
            '<p>Через точки \\(%s\\) и \\(%s\\) проходят две окружности: одна с '
            'центром \\(%s\\), другая с центром \\(%s\\). Докажите, что прямые '
            '\\(%s\\) и \\(%s\\) перпендикулярны.</p>' % (S, T, M, N, MN, ST))

    доказательство = (
        '<p>1. Точки \\(%(S)s\\) и \\(%(T)s\\) лежат на окружности с центром '
        '\\(%(M)s\\), поэтому \\(%(M)s%(S)s = %(M)s%(T)s\\) как радиусы одной '
        'окружности. Точно так же \\(%(N)s%(S)s = %(N)s%(T)s\\) — радиусы окружности '
        'с центром \\(%(N)s\\).</p>'
        '<p>2. Рассмотрим треугольники \\(%(S)s%(M)s%(N)s\\) и \\(%(T)s%(M)s%(N)s\\). '
        'В них \\(%(M)s%(S)s = %(M)s%(T)s\\) и \\(%(N)s%(S)s = %(N)s%(T)s\\) по шагу 1, '
        'а сторона \\(%(MN)s\\) — общая. Значит, '
        '\\(\\triangle %(S)s%(M)s%(N)s = \\triangle %(T)s%(M)s%(N)s\\) по третьему '
        'признаку равенства треугольников (по трём сторонам). В равных треугольниках '
        'против равных сторон лежат равные углы: против сторон \\(%(N)s%(S)s\\) и '
        '\\(%(N)s%(T)s\\) лежат углы \\(%(S)s%(M)s%(N)s\\) и \\(%(T)s%(M)s%(N)s\\), '
        'поэтому \\(%(aSMN)s = %(aTMN)s\\).</p>'
        '<p>3. Треугольник \\(%(S)s%(M)s%(T)s\\) равнобедренный с основанием '
        '\\(%(ST)s\\), так как \\(%(M)s%(S)s = %(M)s%(T)s\\) (шаг 1). Точка \\(%(N)s\\) '
        'лежит внутри угла \\(%(S)s%(M)s%(T)s\\), поэтому луч \\(%(MN)s\\) проходит '
        'между сторонами этого угла, а по шагу 2 он делит его на два равных угла. '
        'Значит, луч \\(%(MN)s\\) — биссектриса угла \\(%(S)s%(M)s%(T)s\\), то есть '
        'угла при вершине равнобедренного треугольника \\(%(S)s%(M)s%(T)s\\). '
        'Биссектриса угла треугольника пересекает '
        'противоположную сторону; обозначим точку её пересечения с \\(%(ST)s\\) через '
        '\\(%(H)s\\). Тогда \\(%(M)s%(H)s\\) — биссектриса равнобедренного треугольника '
        '\\(%(S)s%(M)s%(T)s\\), проведённая к основанию.</p>'
        '<p>4. По свойству равнобедренного треугольника биссектриса, проведённая к '
        'основанию, является также его медианой и высотой. Следовательно, '
        '\\(%(M)s%(H)s \\perp %(ST)s\\). Точки \\(%(M)s\\), \\(%(N)s\\) и \\(%(H)s\\) '
        'лежат на одной прямой (точка \\(%(H)s\\) взята на луче \\(%(MN)s\\)), поэтому '
        'прямая \\(%(M)s%(H)s\\) — это прямая \\(%(MN)s\\). Итак, '
        '\\(%(MN)s \\perp %(ST)s\\), что и требовалось доказать.</p>'
        '<p><i>Замечание.</i> Попутно получено, что \\(%(H)s\\) — середина '
        '\\(%(ST)s\\): линия центров делит общую хорду пополам. Доказательство можно '
        'провести и короче: точки \\(%(M)s\\) и \\(%(N)s\\) равноудалены от концов '
        'отрезка \\(%(ST)s\\) (шаг 1), поэтому каждая из них лежит на серединном '
        'перпендикуляре к \\(%(ST)s\\); через две различные точки проходит ровно одна '
        'прямая, значит, прямая \\(%(MN)s\\) и есть этот серединный перпендикуляр, '
        'и \\(%(MN)s \\perp %(ST)s\\).</p>'
    ) % {
        'M': M, 'N': N, 'S': S, 'T': T, 'H': H, 'MN': MN, 'ST': ST,
        'aSMN': _угол_24(S, M, N), 'aTMN': _угол_24(T, M, N),
    }

    # Чертёж. Линия центров горизонтальна, хорда вертикальна — как в учебнике.
    # Первый центр M получает большую окружность: доказательство ведётся от
    # него, и луч MN обязан смотреть в сторону хорды (см. ловушку 2 в шапке).
    # Радиусы и расстояние d подбираются в мировых единицах так, чтобы
    # посадка отвечала тексту условия, и это проверяется числом.
    if одна_сторона:
        # Тройки (R1, R2, d) подобраны под три требования сразу: серп меньшей
        # окружности за хордой не тоньше 0.8 ед. (d + R2 − R1), центр N не
        # ближе 1 ед. к хорде (иначе «по одну сторону» не читается) и центр M
        # не ближе 1 ед. к меньшей окружности — при d ≈ R2 точка M ложится
        # на окружность N, и чертёж показывает ложный частный случай (так было
        # у пары (5, 3) с d = 3), а подпись M садится на дугу. R1 = 5 везде:
        # важны только отношения, а масштаб холста задаётся именно R1, и в
        # мировых единицах отступы тогда стоят одинаково в пикселях (~24 px).
        # Для этих троек M внутри меньшей окружности, ближайшая её дуга — со
        # стороны, противоположной N, не ближе 24 px.
        R1, R2, d = rng.choice([
            (5.0, 3.5, 2.3), (5.0, 3.5, 2.4), (5.0, 3.5, 2.5),
            (5.0, 3.75, 2.1), (5.0, 3.75, 2.25), (5.0, 3.75, 2.4),
            (5.0, 4.0, 1.85), (5.0, 4.0, 2.0), (5.0, 4.0, 2.15),
        ])
        assert d + R2 - R1 >= 0.8 - 1e-9, 'серп меньшей окружности слишком тонок'
        assert R2 - d >= 1.0 - 1e-9, 'центр M почти на меньшей окружности'
    else:
        R1, R2 = rng.choice([(5.0, 4.0), (5.0, 3.5), (5.0, 4.5), (4.5, 3.5)])
        # Доля не ниже 0.5: при 0.45 центр N подходил к большой окружности
        # на 0.47 ед. (~10 px), и точка N читалась как лежащая на ней.
        нижняя, верхняя = sqrt(R1 * R1 - R2 * R2), R1 + R2
        d = нижняя + (верхняя - нижняя) * rng.choice([0.5, 0.55, 0.65])
        assert d - R1 >= 0.8 and d - R2 >= 0.8, 'центр почти на чужой окружности'
    assert abs(R1 - R2) < d < R1 + R2, 'окружности не пересекаются в двух точках'

    # Расстояние от M до хорды и полухорда — из теоремы Пифагора для двух
    # прямоугольных треугольников с общим катетом SH.
    MH = (d * d + R1 * R1 - R2 * R2) / (2.0 * d)
    h = sqrt(R1 * R1 - MH * MH)
    if одна_сторона:
        assert MH > d, 'центр N должен лежать между M и хордой'
        assert MH - d >= 1.0, 'центр N слишком близко к хорде'
    else:
        assert 0 < MH < d, 'центры должны лежать по разные стороны от хорды'

    зеркало_x = rng.choice([1, 1, -1])    # большая окружность слева / справа
    зеркало_y = rng.choice([1, -1])       # S сверху / снизу

    def точка(x, y):
        return (зеркало_x * x, зеркало_y * y)

    Mк, Nк, Hк = точка(0.0, 0.0), точка(d, 0.0), точка(MH, 0.0)
    Sк, Tк = точка(MH, h), точка(MH, -h)
    # Контроль: S и T лежат на обеих окружностях, H — середина ST.
    for P in (Sк, Tк):
        assert abs(hypot(P[0] - Mк[0], P[1] - Mк[1]) - R1) < 1e-9
        assert abs(hypot(P[0] - Nк[0], P[1] - Nк[1]) - R2) < 1e-9
    assert hypot(*[a - b for a, b in zip(середина(Sк, Tк), Hк)]) < 1e-9

    ч = Чертёж(width=400, height=300)
    ч.окружность(Mк, R1)
    ч.окружность(Nк, R2)
    ч.отрезок(Mк, Nк)                                  # линия центров
    if одна_сторона:
        # Прямая MN продолжается за N до хорды — продолжение серое пунктирное.
        ч.отрезок(Nк, Hк, пунктир=True, вспомогательный=True)
    ч.отрезок(Sк, Tк)                                  # общая хорда
    # Радиусы — вспомогательное построение, на котором держится доказательство.
    for Ц, P in ((Mк, Sк), (Mк, Tк), (Nк, Sк), (Nк, Tк)):
        ч.отрезок(Ц, P, пунктир=True)
    ч.равенство(Mк, Sк)
    ч.равенство(Mк, Tк)
    ч.равенство(Nк, Sк, штрихов=2)
    ч.равенство(Nк, Tк, штрихов=2)
    ч.дуга_угла(Mк, Sк, Nк, радиус=0.9)
    ч.дуга_угла(Mк, Tк, Nк, радиус=0.9)
    ч.прямой_угол(Hк, Sк, Mк, размер=0.5)

    # Подписи: M и N уводим под линию центров в сторону от своих радиусов
    # (строго под точкой нельзя: радиус MS/MT идёт от M под 40–50° и задевает
    # рамку буквы; слева-снизу в посадке «по одну сторону» ближайшая дуга
    # меньшей окружности не ближе 24 px — это и обеспечивает сетка радиусов).
    # Квадратик прямого угла стоит при H между направлениями на S и на M.
    # В линзе подпись H ставим со стороны M, но по вертикали противоположно
    # S — эта четверть свободна. В посадке «центры по одну сторону» N стоит
    # вплотную к H, и её радиусы NS, NT занимают обе четверти со стороны M,
    # поэтому подпись H уходит на противоположную от M сторону.
    сторона_N = 'юз' if одна_сторона else 'юв'
    сторона_H = 'юв' if одна_сторона else 'юз'
    стороны = {'M': 'юз', 'N': сторона_N, 'H': сторона_H}
    if зеркало_x < 0:
        стороны = {k: _ЗЕРКАЛО_СТОРОН[v] for k, v in стороны.items()}
    if зеркало_y < 0:
        стороны['H'] = 'с' + стороны['H'][1:]        # юз → сз, юв → св
    подписать_вершины(
        ч,
        (Mк, _на_чертеже(M), стороны['M']),
        (Nк, _на_чертеже(N), стороны['N']),
        (Hк, H, стороны['H']),
    )
    # Точки пересечения S и T. Свободный сектор у такой точки зажат двумя
    # дугами и несимметричен: большая окружность уходит от хорды круче, чем
    # меньшая, а в посадке «по одну сторону» серп меньшей вообще смотрит в
    # другую сторону. Подпись строго над/под точкой ложится на дугу большей
    # окружности, поэтому букву выносим по биссектрисе свободного сектора —
    # это сумма единичных радиус-векторов из обоих центров.
    for P, буква in ((Sк, S), (Tк, T)):
        ч.точка(P)
        ч.подпись(*_подпись_у_пересечения(P, буква, (Mк, R1), (Nк, R2)))

    return {
        'title': 'Две пересекающиеся окружности: линия центров перпендикулярна '
                 'общей хорде',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': [
            'Все радиусы одной окружности равны.',
            'Третий признак равенства треугольников: по трём сторонам.',
            'В равных треугольниках против равных сторон лежат равные углы.',
            'В равнобедренном треугольнике биссектриса, проведённая к основанию, '
            'является также медианой и высотой.',
        ],
        'params': {'центры': (M, N), 'точки': (S, T), 'H': H,
                   'одна_сторона': одна_сторона, 'формулировка': формулировка,
                   'R1': R1, 'R2': R2, 'd': round(d, 3),
                   'зеркало_x': зеркало_x, 'зеркало_y': зеркало_y},
    }


# ────────────────────────────────────────────────────────────────────────
# Сюжет 25. Внутренняя общая касательная двух окружностей делит отрезок
# ────────────────────────────────────────────────────────────────────────
#
# центров в отношении радиусов.
#
# Конфигурация. Две окружности лежат одна вне другой: общих точек нет и ни
# одна не находится внутри другой. Только у таких окружностей есть общая
# внутренняя касательная — прямая, касающаяся обеих, от которой окружности
# лежат по разные стороны. Она касается первой окружности в точке A, второй —
# в точке B и пересекает отрезок центров PQ во внутренней точке K. Дано
# отношение PK : KQ = m : n; доказать, что в том же отношении находятся радиусы
# (в другой редакции банка — диаметры) окружностей.
#
# Ключевой ход — дополнительное построение: радиусы PA и QB в точки касания.
# Радиус, проведённый в точку касания, перпендикулярен касательной, поэтому
# треугольники PAK и QBK прямоугольные с прямыми углами при A и B. Их острые
# углы при общей вершине K вертикальные, значит, равны, и треугольники подобны
# по двум углам. Гипотенузы PK и KQ относятся как m : n — так же относятся
# катеты PA и QB, а это и есть радиусы.
#
# Почему это работает. Утверждение — тождество: у любых двух окружностей одна
# вне другой внутренняя касательная делит отрезок центров ровно в отношении
# радиусов (K — центр гомотетии с отрицательным коэффициентом, переводящей
# одну окружность в другую). Поэтому числа m и n свободны: годится любая пара
# положительных чисел, никакой связи между ними не нужно, и генерировать их
# можно без оглядки на совместность. Единственное скрытое условие сидит в
# слове «вне»: расстояние между центрами больше суммы радиусов, иначе
# внутренней касательной нет (при внешнем касании она одна и проходит через
# точку касания, при пересечении — не существует).
#
# Ловушки.
# 1. Прямые углы при A и B — не «видно на чертеже», а свойство касательной.
#    Без ссылки на «радиус перпендикулярен касательной» доказательство не
#    засчитают: это и есть содержательный шаг.
# 2. Треугольники подобны, а не равны: гипотенузы PK и KQ разные (m ≠ n).
#    Попытка доказать равенство заканчивается тупиком.
# 3. Соответствие вершин: P ↔ Q, A ↔ B, K ↔ K. Нужная пропорция — катет к
#    гипотенузе в каждом треугольнике, PA/QB = PK/KQ. Пропорция PA/QB = AK/BK
#    тоже верна, но отношения AK : BK в условии нет, и она никуда не ведёт.
# 4. Углы при K вертикальные лишь потому, что K лежит и между P и Q (дано:
#    касательная пересекает отрезок центров), и между A и B. Второе в
#    решениях банка не обосновывают; здесь это одна фраза: будь A и B по одну
#    сторону от K, острые углы PKA и QKB оказались бы смежными. Для внешней
#    касательной картина иная: точка пересечения с прямой PQ лежит вне
#    отрезка, угол при ней общий, а не вертикальный, — другое доказательство.
#    Ещё тоньше: сами треугольники PAK и QBK невырождены, то есть A ≠ K и
#    B ≠ K. При A = K касательная перпендикулярна PQ, радиус QB ложится на
#    прямую PQ и B = A — общая точка, а её нет. Одна фраза в шаге 1.
# 5. При m = n задача вырождается: окружности равны, K — середина PQ, и
#    доказывать нечего. Поэтому m ≠ n.
# 6. Редакция «диаметры относятся как m : n» — тот же вывод плюс одна строка:
#    диаметр вдвое больше радиуса, двойка сокращается.
#
# Варьируется отношение m : n (взаимно простые, m ≠ n, не более чем втрое
# разные, чтобы меньшая окружность на чертеже не превращалась в точку), буквы
# центров (P и Q, M и N, O₁ и O₂), буква точки пересечения (K или O), вводная
# фраза и требование (радиусы либо диаметры). Чертёж строится в пропорциях
# r₁ : r₂ = m : n, так что точка K делит отрезок центров ровно как в условии;
# касательная случайно отражается «сверху вниз» или «снизу вверх».


@сюжет(25)
def _сюжет_25(rng):
    # Отношение m : n. Ограничения только «эстетические»: взаимно простые,
    # чтобы дробь не сокращалась на глазах у ученика; m ≠ n, иначе окружности
    # равны и доказывать нечего; не более чем втрое разные, иначе меньшая
    # окружность на чертеже становится точкой. Математических ограничений
    # нет — утверждение верно для любых положительных m и n.
    while True:
        m = rng.randint(1, 9)
        n = rng.randint(1, 9)
        if m != n and gcd(m, n) == 1 and max(m, n) <= 3 * min(m, n):
            break

    # Буквы. Центры — как в разных задачах банка; точка пересечения — K,
    # а при центрах без буквы O иногда O (так тоже пишут).
    центр1, центр2, центр1_svg, центр2_svg = rng.choice([
        ('P', 'Q', 'P', 'Q'),
        ('M', 'N', 'M', 'N'),
        ('O_1', 'O_2', 'O₁', 'O₂'),
    ])
    точка = 'K' if центр1.startswith('O') else rng.choice(['K', 'K', 'O'])
    про_диаметры = rng.random() < 0.5

    б = {'P': центр1, 'Q': центр2, 'K': точка, 'm': m, 'n': n,
         'что': 'диаметры' if про_диаметры else 'радиусы'}

    вводная = rng.choice([
        'Окружности с центрами \\(%(P)s\\) и \\(%(Q)s\\) лежат одна вне другой; '
        'их общая внутренняя касательная касается',
        'Две окружности с центрами \\(%(P)s\\) и \\(%(Q)s\\) расположены так, что '
        'каждая из них лежит вне другой; их общая внутренняя касательная касается',
    ])
    условие = (
        '<p>' + вводная + ' окружности с центром \\(%(P)s\\) в точке \\(A\\), '
        'окружности с центром \\(%(Q)s\\) — в точке \\(B\\) и пересекает отрезок '
        '\\(%(P)s%(Q)s\\) в точке \\(%(K)s\\), причём '
        '\\(%(P)s%(K)s : %(K)s%(Q)s = %(m)d : %(n)d\\). '
        'Докажите, что %(что)s окружностей с центрами \\(%(P)s\\) и \\(%(Q)s\\) '
        'относятся как \\(%(m)d : %(n)d\\).</p>') % б

    доказательство = (
        '<p>1. Проведём радиусы \\(%(P)sA\\) и \\(%(Q)sB\\) в точки касания — '
        'это дополнительное построение, на котором держится всё доказательство '
        '(на чертеже они пунктирные). Радиус, проведённый в точку касания, '
        'перпендикулярен касательной, поэтому \\(%(P)sA \\perp AB\\) и '
        '\\(%(Q)sB \\perp AB\\), то есть '
        '\\(\\angle %(P)sA%(K)s = \\angle %(Q)sB%(K)s = 90^\\circ\\). '
        'Точки \\(A\\) и \\(B\\) отличны от \\(%(K)s\\): будь, скажем, \\(A = %(K)s\\), '
        'касательная была бы перпендикулярна прямой \\(%(P)s%(Q)s\\), тогда и '
        'перпендикулярный ей радиус \\(%(Q)sB\\) лежал бы на прямой \\(%(P)s%(Q)s\\), '
        'а точка \\(B\\) — общая точка касательной и прямой \\(%(P)s%(Q)s\\) — '
        'совпала бы с \\(A\\); но общих точек у окружностей нет. '
        'Итак, треугольники \\(%(P)sA%(K)s\\) и \\(%(Q)sB%(K)s\\) прямоугольные '
        'с гипотенузами \\(%(P)s%(K)s\\) и \\(%(K)s%(Q)s\\).</p>'
        '<p>2. По условию точка \\(%(K)s\\) лежит на отрезке \\(%(P)s%(Q)s\\), '
        'значит, лучи \\(%(K)s%(P)s\\) и \\(%(K)s%(Q)s\\) дополнительные. '
        'Точки \\(A\\) и \\(B\\) лежат по разные стороны от \\(%(K)s\\): иначе '
        'лучи \\(%(K)sA\\) и \\(%(K)sB\\) совпали бы, углы \\(%(P)s%(K)sA\\) и '
        '\\(%(Q)s%(K)sB\\) оказались бы смежными с суммой \\(180^\\circ\\), '
        'а это невозможно для двух острых углов прямоугольных треугольников. '
        'Поэтому лучи \\(%(K)sA\\) и \\(%(K)sB\\) тоже дополнительные, углы '
        '\\(%(P)s%(K)sA\\) и \\(%(Q)s%(K)sB\\) вертикальные, а вертикальные углы '
        'равны: \\(\\angle %(P)s%(K)sA = \\angle %(Q)s%(K)sB\\).</p>'
        '<p>3. У треугольников \\(%(P)sA%(K)s\\) и \\(%(Q)sB%(K)s\\) по два '
        'соответственно равных угла: '
        '\\(\\angle %(P)sA%(K)s = \\angle %(Q)sB%(K)s = 90^\\circ\\) (шаг 1) '
        'и \\(\\angle %(P)s%(K)sA = \\angle %(Q)s%(K)sB\\) (шаг 2). По первому '
        'признаку подобия \\(\\triangle %(P)sA%(K)s \\sim \\triangle %(Q)sB%(K)s\\); '
        'вершине \\(%(P)s\\) соответствует \\(%(Q)s\\), вершине \\(A\\) — \\(B\\), '
        'вершина \\(%(K)s\\) общая.</p>'
        '<p>4. Сходственные стороны подобных треугольников пропорциональны. '
        'Катет \\(%(P)sA\\) лежит против угла \\(%(P)s%(K)sA\\), катет \\(%(Q)sB\\) — '
        'против равного ему угла \\(%(Q)s%(K)sB\\); гипотенузы \\(%(P)s%(K)s\\) и '
        '\\(%(K)s%(Q)s\\) лежат против прямых углов. Значит,</p>'
        '\\[\\frac{%(P)sA}{%(Q)sB} = \\frac{%(P)s%(K)s}{%(K)s%(Q)s} = '
        '\\frac{%(m)d}{%(n)d}.\\]') % б

    if про_диаметры:
        доказательство += (
            '<p>5. \\(%(P)sA = r_1\\) и \\(%(Q)sB = r_2\\) — радиусы окружностей '
            'с центрами \\(%(P)s\\) и \\(%(Q)s\\), поэтому \\(r_1 : r_2 = %(m)d : %(n)d\\). '
            'Диаметр вдвое больше радиуса: \\(d_1 = 2r_1\\), \\(d_2 = 2r_2\\), '
            'откуда</p>'
            '\\[\\frac{d_1}{d_2} = \\frac{2r_1}{2r_2} = \\frac{r_1}{r_2} = '
            '\\frac{%(m)d}{%(n)d}.\\]'
            '<p>Диаметры относятся как \\(%(m)d : %(n)d\\), что и требовалось '
            'доказать.</p>') % б
    else:
        доказательство += (
            '<p>5. \\(%(P)sA = r_1\\) и \\(%(Q)sB = r_2\\) — радиусы окружностей '
            'с центрами \\(%(P)s\\) и \\(%(Q)s\\). Итак, \\(r_1 : r_2 = %(m)d : %(n)d\\), '
            'что и требовалось доказать.</p>') % б

    # Чертёж. Радиусы берём в отношении m : n — тогда касательная делит
    # отрезок центров ровно как в условии, и картинка не спорит с текстом.
    # Сумма радиусов нормирована, поэтому масштаб, размер квадратиков и
    # дужек от сида не зависят.
    r1 = 5.0 * m / (m + n)
    r2 = 5.0 * n / (m + n)
    d = 1.6 * (r1 + r2)          # больше суммы радиусов: одна вне другой
    P, Q = (0.0, 0.0), (d, 0.0)
    # Радиус в точку касания наклонён к линии центров под углом с косинусом
    # (r1 + r2)/d — одинаковым для обеих окружностей; потому касательная и
    # проходит через одну точку отрезка PQ.
    c = (r1 + r2) / d
    s = sqrt(1.0 - c * c)
    верх = rng.random() < 0.5    # касательная идёт сверху вниз или наоборот
    знак = 1.0 if верх else -1.0
    A = (r1 * c, знак * r1 * s)
    B = (d - r2 * c, -знак * r2 * s)
    K = пересечение(A, B, P, Q)  # получается d·m/(m+n): деление как в условии

    # Касательную рисуем чуть длиннее отрезка AB, чтобы она читалась как прямая.
    длина = sqrt((A[0] - B[0]) ** 2 + (A[1] - B[1]) ** 2)
    u = ((A[0] - B[0]) / длина, (A[1] - B[1]) / длина)
    хвост = 0.8
    A_дальше = (A[0] + хвост * u[0], A[1] + хвост * u[1])
    B_дальше = (B[0] - хвост * u[0], B[1] - хвост * u[1])

    ч = Чертёж()
    ч.окружность(P, r1)
    ч.окружность(Q, r2)
    ч.отрезок(P, Q)
    ч.отрезок(A_дальше, B_дальше)
    ч.отрезок(P, A, пунктир=True)     # дополнительное построение
    ч.отрезок(Q, B, пунктир=True)
    ч.прямой_угол(A, P, K, размер=0.4)
    ч.прямой_угол(B, Q, K, размер=0.4)
    ч.дуга_угла(K, P, A)
    ч.дуга_угла(K, Q, B)
    # Подписи — наружу от линий: у центров прочь от радиуса и линии центров,
    # у точек касания — наружу окружности, у K — в свободный сектор.
    подписать_вершины(
        ч,
        (P, центр1_svg, 'юз' if верх else 'сз'),
        (Q, центр2_svg, 'св' if верх else 'юв'),
        (A, 'A', 'св' if верх else 'юв'),
        (B, 'B', 'юз' if верх else 'сз'),
        (K, точка, 'св' if верх else 'юв'),
    )

    факты = [
        'Радиус, проведённый в точку касания, перпендикулярен касательной.',
        'Вертикальные углы равны; смежные углы в сумме дают \\(180^\\circ\\).',
        'Первый признак подобия: если два угла одного треугольника соответственно '
        'равны двум углам другого, треугольники подобны; сходственные стороны '
        'подобных треугольников пропорциональны.',
    ]
    if про_диаметры:
        факты.append('Диаметр окружности равен удвоенному радиусу.')

    return {
        'title': 'Две окружности: внутренняя касательная делит отрезок центров '
                 'в отношении радиусов',
        'statement_html': условие,
        'proof_html': доказательство,
        'figure': ч,
        'facts': факты,
        'params': {
            'm': m, 'n': n,
            # Радиусы, при которых чертёж согласован с условием; годятся любые
            # положительные с r1 : r2 = m : n.
            'r1': m, 'r2': n,
            'соотношение': '%s%s : %s%s = r1 : r2 = %d : %d'
                           % (центр1, точка, точка, центр2, m, n),
            'диаметры': про_диаметры,
        },
    }
